(205465,'rec_93d92ba856914bf9a397ef4e','ext_a12514f62b504a76a367c734f9a5f154','2192fcaa-96cc-4314-b3cd-57a65aa1e34c.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/b4b2cce4bbd8409d8eb766835f888107.mp3',2,102,'mp3',102960,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎哎，","beginTime":0,"endTime":2070,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":2070,"endTime":2452,"channelId":0},{"speakerRole":"agent","index":2,"text":"是那个赵先生是吧，","beginTime":2452,"endTime":3980,"channelId":0},{"speakerRole":"agent","index":3,"text":"到底什么呢？","beginTime":4440,"endTime":5480,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎，","beginTime":5720,"endTime":5906,"channelId":0},{"speakerRole":"agent","index":5,"text":"这边是支付宝的，","beginTime":5906,"endTime":7209,"channelId":0},{"speakerRole":"agent","index":6,"text":"就是您呃早上提交的那个心理车站，","beginTime":7209,"endTime":10002,"channelId":0},{"speakerRole":"agent","index":7,"text":"呃，","beginTime":10002,"endTime":10188,"channelId":0},{"speakerRole":"agent","index":8,"text":"车子已经通过了，","beginTime":10188,"endTime":11491,"channelId":0},{"speakerRole":"agent","index":9,"text":"有八万七千六的一个额度。","beginTime":11491,"endTime":13540,"channelId":0},{"speakerRole":"agent","index":10,"text":"这个月e尾号五q的车辆是您本人，","beginTime":13780,"endTime":16464,"channelId":0},{"speakerRole":"agent","index":11,"text":"你知道吗？","beginTime":16464,"endTime":17180,"channelId":0},{"speakerRole":"agent","index":12,"text":"啊，","beginTime":17920,"endTime":18125,"channelId":0},{"speakerRole":"agent","index":13,"text":"对呀，","beginTime":18125,"endTime":18535,"channelId":0},{"speakerRole":"agent","index":14,"text":"现在车子是全款还是说有按揭贷款呢？","beginTime":18535,"endTime":21820,"channelId":0},{"speakerRole":"agent","index":15,"text":"呃，","beginTime":22360,"endTime":22577,"channelId":0},{"speakerRole":"agent","index":16,"text":"我不用了，","beginTime":22577,"endTime":23447,"channelId":0},{"speakerRole":"agent","index":17,"text":"别问了啊，","beginTime":23447,"endTime":25240,"channelId":0},{"speakerRole":"agent","index":18,"text":"我不用了，","beginTime":25480,"endTime":26146,"channelId":0},{"speakerRole":"agent","index":19,"text":"你不用问了。","beginTime":26146,"endTime":26980,"channelId":0},{"speakerRole":"agent","index":20,"text":"您是觉得利息高了吗？","beginTime":27220,"endTime":29140,"channelId":0},{"speakerRole":"agent","index":21,"text":"百分之二十三，","beginTime":30000,"endTime":31057,"channelId":0},{"speakerRole":"agent","index":22,"text":"这的话会高高利贷一点。","beginTime":31057,"endTime":32820,"channelId":0},{"speakerRole":"agent","index":23,"text":"他那个是三年的总利息啊，","beginTime":33380,"endTime":35294,"channelId":0},{"speakerRole":"agent","index":24,"text":"赵先生如果说拆分成一年的话，","beginTime":35294,"endTime":37556,"channelId":0},{"speakerRole":"agent","index":25,"text":"平均下来也只有十三点六八的利率啊，","beginTime":37556,"endTime":40340,"channelId":0},{"speakerRole":"agent","index":26,"text":"这个比那个什么借呗和信用卡都要便宜的。","beginTime":40580,"endTime":43581,"channelId":0},{"speakerRole":"agent","index":27,"text":"一万一天的话，","beginTime":43581,"endTime":44582,"channelId":0},{"speakerRole":"agent","index":28,"text":"最高的话是三块八。","beginTime":44582,"endTime":45916,"channelId":0},{"speakerRole":"agent","index":29,"text":"我们现在就是还有那个降息活动，","beginTime":45916,"endTime":48251,"channelId":0},{"speakerRole":"agent","index":30,"text":"利息加起来之后，","beginTime":48251,"endTime":49419,"channelId":0},{"speakerRole":"agent","index":31,"text":"您这个合适再使用吗？","beginTime":49419,"endTime":50920,"channelId":0},{"speakerRole":"agent","index":32,"text":"额度太低了，","beginTime":51640,"endTime":52740,"channelId":0},{"speakerRole":"agent","index":33,"text":"不要这个车的话，","beginTime":52740,"endTime":54820,"channelId":0},{"speakerRole":"agent","index":34,"text":"它是根据您车子的一个生意价值来评估的呀。","beginTime":54820,"endTime":57788,"channelId":0},{"speakerRole":"agent","index":35,"text":"您车子现在是十一万左右的那个估价嘛，","beginTime":57788,"endTime":60443,"channelId":0},{"speakerRole":"agent","index":36,"text":"然后我们现在额度是八万七千六，","beginTime":60443,"endTime":62629,"channelId":0},{"speakerRole":"agent","index":37,"text":"就差不多七八成的那个估价嘛。","beginTime":62629,"endTime":64660,"channelId":0},{"speakerRole":"agent","index":38,"text":"嗯嗯，","beginTime":65280,"endTime":67020,"channelId":0},{"speakerRole":"agent","index":39,"text":"您看考不考虑嘛，","beginTime":68060,"endTime":69292,"channelId":0},{"speakerRole":"agent","index":40,"text":"我这边给您申请把利息降下来。","beginTime":69292,"endTime":71580,"channelId":0},{"speakerRole":"agent","index":41,"text":"啊，","beginTime":74040,"endTime":74242,"channelId":0},{"speakerRole":"agent","index":42,"text":"那你先去申请呃，","beginTime":74242,"endTime":76236,"channelId":0},{"speakerRole":"agent","index":43,"text":"您这边要提交资料啊，","beginTime":76236,"endTime":77641,"channelId":0},{"speakerRole":"agent","index":44,"text":"我这边后台还看不到工单，","beginTime":77641,"endTime":79360,"channelId":0},{"speakerRole":"agent","index":45,"text":"因为呃现在只是一个初审的额度嘛，","beginTime":79360,"endTime":81702,"channelId":0},{"speakerRole":"agent","index":46,"text":"您这边要通过终审之后，","beginTime":81702,"endTime":83264,"channelId":0},{"speakerRole":"agent","index":47,"text":"这个钱才可以确定确定借得出来是这样子的。","beginTime":83264,"endTime":86232,"channelId":0},{"speakerRole":"agent","index":48,"text":"只需要上传那个行驶证和绿本照片就可以了。","beginTime":86232,"endTime":89200,"channelId":0},{"speakerRole":"agent","index":49,"text":"嗯，","beginTime":90380,"endTime":90537,"channelId":0},{"speakerRole":"agent","index":50,"text":"好，","beginTime":90537,"endTime":90695,"channelId":0},{"speakerRole":"agent","index":51,"text":"我知道了。","beginTime":90695,"endTime":91326,"channelId":0},{"speakerRole":"agent","index":52,"text":"嗯，","beginTime":91326,"endTime":91483,"channelId":0},{"speakerRole":"agent","index":53,"text":"好好点中心那个去借款就可以了。","beginTime":91483,"endTime":93691,"channelId":0},{"speakerRole":"agent","index":54,"text":"我稍后添加一下您的微信嘛，","beginTime":93691,"endTime":95583,"channelId":0},{"speakerRole":"agent","index":55,"text":"因为后台资料审核和放款都是我这边来负责。","beginTime":95583,"endTime":98580,"channelId":0},{"speakerRole":"agent","index":56,"text":"嗯，","beginTime":99140,"endTime":99336,"channelId":0},{"speakerRole":"agent","index":57,"text":"好好好，","beginTime":99336,"endTime":99925,"channelId":0},{"speakerRole":"agent","index":58,"text":"嗯嗯，","beginTime":99925,"endTime":100317,"channelId":0},{"speakerRole":"agent","index":59,"text":"好好打扰了哈，","beginTime":100317,"endTime":101495,"channelId":0},{"speakerRole":"agent","index":60,"text":"哎再见哈嗯。","beginTime":101495,"endTime":102940,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:10:32','2026-05-22 01:10:34','2026-05-22 01:10:31','2026-05-22 01:10:34','system','system','BATCH-20260522-030772',NULL),
(205466,'rec_1b213c5567864185a93618c3','ext_e8b5f40fa78a4207af7da5564f31212a','9854e1db-3654-4209-ab46-45e5c48e1251.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/fe4e0ef484b94b4e875458a3f5f1bcab.mp3',2,176,'mp3',176904,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎，","beginTime":2120,"endTime":2298,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":2298,"endTime":2654,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问是哎，","beginTime":2654,"endTime":3367,"channelId":0},{"speakerRole":"agent","index":3,"text":"你好，","beginTime":3367,"endTime":3724,"channelId":0},{"speakerRole":"agent","index":4,"text":"请问是尾号三八二幺的丁先生吗？","beginTime":3724,"endTime":6220,"channelId":0},{"speakerRole":"agent","index":5,"text":"对，","beginTime":6500,"endTime":7220,"channelId":0},{"speakerRole":"agent","index":6,"text":"哎，","beginTime":7600,"endTime":7775,"channelId":0},{"speakerRole":"agent","index":7,"text":"你好，","beginTime":7775,"endTime":8125,"channelId":0},{"speakerRole":"agent","index":8,"text":"我这边是这个支付宝新选车贷的客户经理，","beginTime":8125,"endTime":11278,"channelId":0},{"speakerRole":"agent","index":9,"text":"就看您早早上八点十七的时候，","beginTime":11278,"endTime":13555,"channelId":0},{"speakerRole":"agent","index":10,"text":"有在支付宝提交的这个车主贷。","beginTime":13555,"endTime":15832,"channelId":0},{"speakerRole":"agent","index":11,"text":"然后这边来电的话，","beginTime":15832,"endTime":17233,"channelId":0},{"speakerRole":"agent","index":12,"text":"是协助您这边办理下款的哦，","beginTime":17233,"endTime":20563,"channelId":0},{"speakerRole":"agent","index":13,"text":"这怎么办呀？","beginTime":20563,"endTime":21980,"channelId":0},{"speakerRole":"agent","index":14,"text":"嗯您这边的话，","beginTime":22540,"endTime":23508,"channelId":0},{"speakerRole":"agent","index":15,"text":"现在是需要在这个支付宝上面上传您的行驶证和绿本的一个照片，","beginTime":23508,"endTime":28026,"channelId":0},{"speakerRole":"agent","index":16,"text":"过一下最终的这个人选哦啊我们具体住具体住址，","beginTime":28026,"endTime":34223,"channelId":0},{"speakerRole":"agent","index":17,"text":"那些需要填的填吗？","beginTime":34223,"endTime":36242,"channelId":0},{"speakerRole":"agent","index":18,"text":"嗯，","beginTime":36242,"endTime":36495,"channelId":0},{"speakerRole":"agent","index":19,"text":"需要他是最开始的话，","beginTime":36495,"endTime":39765,"channelId":0},{"speakerRole":"agent","index":20,"text":"你要点那个去借款，","beginTime":39765,"endTime":41302,"channelId":0},{"speakerRole":"agent","index":21,"text":"然后点确认，","beginTime":41302,"endTime":42262,"channelId":0},{"speakerRole":"agent","index":22,"text":"然后对应的填这个地址和呃，","beginTime":42262,"endTime":44568,"channelId":0},{"speakerRole":"agent","index":23,"text":"填这个信息，","beginTime":44568,"endTime":45529,"channelId":0},{"speakerRole":"agent","index":24,"text":"然后上传行驶证和绿本的一个照片过一下最终的这个人选。","beginTime":45529,"endTime":50333,"channelId":0},{"speakerRole":"agent","index":25,"text":"嗯，","beginTime":50333,"endTime":50525,"channelId":0},{"speakerRole":"agent","index":26,"text":"这个没有影响的哈。","beginTime":50525,"endTime":52062,"channelId":0},{"speakerRole":"agent","index":27,"text":"您填这个地址是没有影响的，","beginTime":52062,"endTime":54368,"channelId":0},{"speakerRole":"agent","index":28,"text":"他不是说嗯要去上门什么什么的，","beginTime":54368,"endTime":57058,"channelId":0},{"speakerRole":"agent","index":29,"text":"不是说不是说这个意思。","beginTime":57058,"endTime":58980,"channelId":0},{"speakerRole":"agent","index":30,"text":"哎，","beginTime":59460,"endTime":59682,"channelId":0},{"speakerRole":"agent","index":31,"text":"我我知道哎哎哎，","beginTime":59682,"endTime":61238,"channelId":0},{"speakerRole":"agent","index":32,"text":"然后我是丽宁，","beginTime":61238,"endTime":62572,"channelId":0},{"speakerRole":"agent","index":33,"text":"一般是一般是多一般是多少，","beginTime":62572,"endTime":65240,"channelId":0},{"speakerRole":"agent","index":34,"text":"呃，","beginTime":65480,"endTime":65679,"channelId":0},{"speakerRole":"agent","index":35,"text":"利率的话一般是巴黎四到一分五八之间。","beginTime":65679,"endTime":69074,"channelId":0},{"speakerRole":"agent","ind