(205481,'rec_8f386ca8bc56484888598635','ext_623fe4a054fc489299f3796922fc7bf5','4baee12d-bce4-43c3-bbb2-4e2efaea8ade.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/75c559524cbe445ba34354eff169f246.mp3',2,73,'mp3',73440,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂喂，","beginTime":1940,"endTime":3383,"channelId":0},{"speakerRole":"agent","index":1,"text":"是汤先生吗？","beginTime":3383,"endTime":4700,"channelId":0},{"speakerRole":"agent","index":2,"text":"哪里哦，","beginTime":5040,"endTime":6335,"channelId":0},{"speakerRole":"agent","index":3,"text":"我这边是支付宝申请车贷的，","beginTime":6335,"endTime":8435,"channelId":0},{"speakerRole":"agent","index":4,"text":"我看您有登录后台，","beginTime":8435,"endTime":9835,"channelId":0},{"speakerRole":"agent","index":5,"text":"您这笔资金打算要用了吗？","beginTime":9835,"endTime":11760,"channelId":0},{"speakerRole":"agent","index":6,"text":"太多了，","beginTime":13740,"endTime":14650,"channelId":0},{"speakerRole":"agent","index":7,"text":"不敢动。","beginTime":14650,"endTime":15560,"channelId":0},{"speakerRole":"agent","index":8,"text":"嗯，","beginTime":15920,"endTime":16190,"channelId":0},{"speakerRole":"agent","index":9,"text":"什么态度了，","beginTime":16190,"endTime":17540,"channelId":0},{"speakerRole":"agent","index":10,"text":"你一借借十九万哦哦，","beginTime":17960,"endTime":20147,"channelId":0},{"speakerRole":"agent","index":11,"text":"你说额度太多了是吧，","beginTime":20147,"endTime":22335,"channelId":0},{"speakerRole":"agent","index":12,"text":"那您要用多少钱呢？","beginTime":22335,"endTime":24280,"channelId":0},{"speakerRole":"agent","index":13,"text":"一两万块钱吧，","beginTime":26000,"endTime":27380,"channelId":0},{"speakerRole":"agent","index":14,"text":"两万块钱可嗯也是可以的，","beginTime":27680,"endTime":29598,"channelId":0},{"speakerRole":"agent","index":15,"text":"你你可以在那个支付宝那边改一下金额就好了呀。","beginTime":29598,"endTime":33260,"channelId":0},{"speakerRole":"agent","index":16,"text":"哪一个在那个支付宝那里有那个额度，","beginTime":33640,"endTime":37135,"channelId":0},{"speakerRole":"agent","index":17,"text":"不是二十万吗？","beginTime":37135,"endTime":38028,"channelId":0},{"speakerRole":"agent","index":18,"text":"你可以点一下那个数字，","beginTime":38028,"endTime":39517,"channelId":0},{"speakerRole":"agent","index":19,"text":"它是可以改的呀。","beginTime":39517,"endTime":40560,"channelId":0},{"speakerRole":"agent","index":20,"text":"它显示最低的一次性变成两万了。","beginTime":42880,"endTime":46880,"channelId":0},{"speakerRole":"agent","index":21,"text":"嗯嗯，","beginTime":47220,"endTime":48507,"channelId":0},{"speakerRole":"agent","index":22,"text":"如果您近期要用钱的话，","beginTime":48507,"endTime":50179,"channelId":0},{"speakerRole":"agent","index":23,"text":"我可以和支付宝运营那边讲一下，","beginTime":50179,"endTime":52520,"channelId":0},{"speakerRole":"agent","index":24,"text":"让他把您的额度修改一下。","beginTime":52520,"endTime":54359,"channelId":0},{"speakerRole":"agent","index":25,"text":"但是我们是最低是两万起借的那我给您改一下两万好不好？","beginTime":54359,"endTime":58540,"channelId":0},{"speakerRole":"agent","index":26,"text":"先不用嘛先先不用了，","beginTime":61080,"endTime":64165,"channelId":0},{"speakerRole":"agent","index":27,"text":"那你你你要在别的地方看一下是吧嗯。","beginTime":64165,"endTime":68640,"channelId":0},{"speakerRole":"agent","index":28,"text":"什么。","beginTime":71900,"endTime":73420,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:11:25','2026-05-22 01:11:26','2026-05-22 01:11:22','2026-05-22 01:11:26','system','system','BATCH-20260522-030772',NULL),
(205482,'rec_4c4e5900c810434780d8e54a','ext_f6ec0b5defbb4971a507da8986e4440a','5a1e6799-e037-49da-95ab-0f7d4b956359.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/1cec38157b524a998714d68c670cbbae.mp3',2,125,'mp3',125136,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎，","beginTime":1300,"endTime":1510,"channelId":0},{"speakerRole":"agent","index":1,"text":"喂，","beginTime":1510,"endTime":1721,"channelId":0},{"speakerRole":"agent","index":2,"text":"你好哎，","beginTime":1721,"endTime":2353,"channelId":0},{"speakerRole":"agent","index":3,"text":"你好，","beginTime":2353,"endTime":2775,"channelId":0},{"speakerRole":"agent","index":4,"text":"是罗先生，","beginTime":2775,"endTime":3618,"channelId":0},{"speakerRole":"agent","index":5,"text":"对吗？","beginTime":3618,"endTime":4040,"channelId":0},{"speakerRole":"agent","index":6,"text":"嗯，","beginTime":4280,"endTime":4960,"channelId":0},{"speakerRole":"agent","index":7,"text":"哎，","beginTime":5200,"endTime":5422,"channelId":0},{"speakerRole":"agent","index":8,"text":"罗先生您好，","beginTime":5422,"endTime":6535,"channelId":0},{"speakerRole":"agent","index":9,"text":"我这边是支付宝先生直贷的。","beginTime":6535,"endTime":9205,"channelId":0},{"speakerRole":"agent","index":10,"text":"这边看到您呃，","beginTime":9205,"endTime":10540,"channelId":0},{"speakerRole":"agent","index":11,"text":"就今天提交的那个车主代码就给您通过了三万多的额度。","beginTime":12060,"endTime":16278,"channelId":0},{"speakerRole":"agent","index":12,"text":"您看需要现在谁跟您办理不那个嗯。","beginTime":16278,"endTime":20600,"channelId":0},{"speakerRole":"agent","index":13,"text":"嗯嗯嗯，","beginTime":22800,"endTime":28420,"channelId":0},{"speakerRole":"agent","index":14,"text":"这个是你说我我看那个这个嗯那个是发个电话啊，","beginTime":28700,"endTime":40533,"channelId":0},{"speakerRole":"agent","index":15,"text":"啊，","beginTime":40533,"endTime":40766,"channelId":0},{"speakerRole":"agent","index":16,"text":"你说什么，","beginTime":40766,"endTime":41700,"channelId":0},{"speakerRole":"agent","index":17,"text":"你看那个还款期限是三年是吧？","beginTime":42000,"endTime":44980,"channelId":0},{"speakerRole":"agent","index":18,"text":"对，","beginTime":44980,"endTime":45209,"channelId":0},{"speakerRole":"agent","index":19,"text":"是的，","beginTime":45209,"endTime":45667,"channelId":0},{"speakerRole":"agent","index":20,"text":"三年。","beginTime":45667,"endTime":46126,"channelId":0},{"speakerRole":"agent","index":21,"text":"那可以提前还款的嗯，","beginTime":46126,"endTime":48726,"channelId":0},{"speakerRole":"agent","index":22,"text":"提前还款怎么算呢？","beginTime":48726,"endTime":50540,"channelId":0},{"speakerRole":"agent","index":23,"text":"嗯，","beginTime":51440,"endTime":51655,"channelId":0},{"speakerRole":"agent","index":24,"text":"如果是您用满了一年过后的话，","beginTime":51655,"endTime":54454,"channelId":0},{"speakerRole":"agent","index":25,"text":"就没有任何违约金的。","beginTime":54454,"endTime":56391,"channelId":0},{"speakerRole":"agent","index":26,"text":"如果在一年以内的话，","beginTime":56391,"endTime":58329,"channelId":0},{"speakerRole":"agent","index":27,"text":"就是整天的百分之四本金的谈论。","beginTime":58329,"endTime":63006,"channelId":0},{"speakerRole":"agent","index":28,"text":"嗯，","beginTime":63006,"endTime":63300,"channelId":0},{"speakerRole":"agent","index":29,"text":"对，","beginTime":63300,"endTime":63593,"channelId":0},{"speakerRole":"agent","index":30,"text":"是的，","beginTime":63593,"endTime":64180,"channelId":0},{"speakerRole":"agent","index":31,"text":"你也可以就是说用用完一年过后啊，","beginTime":65200,"endTime":67865,"channelId":0},{"speakerRole":"agent","index":32,"text":"就如果您要提前还款的话，","beginTime":67865,"endTime":69820,"channelId":0},{"speakerRole":"agent","index":33,"text":"是没有任何违约金的。","beginTime":69820,"endTime":71420,"channelId":0},{"speakerRole":"agent","index":34,"text":"嗯，","beginTime":71920,"endTime":72363,"channelId":0},{"speakerRole":"agent","index":35,"text":"行，","beginTime":72363,"endTime":72806,"channelId":0},{"speakerRole":"agent","index":36,"text":"那你多大？","beginTime":72806,"endTime":74580,"channelId":0},{"speakerRole":"agent","index":37,"text":"呃，","beginTime":75040,"endTime":75224,"channelId":0},{"speakerRole":"agent","index":38,"text":"您您这边行驶证和绿本都有在您身边吗？","beginTime":75224,"endTime":78360,"channelId":0},{"speakerRole":"agent","index":39,"text":"嗯，","beginTime":78900,"endTime":79127,"channelId":0},{"speakerRole":"agent","index":40,"text":"我现在不在，","beginTime":79127,"endTime":80264,"channelId":0},{"speakerRole":"agent","index":41,"text":"哎，","beginTime":80264,"endTime":80491,"channelId":0},{"speakerRole":"agent","index":42,"text":"所以我发有一个我发过了呀啊呃呃因为我这边还没有添加您的联系。","beginTime":80491,"endTime":89550,"channelId":0},{"speakerRole":"agent","index":43,"text":"因为我我车子在，","beginTime":89550,"endTime":91278,"channelId":0},{"speakerRole":"agent","index":44,"text":"我现在在老家，","beginTime":91278,"endTime":92759,"channelId":0},{"speakerRole":"agent","index":45,"text":"车子在在在江苏那边没地方。","beginTime":92759,"endTime":97883,"channelId":0},{"speakerRole":"agent","index":46,"text":"呃，","beginTime":97883,"endTime":98104,"channelId":0},{"speakerRole":"agent","index":47,"text":"那你有没有行驶证和日本的照片呢？","beginTime":98104,"endTime":101420,"channelId":0},{"speakerRole":"agent","index":48,"text":"应该有吧，","beginTime":102380,"endTime":103646,"channelId":0},{"speakerRole":"agent","index":49,"text":"没本。","beginTime":103646,"endTime":104280,"channelId":0},{"speakerRole":"agent","index":50,"text":"对，","beginTime":105220,"endTime":105409,"channelId":0},{"speakerRole":"agent","index":51,"text":"那行吧，","beginTime":105409,"endTime":105976,"channelId":0},{"speakerRole":"agent","index":52,"text":"现现在我暂时过几天吧，","beginTime":105976,"endTime":107869,"channelId":0},{"speakerRole":"agent","index":53,"text":"等他们上去发给我。","beginTime":107869,"endTime":109383,"channelId":0},{"speakerRole":"agent","index":54,"text":"嗯嗯，","beginTime":109383,"endTime":109761,"channelId":0},{"speakerRole":"agent","index":55,"text":"那那我这边添加您一个联系方式嘛，","beginTime":109761,"endTime":112600,"channelId":0},{"speakerRole":"agent","index":56,"text":"然后您到时候有了，","beginTime":112600,"endTime":114113,"channelId":0},{"speakerRole":"agent","index":57,"text":"您可以直接联系我。","beginTime":114113,"endTime":115627,"channelId":0},{"speakerRole":"agent","index":58,"text":"然后我这边就帮您办理很快的，","beginTime":115627,"endTime":118409,"channelId":0},{"speakerRole":"agent","index":59,"text":"最快一个小时左右就可以放款的了。","beginTime":118409,"endTime":121656,"channelId":0},{"speakerRole":"agent","index":60,"text":"嗯嗯，","beginTime":121656,"endTime":122089,"channelId":0},{"speakerRole":"agent","index":61,"text":"行，","beginTime":122089,"endTime":122305,"channelId":0},{"speakerRole":"agent","index":62,"text":"您稍等一下，","beginTime":122305,"endTime":123388,"channelId":0},{"speakerRole":"agent","index":63,"text":"我这边添加您一个。","beginTime":123388,"endTime":125120,"channelId":0}]}',80,NULL,NULL,0,0,2,'2026-05-22 01:11:27','2026-05-22 01:11:30','2026-05-22 01:11:23','2026-05-22 01:11:30','system','system','BATCH-20260522-030772',NULL),
(205483,'rec_495416104203400bb47a14a4','ext_e7dde4f68fbe479eb16a6dcf862ea4e8','7fbb7d56-77d9-47a5-ac72-6c2441edd212.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/62c4a1b699e644a5bb6cd6ea8cb17b43.mp3',2,104,'mp3',108360,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":1440,"endTime":1734,"channelId":0},{"speakerRole":"agent","index":1,"text":"哎你好，","beginTime":1734,"endTime":2616,"channelId":0},{"speakerRole":"agent","index":2,"text":"郑先生啊，","beginTime":2616,"endTime":3792,"channelId":0},{"speakerRole":"agent","index":3,"text":"我看您早上登录系统，","beginTime":3792,"endTime":6438,"channelId":0},{"speakerRole":"agent","index":4,"text":"我这边发起了陪伴。","beginTime":6438,"endTime":8790,"channelId":0},{"speakerRole":"agent","index":5,"text":"嗯，","beginTime":8790,"endTime":9084,"channelId":0},{"speakerRole":"agent","index":6,"text":"您这边的话资金现在用的能用的着吗？","beginTime":9084,"endTime":13788,"channelId":0},{"speakerRole":"agent","index":7,"text":"还是暂时不着急啊？","beginTime":13788,"endTime":16140,"channelId":0},{"speakerRole":"agent","index":8,"text":"没有，","beginTime":16480,"endTime":16960,"channelId":0},{"speakerRole":"agent","index":9,"text":"我是听等一下，","beginTime":16960,"endTime":18400,"channelId":0},{"speakerRole":"agent","index":10,"text":"我我提交那个身份信息啊呃，","beginTime":18400,"endTime":21591,"channelId":0},{"speakerRole":"agent","index":11,"text":"什么提交身份证息啊，","beginTime":21591,"endTime":25033,"channelId":0},{"speakerRole":"agent","index":12,"text":"您现在正在提交吗？","beginTime":25033,"endTime":27220,"channelId":0},{"speakerRole":"agent","index":13,"text":"总账总账不就是十多个吗？","beginTime":27900,"endTime":30200,"channelId":0},{"speakerRole":"agent","index":14,"text":"没有啊，","beginTime":31060,"endTime":31750,"channelId":0},{"speakerRole":"agent","index":15,"text":"你你早上只是那个我看看了一下还款计划，","beginTime":31750,"endTime":35890,"channelId":0},{"speakerRole":"agent","index":16,"text":"但是一直没往下操作。","beginTime":35890,"endTime":37960,"channelId":0},{"speakerRole":"agent","index":17,"text":"您这边的话需要填写完整的信息，","beginTime":40020,"endTime":43072,"channelId":0},{"speakerRole":"agent","index":18,"text":"包括您需要绑卡上传这个行驶证和日本照片啊，","beginTime":43072,"endTime":47433,"channelId":0},{"speakerRole":"agent","index":19,"text":"我这边才能收到。","beginTime":47433,"endTime":48960,"channelId":0},{"speakerRole":"agent","index":20,"text":"行行行，","beginTime":51140,"endTime":51630,"channelId":0},{"speakerRole":"agent","index":21,"text":"那我操作一下，","beginTime":51630,"endTime":52611,"channelId":0},{"speakerRole":"agent","index":22,"text":"等一下现在为止吧。","beginTime":52611,"endTime":53920,"channelId":0},{"speakerRole":"agent","index":23,"text":"行，","beginTime":54220,"endTime":54437,"channelId":0},{"speakerRole":"agent","index":24,"text":"您大约几点方便啊？","beginTime":54437,"endTime":56181,"channelId":0},{"speakerRole":"agent","index":25,"text":"我协助您这边投标一下。","beginTime":56181,"endTime":58360,"channelId":0},{"speakerRole":"agent","index":26,"text":"九点钟晚上好，","beginTime":60540,"endTime":61960,"channelId":0},{"speakerRole":"agent","index":27,"text":"十点左右是吧？","beginTime":62200,"endTime":63580,"channelId":0},{"speakerRole":"agent","index":28,"text":"行行，","beginTime":64720,"endTime":65123,"channelId":0},{"speakerRole":"agent","index":29,"text":"那那到时候你有啥不明白的，","beginTime":65123,"endTime":67545,"channelId":0},{"speakerRole":"agent","index":30,"text":"你随时问我就行了。","beginTime":67545,"endTime":69160,"channelId":0},{"speakerRole":"agent","index":31,"text":"我们现在有呃有个假期活动，","beginTime":70820,"endTime":74015,"channelId":0},{"speakerRole":"agent","index":32,"text":"您考虑吗？","beginTime":74015,"endTime":75080,"channelId":0},{"speakerRole":"agent","index":33,"text":"电视的啊什么价格的。","beginTime":77680,"endTime":81860,"channelId":0},{"speakerRole":"agent","index":34,"text":"就说嗯因为虽然现在看不到您最终的利息，","beginTime":83940,"endTime":88570,"channelId":0},{"speakerRole":"agent","index":35,"text":"但是您如果呃，","beginTime":88570,"endTime":90114,"channelId":0},{"speakerRole":"agent","index":36,"text":"感觉利息不合适，","beginTime":90114,"endTime":91915,"channelId":0},{"speakerRole":"agent","index":37,"text":"我这边可以考虑给你做降息啊。","beginTime":91915,"endTime":95260,"channelId":0},{"speakerRole":"agent","index":38,"text":"好的好的，","beginTime":95600,"endTime":96406,"channelId":0},{"speakerRole":"agent","index":39,"text":"等一下十点钟再说吧。","beginTime":96406,"endTime":98220,"channelId":0},{"speakerRole":"agent","index":40,"text":"四点多的说是吧，","beginTime":98460,"endTime":99785,"channelId":0},{"speakerRole":"agent","index":41,"text":"到时候你你有时间了，","beginTime":99785,"endTime":101490,"channelId":0},{"speakerRole":"agent","index":42,"text":"你提前告诉我行吧。","beginTime":101490,"endTime":103005,"channelId":0},{"speakerRole":"agent","index":43,"text":"行行行行，","beginTime":103005,"endTime":103763,"channelId":0},{"speakerRole":"agent","index":44,"text":"嗯，","beginTime":103763,"endTime":103952,"channelId":0},{"speakerRole":"agent","index":45,"text":"好嘞好嘞，","beginTime":103952,"endTime":104710,"channelId":0},{"speakerRole":"agent","index":46,"text":"嗯。","beginTime":104710,"endTime":104900,"channelId":0}]}',80,NULL,NULL,0,0,2,'2026-05-22 01:11:27','2026-05-22 01:11:30','2026-05-22 01:11:24','2026-05-22 01:11:30','system','system','BATCH-20260522-030772',NULL),
