(205485,'rec_4109efbb8310466395d16547','ext_8e1d59d570ec42ee9608565a2ec3a27c','22bd7ced-22be-4502-9468-7bacecb55b0c.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/c80b1fb015dc408fb6509a7472674cbe.mp3',2,134,'mp3',134208,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎喂，","beginTime":580,"endTime":1060,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":1060,"endTime":1540,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问您是手机尾号九三七九的董先生吗？","beginTime":1540,"endTime":5620,"channelId":0},{"speakerRole":"agent","index":3,"text":"喂，","beginTime":6320,"endTime":6479,"channelId":0},{"speakerRole":"agent","index":4,"text":"你好，","beginTime":6479,"endTime":6798,"channelId":0},{"speakerRole":"agent","index":5,"text":"董先生，","beginTime":6798,"endTime":7276,"channelId":0},{"speakerRole":"agent","index":6,"text":"我这边是那个支付宝新人车贷的，","beginTime":7276,"endTime":9508,"channelId":0},{"speakerRole":"agent","index":7,"text":"这边来电是看到您提交的一笔出子贷，","beginTime":9508,"endTime":12058,"channelId":0},{"speakerRole":"agent","index":8,"text":"一审已经通过了。","beginTime":12058,"endTime":13174,"channelId":0},{"speakerRole":"agent","index":9,"text":"目前的话授权额度的话有三万六千八，","beginTime":13174,"endTime":15725,"channelId":0},{"speakerRole":"agent","index":10,"text":"你看这边额度满意吗？","beginTime":15725,"endTime":17160,"channelId":0},{"speakerRole":"agent","index":11,"text":"嗯嗯嗯，","beginTime":20180,"endTime":20706,"channelId":0},{"speakerRole":"agent","index":12,"text":"我这边是给您一个后续流行的放款专员，","beginTime":20706,"endTime":23689,"channelId":0},{"speakerRole":"agent","index":13,"text":"咱们这边提交这个车辆的话，","beginTime":23689,"endTime":25794,"channelId":0},{"speakerRole":"agent","index":14,"text":"是您本人您带的全款车辆吗？","beginTime":25794,"endTime":27900,"channelId":0},{"speakerRole":"agent","index":15,"text":"哎，","beginTime":29620,"endTime":29809,"channelId":0},{"speakerRole":"agent","index":16,"text":"好的，","beginTime":29809,"endTime":30188,"channelId":0},{"speakerRole":"agent","index":17,"text":"这个资金咱们不是在用的吗？","beginTime":30188,"endTime":32460,"channelId":0},{"speakerRole":"agent","index":18,"text":"哎，","beginTime":35160,"endTime":35311,"channelId":0},{"speakerRole":"agent","index":19,"text":"简单跟您说一下流程哈，","beginTime":35311,"endTime":36825,"channelId":0},{"speakerRole":"agent","index":20,"text":"这边就需要您去支付宝补充上传一下您的车辆日本和行驶证的照片，","beginTime":36825,"endTime":41215,"channelId":0},{"speakerRole":"agent","index":21,"text":"上传之后，","beginTime":41215,"endTime":41820,"channelId":0},{"speakerRole":"agent","index":22,"text":"是不是给您对接审核，","beginTime":41820,"endTime":43183,"channelId":0},{"speakerRole":"agent","index":23,"text":"审核通过，","beginTime":43183,"endTime":43788,"channelId":0},{"speakerRole":"agent","index":24,"text":"咱们今天就可以到账的，","beginTime":43788,"endTime":45302,"channelId":0},{"speakerRole":"agent","index":25,"text":"全程都是一个宣传办理，","beginTime":45302,"endTime":46816,"channelId":0},{"speakerRole":"agent","index":26,"text":"没有任何费用的。","beginTime":46816,"endTime":47876,"channelId":0},{"speakerRole":"agent","index":27,"text":"目前这两个资料有在您身边吗？","beginTime":47876,"endTime":49844,"channelId":0},{"speakerRole":"agent","index":28,"text":"就是您的大本和信息这样子的照片，","beginTime":49844,"endTime":52114,"channelId":0},{"speakerRole":"agent","index":29,"text":"或者是这两个证件有在吗？","beginTime":52114,"endTime":53780,"channelId":0},{"speakerRole":"agent","index":30,"text":"我在吗？","beginTime":55060,"endTime":56060,"channelId":0},{"speakerRole":"agent","index":31,"text":"嗯，","beginTime":56900,"endTime":57560,"channelId":0},{"speakerRole":"agent","index":32,"text":"哦在的话，","beginTime":58180,"endTime":58842,"channelId":0},{"speakerRole":"agent","index":33,"text":"那就可以的呀。","beginTime":58842,"endTime":59835,"channelId":0},{"speakerRole":"agent","index":34,"text":"然后我刚看了一下你的这个微信名字，","beginTime":59835,"endTime":62485,"channelId":0},{"speakerRole":"agent","index":35,"text":"是一个那个头像是一个男生的那个是吗？","beginTime":62485,"endTime":65300,"channelId":0},{"speakerRole":"agent","index":36,"text":"给那个阿峰，","beginTime":66980,"endTime":67753,"channelId":0},{"speakerRole":"agent","index":37,"text":"我用这个协议信添加您了，","beginTime":67753,"endTime":69454,"channelId":0},{"speakerRole":"agent","index":38,"text":"在您的微信界面上会有一个服务通知，","beginTime":69454,"endTime":71929,"channelId":0},{"speakerRole":"agent","index":39,"text":"是一个橙色的小喇叭。","beginTime":71929,"endTime":73321,"channelId":0},{"speakerRole":"agent","index":40,"text":"这边您可以通过一下我这个协议信用，","beginTime":73321,"endTime":75796,"channelId":0},{"speakerRole":"agent","index":41,"text":"本次订单由我负责，","beginTime":75796,"endTime":77033,"channelId":0},{"speakerRole":"agent","index":42,"text":"给您后续的邮件和放款。","beginTime":77033,"endTime":78580,"channelId":0},{"speakerRole":"agent","index":43,"text":"这边您添加之后，","beginTime":78580,"endTime":79663,"channelId":0},{"speakerRole":"agent","index":44,"text":"我把这个资料模板发给您，","beginTime":79663,"endTime":81364,"channelId":0},{"speakerRole":"agent","index":45,"text":"然后您这边就对着这个资料去上传，","beginTime":81364,"endTime":83684,"channelId":0},{"speakerRole":"agent","index":46,"text":"上传之后就给您对接，","beginTime":83684,"endTime":85077,"channelId":0},{"speakerRole":"agent","index":47,"text":"审核。","beginTime":85077,"endTime":85386,"channelId":0},{"speakerRole":"agent","index":48,"text":"审核的话也很快，","beginTime":85386,"endTime":86469,"channelId":0},{"speakerRole":"agent","index":49,"text":"几分钟。","beginTime":86469,"endTime":86933,"channelId":0},{"speakerRole":"agent","index":50,"text":"咱们这边如果现在补充的话，","beginTime":86933,"endTime":88789,"channelId":0},{"speakerRole":"agent","index":51,"text":"呃，","beginTime":88789,"endTime":88943,"channelId":0},{"speakerRole":"agent","index":52,"text":"十点半之前就可以到账的哈。","beginTime":88943,"endTime":90800,"channelId":0},{"speakerRole":"agent","index":53,"text":"哎，","beginTime":94560,"endTime":94707,"channelId":0},{"speakerRole":"agent","index":54,"text":"没事，","beginTime":94707,"endTime":95002,"channelId":0},{"speakerRole":"agent","index":55,"text":"的哥，","beginTime":95002,"endTime":95297,"channelId":0},{"speakerRole":"agent","index":56,"text":"您可以先添加我这个微信吧。","beginTime":95297,"endTime":97067,"channelId":0},{"speakerRole":"agent","index":57,"text":"您看如果有任何呃问题的话，","beginTime":97067,"endTime":98837,"channelId":0},{"speakerRole":"agent","index":58,"text":"您可以随时跟我沟通的。","beginTime":98837,"endTime":100312,"channelId":0},{"speakerRole":"agent","index":59,"text":"或者是您什么时候的话，","beginTime":100312,"endTime":101787,"channelId":0},{"speakerRole":"agent","index":60,"text":"就可以联系您办理，","beginTime":101787,"endTime":102967,"channelId":0},{"speakerRole":"agent","index":61,"text":"这样比较方便点。","beginTime":102967,"endTime":104000,"channelId":0},{"speakerRole":"agent","index":62,"text":"哎，","beginTime":106780,"endTime":106943,"channelId":0},{"speakerRole":"agent","index":63,"text":"对，","beginTime":106943,"endTime":107107,"channelId":0},{"speakerRole":"agent","index":64,"text":"因为咱们这个是外呼系统给您打过来的。","beginTime":107107,"endTime":109887,"channelId":0},{"speakerRole":"agent","index":65,"text":"这个待会儿的话，","beginTime":109887,"endTime":111032,"channelId":0},{"speakerRole":"agent","index":66,"text":"您联系不上，","beginTime":111032,"endTime":111850,"channelId":0},{"speakerRole":"agent","index":67,"text":"所以您每天在下午这个节奏天，","beginTime":111850,"endTime":113977,"channelId":0},{"speakerRole":"agent","index":68,"text":"我刚刚用这个节目先添加了。","beginTime":113977,"endTime":115940,"channelId":0},{"speakerRole":"agent","index":69,"text":"能听到吗？","beginTime":120960,"endTime":122208,"channelId":0},{"speakerRole":"agent","index":70,"text":"哥，","beginTime":122208,"endTime":122520,"channelId":0},{"speakerRole":"agent","index":71,"text":"哎，","beginTime":123840,"endTime":123995,"channelId":0},{"speakerRole":"agent","index":72,"text":"好的好的，","beginTime":123995,"endTime":124615,"channelId":0},{"speakerRole":"agent","index":73,"text":"那这边就麻烦您通过一下这个企业微信有任何问题，","beginTime":124615,"endTime":128028,"channelId":0},{"speakerRole":"agent","index":74,"text":"咱们在微信上沟通好吧。","beginTime":128028,"endTime":129580,"channelId":0},{"speakerRole":"agent","index":75,"text":"哎，","beginTime":130980,"endTime":131149,"channelId":0},{"speakerRole":"agent","index":76,"text":"好的好的，","beginTime":131149,"endTime":131827,"channelId":0},{"speakerRole":"agent","index":77,"text":"那就不打扰您了哈，","beginTime":131827,"endTime":133183,"channelId":0},{"speakerRole":"agent","index":78,"text":"昨天生日再见。","beginTime":133183,"endTime":134200,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:11:32','2026-05-22 01:11:35','2026-05-22 01:11:27','2026-05-22 01:11:35','system','system','BATCH-20260522-030772',NULL),
(205486,'rec_f4dbcb9e5a344a8eba2fc08d','ext_db970ef447db45979cadf0acebbf769f','53a44c59-6fc4-4b80-a238-b12daccfe63a.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/e5f87a8f86f0476abe2bc6841080dc90.mp3',2,68,'mp3',71496,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"好哎喂你好，","beginTime":1520,"endTime":2658,"channelId":0},{"speakerRole":"agent","index":1,"text":"请问是陈先生，","beginTime":2658,"endTime":4024,"channelId":0},{"speakerRole":"agent","index":2,"text":"对吧？","beginTime":4024,"endTime":4480,"channelId":0},{"speakerRole":"agent","index":3,"text":"嗯，","beginTime":4720,"endTime":5520,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎你好，","beginTime":5800,"endTime":6418,"channelId":0},{"speakerRole":"agent","index":5,"text":"我这边的话是支付宝精选车贷的客户经理。","beginTime":6418,"endTime":10129,"channelId":0},{"speakerRole":"agent","index":6,"text":"这个您这笔四万多的额，","beginTime":10129,"endTime":12190,"channelId":0},{"speakerRole":"agent","index":7,"text":"还需要办理价款吗？","beginTime":12190,"endTime":13840,"channelId":0},{"speakerRole":"agent","index":8,"text":"嗯，","beginTime":15120,"endTime":15493,"channelId":0},{"speakerRole":"agent","index":9,"text":"不用呃，","beginTime":15493,"endTime":17136,"channelId":0},{"speakerRole":"agent","index":10,"text":"降低优惠也不需要吗？","beginTime":17136,"endTime":19440,"channelId":0},{"speakerRole":"agent","index":11,"text":"我们店嗯是这样的，","beginTime":20740,"endTime":23675,"channelId":0},{"speakerRole":"agent","index":12,"text":"我们目前针对就是月底的时候有发放一笔这个相机线。","beginTime":23675,"endTime":28528,"channelId":0},{"speakerRole":"agent","index":13,"text":"就如果需要办理的话，","beginTime":28528,"endTime":30427,"channelId":0},{"speakerRole":"agent","index":14,"text":"这边可以后续给您申请账期。","beginTime":30427,"endTime":32960,"channelId":0},{"speakerRole":"agent","index":15,"text":"嗯，","beginTime":34120,"endTime":34456,"channelId":0},{"speakerRole":"agent","index":16,"text":"申请多少，","beginTime":34456,"endTime":35800,"channelId":0},{"speakerRole":"agent","index":17,"text":"嗯，","beginTime":36460,"endTime":36856,"channelId":0},{"speakerRole":"agent","index":18,"text":"差不多在三到九级左右吧，","beginTime":36856,"endTime":41140,"channelId":0},{"speakerRole":"agent","index":19,"text":"一起吧。","beginTime":41380,"endTime":42280,"channelId":0},{"speakerRole":"agent","index":20,"text":"嗯就一个月的话，","beginTime":43740,"endTime":47560,"channelId":0},{"speakerRole":"agent","index":21,"text":"就相当于说借一万块钱的话，","beginTime":47940,"endTime":51580,"channelId":0},{"speakerRole":"agent","index":22,"text":"你可的话哎喂哎。","beginTime":51580,"endTime":55220,"channelId":0},{"speakerRole":"agent","index":23,"text":"听得到吗？","beginTime":57380,"endTime":58560,"channelId":0},{"speakerRole":"agent","index":24,"text":"喂，","beginTime":60000,"endTime":60860,"channelId":0},{"speakerRole":"agent","index":25,"text":"嗯要不喂，","beginTime":61160,"endTime":62525,"channelId":0},{"speakerRole":"agent","index":26,"text":"哥听得到吗？","beginTime":62525,"endTime":64354,"channelId":0},{"speakerRole":"agent","index":27,"text":"哎。","beginTime":64354,"endTime":64720,"channelId":0},{"speakerRole":"agent","index":28,"text":"哎。","beginTime":67220,"endTime":68060,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:11:32','2026-05-22 01:11:34','2026-05-22 01:11:29','2026-05-22 01:11:34','system','system','BATCH-20260522-030772',NULL),
(205487,'rec_be7ee74f188346a296ba550e','ext_b42d47adc0ef445fbb84037df68d276f','103efccf-607b-4346-9046-2fdf8d4fd7dc.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/8b81f0127e67427a9ccfa07af2ab843d.mp3',2,410,'mp3',411336,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"你好喂你好，","beginTime":0,"endTime":1208,"channelId":0},{"speakerRole":"agent","index":1,"text":"请问是李先生吗？","beginTime":1208,"endTime":2900,"channelId":0},{"speakerRole":"agent","index":2,"text":"喂，","beginTime":5220,"endTime":5693,"channelId":0},{"speakerRole":"agent","index":3,"text":"你好，","beginTime":5693,"endTime":6640,"channelId":0},{"speakerRole":"agent","index":4,"text":"你现在能听到吗？","beginTime":8460,"endTime":10080,"channelId":0},{"speakerRole":"agent","index":5,"text":"啊啊，","beginTime":10420,"endTime":11780,"channelId":0},{"speakerRole":"agent","index":6,"text":"你好，","beginTime":11780,"endTime":12222,"channelId":0},{"speakerRole":"agent","index":7,"text":"我这边是支付宝，","beginTime":12222,"endTime":13768,"channelId":0},{"speakerRole":"agent","index":8,"text":"现在车贷的，","beginTime":13768,"endTime":14873,"channelId":0},{"speakerRole":"agent","index":9,"text":"您现在说方便吗？","beginTime":14873,"endTime":16419,"channelId":0},{"speakerRole":"agent","index":10,"text":"是方便方便啊。","beginTime":16419,"endTime":17725,"channelId":0},{"speakerRole":"agent","index":11,"text":"就是我这边是来协助您把您这个签约和给您换款的。","beginTime":17725,"endTime":21445,"channelId":0},{"speakerRole":"agent","index":12,"text":"您看这笔资金大概什么时候需要使用呢？","beginTime":21445,"endTime":24320,"channelId":0},{"speakerRole":"agent","index":13,"text":"那个不给结呀，","beginTime":25680,"endTime":28850,"channelId":0},{"speakerRole":"agent","index":14,"text":"然后我想问一下，","beginTime":28850,"endTime":30162,"channelId":0},{"speakerRole":"agent","index":15,"text":"你们那个能提前还款吗？","beginTime":30162,"endTime":32037,"channelId":0},{"speakerRole":"agent","index":16,"text":"嗯，","beginTime":32037,"endTime":32225,"channelId":0},{"speakerRole":"agent","index":17,"text":"他是这样的哥嗯，","beginTime":32225,"endTime":33537,"channelId":0},{"speakerRole":"agent","index":18,"text":"提前结清是随时都可以。","beginTime":33537,"endTime":35412,"channelId":0},{"speakerRole":"agent","index":19,"text":"但是它涉及到一个违约金的问题，","beginTime":35412,"endTime":38037,"channelId":0},{"speakerRole":"agent","index":20,"text":"就说是你使用大概多久了，","beginTime":38037,"endTime":40100,"channelId":0},{"speakerRole":"agent","index":21,"text":"使用大概在使用前三年这一块啊，","beginTime":41200,"endTime":45785,"channelId":0},{"speakerRole":"agent","index":22,"text":"他一年之后他就没有违约金了。","beginTime":45785,"endTime":47933,"channelId":0},{"speakerRole":"agent","index":23,"text":"就是这样的，","beginTime":47933,"endTime":48760,"channelId":0},{"speakerRole":"agent","index":24,"text":"如果一年之内的话，","beginTime":48760,"endTime":50082,"channelId":0},{"speakerRole":"agent","index":25,"text":"他有一个剩余本金百分之四就是一万块钱的话，","beginTime":50082,"endTime":53387,"channelId":0},{"speakerRole":"agent","index":26,"text":"就是四百块钱的违约金要用嘛，","beginTime":53387,"endTime":55995,"channelId":0},{"speakerRole":"agent","index":27,"text":"加上去之后就没有这个违约金了哦。","beginTime":55995,"endTime":58858,"channelId":0},{"speakerRole":"agent","index":28,"text":"你的意思就是说，","beginTime":58858,"endTime":60384,"channelId":0},{"speakerRole":"agent","index":29,"text":"我现在贷了三年。","beginTime":60384,"endTime":61911,"channelId":0},{"speakerRole":"agent","index":30,"text":"对对，","beginTime":61911,"endTime":62347,"channelId":0},{"speakerRole":"agent","index":31,"text":"我还过一年以后，","beginTime":62347,"endTime":63874,"channelId":0},{"speakerRole":"agent","index":32,"text":"然后后后面这两年感觉就是自己有能力一下还清了，","beginTime":63874,"endTime":68672,"channelId":0},{"speakerRole":"agent","index":33,"text":"然后就可以申请一一下还清。","beginTime":68672,"endTime":71289,"channelId":0},{"speakerRole":"agent","index":34,"text":"对对，","beginTime":71289,"endTime":71725,"channelId":0},{"speakerRole":"agent","index":35,"text":"可以的。","beginTime":71725,"endTime":72380,"channelId":0},{"speakerRole":"agent","index":36,"text":"那他的嗯就是说嗯你后面有资金了，","beginTime":72620,"endTime":75743,"channelId":0},{"speakerRole":"agent","index":37,"text":"十二个月之后，","beginTime":75743,"endTime":76993,"channelId":0},{"speakerRole":"agent","index":38,"text":"他就没有违约金了。","beginTime":76993,"endTime":78659,"channelId":0},{"speakerRole":"agent","index":39,"text":"然后你就是还您自己申请的本金就行了，","beginTime":78659,"endTime":82200,"channelId":0},{"speakerRole":"agent","index":40,"text":"那就是相当于打个比方，","beginTime":82800,"endTime":84523,"channelId":0},{"speakerRole":"agent","index":41,"text":"就是按我那种说法，","beginTime":84523,"endTime":85901,"channelId":0},{"speakerRole":"agent","index":42,"text":"就是说我用一年，","beginTime":85901,"endTime":87107,"channelId":0},{"speakerRole":"agent","index":43,"text":"也就是相当于付你们一年的利息就可以。","beginTime":87107,"endTime":90753,"channelId":0},{"speakerRole":"agent","index":44,"text":"嗯，","beginTime":90753,"endTime":91084,"channelId":0},{"speakerRole":"agent","index":45,"text":"对，","beginTime":91084,"endTime":91415,"channelId":0},{"speakerRole":"agent","index":46,"text":"是这样的那好好好，","beginTime":91415,"endTime":93960,"channelId":0},{"speakerRole":"agent","index":47,"text":"那我理解。","beginTime":93960,"endTime":94880,"channelId":0},{"speakerRole":"agent","index":48,"text":"那现在办理就是说嗯那也结婚了吧，","beginTime":94880,"endTime":98818,"channelId":0},{"speakerRole":"agent","index":49,"text":"也等着用钱，","beginTime":98818,"endTime":99946,"channelId":0},{"speakerRole":"agent","index":50,"text":"就就这个情况啊。","beginTime":99946,"endTime":102135,"channelId":0},{"speakerRole":"agent","index":51,"text":"可以啊，","beginTime":102135,"endTime":102962,"channelId":0},{"speakerRole":"agent","index":52,"text":"哥嗯，","beginTime":102962,"endTime":103514,"channelId":0},{"speakerRole":"agent","index":53,"text":"你大概需要多少嘛？","beginTime":103514,"endTime":105720,"channelId":0},{"speakerRole":"agent","index":54,"text":"我看你这上面显示的是九万九万多，","beginTime":106380,"endTime":109424,"channelId":0},{"speakerRole":"agent","index":55,"text":"不是吗？","beginTime":109424,"endTime":110033,"channelId":0},{"speakerRole":"agent","index":56,"text":"九万嗯，","beginTime":110033,"endTime":110642,"channelId":0},{"speakerRole":"agent","index":57,"text":"它是一个初始的额度，","beginTime":110642,"endTime":112469,"channelId":0},{"speakerRole":"agent","index":58,"text":"就是说因为这个需要过一个审核，","beginTime":112469,"endTime":115311,"channelId":0},{"speakerRole":"agent","index":59,"text":"审核通过之后，","beginTime":115311,"endTime":116529,"channelId":0},{"speakerRole":"agent","index":60,"text":"他还要看您是否符合办理条件，","beginTime":116529,"endTime":119168,"channelId":0},{"speakerRole":"agent","index":61,"text":"然后是否是本人的。","beginTime":119168,"endTime":120871,"channelId":0},{"speakerRole":"agent","index":62,"text":"歌是这样的，","beginTime":120871,"endTime":121960,"channelId":0},{"speakerRole":"agent","index":63,"text":"然后它会最后是一个最终的额度。","beginTime":122200,"endTime":124960,"channelId":0},{"speakerRole":"agent","index":64,"text":"然后您看的额度才是最终的额度。","beginTime":124960,"endTime":127720,"channelId":0},{"speakerRole":"agent","index":65,"text":"说那你现在怎么着，","beginTime":128200,"endTime":131047,"channelId":0},{"speakerRole":"agent","index":66,"text":"因为我现在上面显示九万零九百嗯嗯，","beginTime":131047,"endTime":134585,"channelId":0},{"speakerRole":"agent","index":67,"text":"跟您的六百和行驶证在上面吗？","beginTime":134585,"endTime":137460,"channelId":0},{"speakerRole":"agent","index":68,"text":"呃，","beginTime":138580,"endTime":138850,"channelId":0},{"speakerRole":"agent","index":69,"text":"什么东西啊，","beginTime":138850,"endTime":140200,"channelId":0},{"speakerRole":"agent","index":70,"text":"绿本和行驶证嗯，","beginTime":140440,"endTime":142789,"channelId":0},{"speakerRole":"agent","index":71,"text":"一本教昨天跟血压上面差一万嗯，","beginTime":142789,"endTime":148240,"channelId":0},{"speakerRole":"agent","index":72,"text":"那你这个解押了吗？","beginTime":148580,"endTime":150295,"channelId":0},{"speakerRole":"agent","index":73,"text":"呃，","beginTime":150295,"endTime":150510,"channelId":0},{"speakerRole":"agent","index":74,"text":"你昨天刚解押过呃，","beginTime":150510,"endTime":152226,"channelId":0},{"speakerRole":"agent","index":75,"text":"上面打的这个呃，","beginTime":152226,"endTime":153727,"channelId":0},{"speakerRole":"agent","index":76,"text":"解押状态吗？","beginTime":153727,"endTime":154800,"channelId":0},{"speakerRole":"agent","index":77,"text":"搞好了呀，","beginTime":155680,"endTime":156548,"channelId":0},{"speakerRole":"agent","index":78,"text":"因为我跟那工作人员说了，","beginTime":156548,"endTime":158938,"channelId":0},{"speakerRole":"agent","index":79,"text":"他都说搞好了呀，","beginTime":158938,"endTime":160458,"channelId":0},{"speakerRole":"agent","index":80,"text":"你交给家给掉了，","beginTime":160458,"endTime":161979,"channelId":0},{"speakerRole":"agent","index":81,"text":"那给我盖上了。","beginTime":161979,"endTime":163282,"channelId":0},{"speakerRole":"agent","index":82,"text":"嗯，","beginTime":163282,"endTime":163500,"channelId":0},{"speakerRole":"agent","index":83,"text":"哥，","beginTime":163740,"endTime":163944,"channelId":0},{"speakerRole":"agent","index":84,"text":"您这样吧，","beginTime":163944,"endTime":164763,"channelId":0},{"speakerRole":"agent","index":85,"text":"你把嗯我这边用企业微信添加了一个好友。","beginTime":164763,"endTime":168447,"channelId":0},{"speakerRole":"agent","index":86,"text":"嗯，","beginTime":168447,"endTime":168652,"channelId":0},{"speakerRole":"agent","index":87,"text":"那个他这个啊我就想问一下，","beginTime":168652,"endTime":172013,"channelId":0},{"speakerRole":"agent","index":88,"text":"你们这个就是说嗯就是压力本绿本压在哪里啊？","beginTime":172013,"endTime":176992,"channelId":0},{"speakerRole":"agent","index":89,"text":"嗯是这样的，","beginTime":176992,"endTime":178237,"channelId":0},{"speakerRole":"agent","index":90,"text":"绿板是放嗯先去地的那个上牌车管所。","beginTime":178237,"endTime":181806,"channelId":0},{"speakerRole":"agent","index":91,"text":"做一个备案登记，","beginTime":181806,"endTime":183210,"channelId":0},{"speakerRole":"agent","index":92,"text":"然后就是说已经抵押给我们公司的房子，","beginTime":183210,"endTime":186622,"channelId":0},{"speakerRole":"agent","index":93,"text":"您再拿绿本出去，","beginTime":186622,"endTime":188026,"channelId":0},{"speakerRole":"agent","index":94,"text":"在其他平台贷贷款就进行一个二次抵押，","beginTime":188026,"endTime":191438,"channelId":0},{"speakerRole":"agent","index":95,"text":"就是这样。","beginTime":191438,"endTime":192241,"channelId":0},{"speakerRole":"agent","index":96,"text":"然后然后呃，","beginTime":192241,"endTime":193244,"channelId":0},{"speakerRole":"agent","index":97,"text":"是扣在那里是吧，","beginTime":193244,"endTime":194649,"channelId":0},{"speakerRole":"agent","index":98,"text":"嗯，","beginTime":194649,"endTime":194849,"channelId":0},{"speakerRole":"agent","index":99,"text":"然后最后的是呃邮寄到我们总部来啊，","beginTime":194849,"endTime":198385,"channelId":0},{"speakerRole":"agent","index":100,"text":"一边预约一到你们总部。","beginTime":198385,"endTime":200240,"channelId":0},{"speakerRole":"agent","index":101,"text":"哎，","beginTime":200240,"endTime":200425,"channelId":0},{"speakerRole":"agent","index":102,"text":"对，","beginTime":200425,"endTime":200611,"channelId":0},{"speakerRole":"agent","index":103,"text":"留到我们总部。","beginTime":200611,"endTime":201724,"channelId":0},{"speakerRole":"agent","index":104,"text":"然后您结清之后，","beginTime":201724,"endTime":203022,"channelId":0},{"speakerRole":"agent","index":105,"text":"又是由我们给您解押，","beginTime":203022,"endTime":204692,"channelId":0},{"speakerRole":"agent","index":106,"text":"解押好之后，","beginTime":204692,"endTime":205619,"channelId":0},{"speakerRole":"agent","index":107,"text":"就直接快递到您所在地的哦。","beginTime":205619,"endTime":208194,"channelId":0},{"speakerRole":"agent","index":108,"text":"那那样还好，","beginTime":208194,"endTime":209168,"channelId":0},{"speakerRole":"agent","index":109,"text":"那个还好，","beginTime":209168,"endTime":209947,"channelId":0},{"speakerRole":"agent","index":110,"text":"他这个哎呀我就跑了一趟合肥去解压，","beginTime":209947,"endTime":213062,"channelId":0},{"speakerRole":"agent","index":111,"text":"挺麻烦的。","beginTime":213062,"endTime":213841,"channelId":0},{"speakerRole":"agent","index":112,"text":"哎，","beginTime":213841,"endTime":214035,"channelId":0},{"speakerRole":"agent","index":113,"text":"对，","beginTime":214035,"endTime":214230,"channelId":0},{"speakerRole":"agent","index":114,"text":"就不需要你自己跑的。","beginTime":214230,"endTime":215982,"channelId":0},{"speakerRole":"agent","index":115,"text":"因为我们这个全程都是线上的，","beginTime":215982,"endTime":218513,"channelId":0},{"speakerRole":"agent","index":116,"text":"是吧？","beginTime":218513,"endTime":218903,"channelId":0},{"speakerRole":"agent","index":117,"text":"包括您办理，","beginTime":218903,"endTime":219876,"channelId":0},{"speakerRole":"agent","index":118,"text":"然后嗯这个解押这些都是免费的，","beginTime":219876,"endTime":222602,"channelId":0},{"speakerRole":"agent","index":119,"text":"我们不收任何费用。","beginTime":222602,"endTime":224160,"channelId":0},{"speakerRole":"agent","index":120,"text":"还有我们这个里面不要不要这个费用，","beginTime":224160,"endTime":227275,"channelId":0},{"speakerRole":"agent","index":121,"text":"钥匙，","beginTime":227275,"endTime":227664,"channelId":0},{"speakerRole":"agent","index":122,"text":"不要这个呃不充g p s连车都不用看。","beginTime":227664,"endTime":230780,"channelId":0},{"speakerRole":"agent","index":123,"text":"嗯嗯，","beginTime":231820,"endTime":232192,"channelId":0},{"speakerRole":"agent","index":124,"text":"哦那我现在这个额度你给我说的，","beginTime":232192,"endTime":234803,"channelId":0},{"speakerRole":"agent","index":125,"text":"就是说我上面显示的让你给他不是哎，","beginTime":234803,"endTime":238677,"channelId":0},{"speakerRole":"agent","index":126,"text":"它现在显示额度是九万零九百。","beginTime":238677,"endTime":241238,"channelId":0},{"speakerRole":"agent","index":127,"text":"然后一会儿他通过审核之后，","beginTime":241238,"endTime":243603,"channelId":0},{"speakerRole":"agent","index":128,"text":"他主要是根据您爱科的价格来给您判断的。","beginTime":243603,"endTime":247150,"channelId":0},{"speakerRole":"agent","index":129,"text":"因为您现在的爱车的价值有十万零九千，","beginTime":247150,"endTime":250500,"channelId":0},{"speakerRole":"agent","index":130,"text":"嗯，","beginTime":251260,"endTime":251472,"channelId":0},{"speakerRole":"agent","index":131,"text":"哎然后，","beginTime":251472,"endTime":252109,"channelId":0},{"speakerRole":"agent","index":132,"text":"它会根据您爱车的价值，","beginTime":252109,"endTime":254231,"channelId":0},{"speakerRole":"agent","index":133,"text":"然后再加上您个人的资质，","beginTime":254231,"endTime":256566,"channelId":0},{"speakerRole":"agent","index":134,"text":"就说看能不能把这个额度再稍微降一点。","beginTime":256566,"endTime":260175,"channelId":0},{"speakerRole":"agent","index":135,"text":"如果是确实最近大数据花了的话，","beginTime":260175,"endTime":263147,"channelId":0},{"speakerRole":"agent","index":136,"text":"查询多了，","beginTime":263147,"endTime":263996,"channelId":0},{"speakerRole":"agent","index":137,"text":"它这个额度也可能会降，","beginTime":263996,"endTime":266118,"channelId":0},{"speakerRole":"agent","index":138,"text":"就是这样的。","beginTime":266118,"endTime":267180,"channelId":0},{"speakerRole":"agent","index":139,"text":"没事，","beginTime":267180,"endTime":267604,"channelId":0},{"speakerRole":"agent","index":140,"text":"那那就下一步怎么操作呢？","beginTime":267604,"endTime":269939,"channelId":0},{"speakerRole":"agent","index":141,"text":"嗯，","beginTime":269939,"endTime":270151,"channelId":0},{"speakerRole":"agent","index":142,"text":"哥，","beginTime":270151,"endTime":270364,"channelId":0},{"speakerRole":"agent","index":143,"text":"我这边用企业微信添加你一个好友了，","beginTime":270364,"endTime":273760,"channelId":0},{"speakerRole":"agent","index":144,"text":"你点开这个平时微信聊天记录，","beginTime":273760,"endTime":276520,"channelId":0},{"speakerRole":"agent","index":145,"text":"那就等我闲闲起来吧。","beginTime":276800,"endTime":278420,"channelId":0},{"speakerRole":"agent","index":146,"text":"然后今天我要去拍添加了，","beginTime":278420,"endTime":280400,"channelId":0},{"speakerRole":"agent","index":147,"text":"人家马上到点了啊，","beginTime":280400,"endTime":282073,"channelId":0},{"speakerRole":"agent","index":148,"text":"您可以先把我这个企业微信通过嘛，","beginTime":282073,"endTime":284673,"channelId":0},{"speakerRole":"agent","index":149,"text":"要不然您您什么时候有空了，","beginTime":284673,"endTime":286753,"channelId":0},{"speakerRole":"agent","index":150,"text":"您跟我说。","beginTime":286753,"endTime":287446,"channelId":0},{"speakerRole":"agent","index":151,"text":"然后因为我这个是外部电话嘛，","beginTime":287446,"endTime":289700,"channelId":0},{"speakerRole":"agent","index":152,"text":"到时候又又找不到我。","beginTime":289700,"endTime":291260,"channelId":0},{"speakerRole":"agent","index":153,"text":"好，","beginTime":291500,"endTime":291680,"channelId":0},{"speakerRole":"agent","index":154,"text":"那你加我，","beginTime":291680,"endTime":292402,"channelId":0},{"speakerRole":"agent","index":155,"text":"等他，","beginTime":292402,"endTime":292762,"channelId":0},{"speakerRole":"agent","index":156,"text":"等一下，","beginTime":292762,"endTime":293304,"channelId":0},{"speakerRole":"agent","index":157,"text":"我同意一下。","beginTime":293304,"endTime":294206,"channelId":0},{"speakerRole":"agent","index":158,"text":"哎，","beginTime":294206,"endTime":294386,"channelId":0},{"speakerRole":"agent","index":159,"text":"你打开平时微信聊天界面，","beginTime":294386,"endTime":296371,"channelId":0},{"speakerRole":"agent","index":160,"text":"他有一个服务通知，","beginTime":296371,"endTime":297814,"channelId":0},{"speakerRole":"agent","index":161,"text":"一个成熟的小伙伴，","beginTime":297814,"endTime":299258,"channelId":0},{"speakerRole":"agent","index":162,"text":"你看一下，","beginTime":299258,"endTime":299980,"channelId":0},{"speakerRole":"agent","index":163,"text":"我记得我加过你们的啊。","beginTime":301020,"endTime":303313,"channelId":0},{"speakerRole":"agent","index":164,"text":"嗯之前可能是在其他同事那边说，","beginTime":303313,"endTime":306584,"channelId":0},{"speakerRole":"agent","index":165,"text":"现在是我来为您办理的。","beginTime":306584,"endTime":308920,"channelId":0},{"speakerRole":"agent","index":166,"text":"这个不影响的，","beginTime":312520,"endTime":313612,"channelId":0},{"speakerRole":"agent","index":167,"text":"反正您看你在哪里办都是可以的。","beginTime":313612,"endTime":316160,"channelId":0},{"speakerRole":"agent","index":168,"text":"没有没有没有显示你加过来。","beginTime":317140,"endTime":319400,"channelId":0},{"speakerRole":"agent","index":169,"text":"嗯，","beginTime":320620,"endTime":321920,"channelId":0},{"speakerRole":"agent","index":170,"text":"您加的是哪一个大哥？","beginTime":323820,"endTime":325700,"channelId":0},{"speakerRole":"agent","index":171,"text":"我这边我这边听不到声音啊，","beginTime":329380,"endTime":331743,"channelId":0},{"speakerRole":"agent","index":172,"text":"哥。","beginTime":331743,"endTime":331940,"channelId":0},{"speakerRole":"agent","index":173,"text":"我这边叫阮杰，","beginTime":338640,"endTime":339999,"channelId":0},{"speakerRole":"agent","index":174,"text":"您看一下有没有，","beginTime":339999,"endTime":341584,"channelId":0},{"speakerRole":"agent","index":175,"text":"我给你发了一个嗯这个服务通知，","beginTime":341584,"endTime":344755,"channelId":0},{"speakerRole":"agent","index":176,"text":"一个二维码长按识别就可以添加到我。","beginTime":344755,"endTime":348380,"channelId":0},{"speakerRole":"agent","index":177,"text":"看到嗯嗯有有叫转接的吗？","beginTime":353880,"endTime":356973,"channelId":0},{"speakerRole":"agent","index":178,"text":"您拍二维码直接就可以添加到我。","beginTime":356973,"endTime":359980,"channelId":0},{"speakerRole":"agent","index":179,"text":"五月哥，","beginTime":370960,"endTime":371696,"channelId":0},{"speakerRole":"agent","index":180,"text":"我这边又听不见了。","beginTime":371696,"endTime":373660,"channelId":0},{"speakerRole":"agent","index":181,"text":"哎，","beginTime":375380,"endTime":375576,"channelId":0},{"speakerRole":"agent","index":182,"text":"我那那等一下弄吧，","beginTime":375576,"endTime":377145,"channelId":0},{"speakerRole":"agent","index":183,"text":"等一下弄，","beginTime":377145,"endTime":377930,"channelId":0},{"speakerRole":"agent","index":184,"text":"等一下，","beginTime":377930,"endTime":378518,"channelId":0},{"speakerRole":"agent","index":185,"text":"我到时候闲了，","beginTime":378518,"endTime":379695,"channelId":0},{"speakerRole":"agent","index":186,"text":"我再往弄一下。","beginTime":379695,"endTime":380872,"channelId":0},{"speakerRole":"agent","index":187,"text":"因为现在人家拍婚纱照，","beginTime":380872,"endTime":382834,"channelId":0},{"speakerRole":"agent","index":188,"text":"已经打电话给我了。","beginTime":382834,"endTime":384404,"channelId":0},{"speakerRole":"agent","in