(205492,'rec_84600708dd344b388df67310','ext_2f3b86f4e6284637ba22301ae00e170c','9311da5c-d66e-474b-8d7f-26772065cf2a.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/8ef7e8306b554460a915239872c4bc20.mp3',2,94,'mp3',95400,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"啊，","beginTime":520,"endTime":775,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":775,"endTime":1285,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问是张先生，","beginTime":1285,"endTime":2815,"channelId":0},{"speakerRole":"agent","index":3,"text":"对吧？","beginTime":2815,"endTime":3325,"channelId":0},{"speakerRole":"agent","index":4,"text":"嗯，","beginTime":3325,"endTime":3580,"channelId":0},{"speakerRole":"agent","index":5,"text":"好，","beginTime":3580,"endTime":3835,"channelId":0},{"speakerRole":"agent","index":6,"text":"我这边是支付宝新选车贷的，","beginTime":3835,"endTime":6895,"channelId":0},{"speakerRole":"agent","index":7,"text":"收到，","beginTime":6895,"endTime":7405,"channelId":0},{"speakerRole":"agent","index":8,"text":"您提交了一笔车子的申请，","beginTime":7405,"endTime":10210,"channelId":0},{"speakerRole":"agent","index":9,"text":"对吧？","beginTime":10210,"endTime":10720,"channelId":0},{"speakerRole":"agent","index":10,"text":"嗯嗯，","beginTime":10960,"endTime":11444,"channelId":0},{"speakerRole":"agent","index":11,"text":"您车子现在是全款中还是有贷款在还呢？","beginTime":11444,"endTime":15560,"channelId":0},{"speakerRole":"agent","index":12,"text":"嗯，","beginTime":15900,"endTime":16211,"channelId":0},{"speakerRole":"agent","index":13,"text":"贷款就绿本有没有在身边，","beginTime":16211,"endTime":19640,"channelId":0},{"speakerRole":"agent","index":14,"text":"嗯，","beginTime":20300,"endTime":20691,"channelId":0},{"speakerRole":"agent","index":15,"text":"那边在在后面哦，","beginTime":20691,"endTime":23572,"channelId":0},{"speakerRole":"agent","index":16,"text":"绿本在三遍就有有那个绿本是吧？","beginTime":23572,"endTime":27667,"channelId":0},{"speakerRole":"agent","index":17,"text":"嗯嗯，","beginTime":27667,"endTime":28436,"channelId":0},{"speakerRole":"agent","index":18,"text":"然后我这边的话哈就是稍后用我的那个企业微信添加您。","beginTime":28436,"endTime":34114,"channelId":0},{"speakerRole":"agent","index":19,"text":"您这边通过一下你那个绿本，","beginTime":34114,"endTime":36954,"channelId":0},{"speakerRole":"agent","index":20,"text":"现在在身边方便拍照吗？","beginTime":36954,"endTime":39320,"channelId":0},{"speakerRole":"agent","index":21,"text":"现在我不在家，","beginTime":40280,"endTime":41500,"channelId":0},{"speakerRole":"agent","index":22,"text":"在外面。","beginTime":41500,"endTime":42110,"channelId":0},{"speakerRole":"agent","index":23,"text":"嗯，","beginTime":42110,"endTime":42313,"channelId":0},{"speakerRole":"agent","index":24,"text":"你大概多久回去啊，","beginTime":42313,"endTime":43940,"channelId":0},{"speakerRole":"agent","index":25,"text":"要两三天吧，","beginTime":45140,"endTime":46283,"channelId":0},{"speakerRole":"agent","index":26,"text":"要两三天是吧，","beginTime":46283,"endTime":47655,"channelId":0},{"speakerRole":"agent","index":27,"text":"家里面家里面有没有人可以帮你拍一下照嘛。","beginTime":47655,"endTime":52000,"channelId":0},{"speakerRole":"agent","index":28,"text":"我在外面打工，","beginTime":54180,"endTime":55548,"channelId":0},{"speakerRole":"agent","index":29,"text":"不在老家哦，","beginTime":55548,"endTime":56926,"channelId":0},{"speakerRole":"agent","index":30,"text":"你要两三天才回去啊。","beginTime":56926,"endTime":58965,"channelId":0},{"speakerRole":"agent","index":31,"text":"那因为我们这个它是需要等那个需要那个日本照片才能给你批，","beginTime":58965,"endTime":65081,"channelId":0},{"speakerRole":"agent","index":32,"text":"才能给你过终审的嘛。","beginTime":65081,"endTime":67120,"channelId":0},{"speakerRole":"agent","index":33,"text":"嗯，","beginTime":68760,"endTime":69102,"channelId":0},{"speakerRole":"agent","index":34,"text":"要绿的是吧，","beginTime":69102,"endTime":70813,"channelId":0},{"speakerRole":"agent","index":35,"text":"对，","beginTime":70813,"endTime":71155,"channelId":0},{"speakerRole":"agent","index":36,"text":"绿本呃，","beginTime":71155,"endTime":73182,"channelId":0},{"speakerRole":"agent","index":37,"text":"发票是吧，","beginTime":73182,"endTime":74074,"channelId":0},{"speakerRole":"agent","index":38,"text":"不行，","beginTime":74074,"endTime":74520,"channelId":0},{"speakerRole":"agent","index":39,"text":"发票不行，","beginTime":74760,"endTime":76300,"channelId":0},{"speakerRole":"agent","index":40,"text":"他主要是嗯那我这边我这边先用我的企业微信添加你嘛。","beginTime":77740,"endTime":84254,"channelId":0},{"speakerRole":"agent","index":41,"text":"你回去的时候，","beginTime":84254,"endTime":85345,"channelId":0},{"speakerRole":"agent","index":42,"text":"你就把那个绿本照片拍给就拍了，","beginTime":85345,"endTime":87890,"channelId":0},{"speakerRole":"agent","index":43,"text":"发给我好吧。","beginTime":87890,"endTime":88800,"channelId":0},{"speakerRole":"agent","index":44,"text":"啊，","beginTime":89040,"endTime":89262,"channelId":0},{"speakerRole":"agent","index":45,"text":"好嗯好的，","beginTime":89262,"endTime":90151,"channelId":0},{"speakerRole":"agent","index":46,"text":"我加你了哈，","beginTime":90151,"endTime":91262,"channelId":0},{"speakerRole":"agent","index":47,"text":"你稍后通通过一下。","beginTime":91262,"endTime":93040,"channelId":0},{"speakerRole":"agent","index":48,"text":"嗯嗯，","beginTime":93280,"endTime":94173,"channelId":0},{"speakerRole":"agent","index":49,"text":"好。","beginTime":94173,"endTime":94620,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:10:47','2026-05-22 01:10:49','2026-05-22 01:10:46','2026-05-22 01:10:49','system','system','BATCH-20260522-030772',NULL),
(205493,'rec_868e104dc29441809cdefce0','ext_f05dd89b264b4d1c9b5f19e994103db2','547409ef-536b-4b60-b173-58769f74cdf2.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/03ff17d8bab64d1eb4ad00356ebd038b.mp3',2,162,'mp3',163728,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎哎喂，","beginTime":1860,"endTime":3212,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":3212,"endTime":3604,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问是手机尾号八八九八的罗先生是吧？","beginTime":3604,"endTime":6940,"channelId":0},{"speakerRole":"agent","index":3,"text":"啊，","beginTime":7280,"endTime":7475,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎，","beginTime":7475,"endTime":7671,"channelId":0},{"speakerRole":"agent","index":5,"text":"这边的话看到您在支付宝金选车的申请了一笔贷款额度，","beginTime":7671,"endTime":12365,"channelId":0},{"speakerRole":"agent","index":6,"text":"然后您这边是已经提交了资料，","beginTime":12365,"endTime":14908,"channelId":0},{"speakerRole":"agent","index":7,"text":"对吧？","beginTime":14908,"endTime":15300,"channelId":0},{"speakerRole":"agent","index":8,"text":"对，","beginTime":15800,"endTime":16520,"channelId":0},{"speakerRole":"agent","index":9,"text":"哎，","beginTime":16760,"endTime":16920,"channelId":0},{"speakerRole":"agent","index":10,"text":"给您来电的话，","beginTime":16920,"endTime":17883,"channelId":0},{"speakerRole":"agent","index":11,"text":"就是简单跟您核实一下您申请的这辆车是您本人名下的全款车辆吗？","beginTime":17883,"endTime":22540,"channelId":0},{"speakerRole":"agent","index":12,"text":"贷款出来对，","beginTime":24040,"endTime":25440,"channelId":0},{"speakerRole":"agent","index":13,"text":"贷款的绿本在你手中，","beginTime":25680,"endTime":27412,"channelId":0},{"speakerRole":"agent","index":14,"text":"还是在银行的呀，","beginTime":27412,"endTime":28760,"channelId":0},{"speakerRole":"agent","index":15,"text":"啊在我手上呢哦那是可以的。","beginTime":29460,"endTime":33704,"channelId":0},{"speakerRole":"agent","index":16,"text":"但是这边看到您传资料的时候，","beginTime":33704,"endTime":35925,"channelId":0},{"speakerRole":"agent","index":17,"text":"只传了行驶证的照片，","beginTime":35925,"endTime":37462,"channelId":0},{"speakerRole":"agent","index":18,"text":"稍后的话可能会补一下那个绿本的一个照片。","beginTime":37462,"endTime":40707,"channelId":0},{"speakerRole":"agent","index":19,"text":"您的那个手机号码好像搜不到您的微信，","beginTime":40707,"endTime":43610,"channelId":0},{"speakerRole":"agent","index":20,"text":"您看方便加一下我的微信吗？","beginTime":43610,"endTime":45660,"channelId":0},{"speakerRole":"agent","index":21,"text":"多少，","beginTime":46680,"endTime":47486,"channelId":0},{"speakerRole":"agent","index":22,"text":"嗯，","beginTime":47486,"endTime":47890,"channelId":0},{"speakerRole":"agent","index":23,"text":"幺三二。","beginTime":47890,"endTime":49100,"channelId":0},{"speakerRole":"agent","index":24,"text":"幺三二，","beginTime":54460,"endTime":55380,"channelId":0},{"speakerRole":"agent","index":25,"text":"然后嘞，","beginTime":55380,"endTime":56300,"channelId":0},{"speakerRole":"agent","index":26,"text":"七二六三四三，","beginTime":56300,"endTime":58140,"channelId":0},{"speakerRole":"agent","index":27,"text":"幺三二七二六三五零幺三，","beginTime":58680,"endTime":61760,"channelId":0},{"speakerRole":"agent","index":28,"text":"我要的，","beginTime":62540,"endTime":63060,"channelId":0},{"speakerRole":"agent","index":29,"text":"但是我现在那个本没有在身上，","beginTime":63060,"endTime":65313,"channelId":0},{"speakerRole":"agent","index":30,"text":"我在外地也可以吗？","beginTime":65313,"endTime":66700,"channelId":0},{"speakerRole":"agent","index":31,"text":"呃，","beginTime":67180,"endTime":67373,"channelId":0},{"speakerRole":"agent","index":32,"text":"您的本人没有在身上，","beginTime":67373,"endTime":69118,"channelId":0},{"speakerRole":"agent","index":33,"text":"这笔资金大概准备什么时候再使用呢？","beginTime":69118,"endTime":72220,"channelId":0},{"speakerRole":"agent","index":34,"text":"越快越快越好吧。","beginTime":73940,"endTime":75289,"channelId":0},{"speakerRole":"agent","index":35,"text":"呃，","beginTime":75289,"endTime":75481,"channelId":0},{"speakerRole":"agent","index":36,"text":"如果因为咱们是需要补那个绿本的一个资料的那您是照片，","beginTime":75481,"endTime":80300,"channelId":0},{"speakerRole":"agent","index":37,"text":"这些也不方便提交啊。","beginTime":80300,"endTime":82034,"channelId":0},{"speakerRole":"agent","index":38,"text":"家里面有人可以帮您弄一下吗？","beginTime":82034,"endTime":84540,"channelId":0},{"speakerRole":"agent","index":39,"text":"嗯，","beginTime":86640,"endTime":86838,"channelId":0},{"speakerRole":"agent","index":40,"text":"然后的话日本发给你就行了，","beginTime":86838,"endTime":89222,"channelId":0},{"speakerRole":"agent","index":41,"text":"是吗？","beginTime":89222,"endTime":89620,"channelId":0},{"speakerRole":"agent","index":42,"text":"嗯，","beginTime":90040,"endTime":90212,"channelId":0},{"speakerRole":"agent","index":43,"text":"对对对，","beginTime":90212,"endTime":90731,"channelId":0},{"speakerRole":"agent","index":44,"text":"然后咱们这边先提交资料审核，","beginTime":90731,"endTime":92978,"channelId":0},{"speakerRole":"agent","index":45,"text":"如果审核通过了，","beginTime":92978,"endTime":94188,"channelId":0},{"speakerRole":"agent","index":46,"text":"您觉得满意的话，","beginTime":94188,"endTime":95398,"channelId":0},{"speakerRole":"agent","index":47,"text":"咱们再走后续放款流程。","beginTime":95398,"endTime":97126,"channelId":0},{"speakerRole":"agent","index":48,"text":"嗯，","beginTime":97126,"endTime":97299,"channelId":0},{"speakerRole":"agent","index":49,"text":"如果您的日本就是不方便的话，","beginTime":97299,"endTime":99546,"channelId":0},{"speakerRole":"agent","index":50,"text":"也可以申请补办一个，","beginTime":99546,"endTime":101101,"channelId":0},{"speakerRole":"agent","index":51,"text":"就直接车管所线上补办，","beginTime":101101,"endTime":102830,"channelId":0},{"speakerRole":"agent","index":52,"text":"它可以邮寄给您啊。","beginTime":102830,"endTime":105904,"channelId":0},{"speakerRole":"agent","index":53,"text":"这种就是说我知道意思是说那个绿本这个要用绿本正常流程的话，","beginTime":105904,"endTime":111616,"channelId":0},{"speakerRole":"agent","index":54,"text":"是要绿本才可以才可以用，","beginTime":111616,"endTime":113860,"channelId":0},{"speakerRole":"agent","index":55,"text":"是不是？","beginTime":113860,"endTime":114472,"channelId":0},{"speakerRole":"agent","index":56,"text":"对对对，","beginTime":114472,"endTime":115084,"channelId":0},{"speakerRole":"agent","index":57,"text":"所有的车贷都是这样的，","beginTime":115084,"endTime":117124,"channelId":0},{"speakerRole":"agent","index":58,"text":"都是需要您车辆的一个绿本。","beginTime":117124,"endTime":119572,"channelId":0},{"speakerRole":"agent","index":59,"text":"因为在贷款期间的话，","beginTime":119572,"endTime":121969,"channelId":0},{"speakerRole":"agent","index":60,"text":"车辆是不能过户交易买卖的，","beginTime":121969,"endTime":124111,"channelId":0},{"speakerRole":"agent","index":61,"text":"但是不会影响您车辆的正常行驶。","beginTime":124111,"endTime":126610,"channelId":0},{"speakerRole":"agent","index":62,"text":"因为绿本的话，","beginTime":126610,"endTime":127681,"channelId":0},{"speakerRole":"agent","index":63,"text":"平时也不会用到，","beginTime":127681,"endTime":128931,"channelId":0},{"speakerRole":"agent","index":64,"text":"除了就过户的时候需要使用绿外，","beginTime":128931,"endTime":131430,"channelId":0},{"speakerRole":"agent","index":65,"text":"其他时候违章年检，","beginTime":131430,"endTime":132858,"channelId":0},{"speakerRole":"agent","index":66,"text":"这些都不是都不需要使用的。","beginTime":132858,"endTime":135000,"channelId":0},{"speakerRole":"agent","index":67,"text":"我还有一个车是是在抵押状态，","beginTime":135600,"endTime":138668,"channelId":0},{"speakerRole":"agent","index":68,"text":"就是不能用了吧。","beginTime":138668,"endTime":140320,"channelId":0},{"speakerRole":"agent","index":69,"text":"抵押状态的话，","beginTime":140560,"endTime":141702,"channelId":0},{"speakerRole":"agent","index":70,"text":"那您的绿本应该是在银行或者是四s店的吧。","beginTime":141702,"endTime":145320,"channelId":0},{"speakerRole":"agent","index":71,"text":"啊，","beginTime":145720,"endTime":145899,"channelId":0},{"speakerRole":"agent","index":72,"text":"对，","beginTime":145899,"endTime":146078,"channelId":0},{"speakerRole":"agent","index":73,"text":"然后另外那个车就不能做这个贷款难回来。","beginTime":146078,"endTime":149301,"channelId":0},{"speakerRole":"agent","index":74,"text":"对对对对，","beginTime":149301,"endTime":150018,"channelId":0},{"speakerRole":"agent","index":75,"text":"但是您目前这个绿本在手的这个车是可以做的哦。","beginTime":150018,"endTime":154535,"channelId":0},{"speakerRole":"agent","index":76,"text":"那我明白了明白了。","beginTime":154535,"endTime":155943,"channelId":0},{"speakerRole":"agent","index":77,"text":"对对对，","beginTime":155943,"endTime":156470,"channelId":0},{"speakerRole":"agent","index":78,"text":"发给你了，","beginTime":156470,"endTime":157174,"channelId":0},{"speakerRole":"agent","index":79,"text":"加你。","beginTime":157174,"endTime":157526,"channelId":0},{"speakerRole":"agent","index":80,"text":"哎，","beginTime":157526,"endTime":157702,"channelId":0},{"speakerRole":"agent","index":81,"text":"好好，","beginTime":157702,"endTime":158054,"channelId":0},{"speakerRole":"agent","index":82,"text":"你加我微信吧。","beginTime":158054,"endTime":159109,"channelId":0},{"speakerRole":"agent","index":83,"text":"哎，","beginTime":159109,"endTime":159285,"channelId":0},{"speakerRole":"agent","index":84,"text":"好的，","beginTime":159285,"endTime":159637,"channelId":0},{"speakerRole":"agent","index":85,"text":"好，","beginTime":159637,"endTime":159813,"channelId":0},{"speakerRole":"agent","index":86,"text":"那就先不打扰您了哈。","beginTime":159813,"endTime":161396,"channelId":0},{"speakerRole":"agent","index":87,"text":"嗯好，","beginTime":161396,"endTime":161748,"channelId":0},{"speakerRole":"agent","index":88,"text":"再见。","beginTime":161748,"endTime":162100,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:10:52','2026-05-22 01:10:55','2026-05-22 01:10:48','2026-05-22 01:10:55','system','system','BATCH-20260522-030772',NULL),
