(205497,'rec_77cb343257a24cbfaff46e42','ext_79142c9ec61c4d0dbe8084333838faa4','c4de936b-c283-4b7d-8281-1b9050484cbf.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/16788873b087464ca6d1de63e3999424.mp3',2,84,'mp3',84672,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"而且喂请问这是刘女士吗？","beginTime":1420,"endTime":6404,"channelId":0},{"speakerRole":"agent","index":1,"text":"哪位？","beginTime":6404,"endTime":7060,"channelId":0},{"speakerRole":"agent","index":2,"text":"你好，","beginTime":7300,"endTime":7700,"channelId":0},{"speakerRole":"agent","index":3,"text":"梁女士，","beginTime":7700,"endTime":8300,"channelId":0},{"speakerRole":"agent","index":4,"text":"我这边是支付宝，","beginTime":8300,"endTime":9700,"channelId":0},{"speakerRole":"agent","index":5,"text":"谢谢汽车咨询经理，","beginTime":9700,"endTime":11300,"channelId":0},{"speakerRole":"agent","index":6,"text":"谢谢您先生。","beginTime":11300,"endTime":12300,"channelId":0},{"speakerRole":"agent","index":7,"text":"昨天晚上八点多，","beginTime":12300,"endTime":13700,"channelId":0},{"speakerRole":"agent","index":8,"text":"钟瑜在您付款申请的车子，","beginTime":13700,"endTime":15900,"channelId":0},{"speakerRole":"agent","index":9,"text":"在我们这边通知你，","beginTime":15900,"endTime":17500,"channelId":0},{"speakerRole":"agent","index":10,"text":"通过合同签，","beginTime":17500,"endTime":18500,"channelId":0},{"speakerRole":"agent","index":11,"text":"你还把这个信息就是定了是吧？","beginTime":18500,"endTime":21100,"channelId":0},{"speakerRole":"agent","index":12,"text":"呃，","beginTime":22780,"endTime":23078,"channelId":0},{"speakerRole":"agent","index":13,"text":"我昨天查看了一下，","beginTime":23078,"endTime":25463,"channelId":0},{"speakerRole":"agent","index":14,"text":"暂时我在呃，","beginTime":25463,"endTime":28039,"channelId":0},{"speakerRole":"agent","index":15,"text":"是这样的哈，","beginTime":28039,"endTime":29035,"channelId":0},{"speakerRole":"agent","index":16,"text":"您这边也是查了您的微信哈。","beginTime":29035,"endTime":31427,"channelId":0},{"speakerRole":"agent","index":17,"text":"您看这边的话就是已经过我来电话时核对您的信息，","beginTime":31427,"endTime":35812,"channelId":0},{"speakerRole":"agent","index":18,"text":"显示您去放款，","beginTime":35812,"endTime":37008,"channelId":0},{"speakerRole":"agent","index":19,"text":"放款是由我这边来给您处理办理。","beginTime":37008,"endTime":39798,"channelId":0},{"speakerRole":"agent","index":20,"text":"然后这边就是额就是六万九千八的，","beginTime":39798,"endTime":42788,"channelId":0},{"speakerRole":"agent","index":21,"text":"这这个是您本人名下的吗？","beginTime":42788,"endTime":44980,"channelId":0},{"speakerRole":"agent","index":22,"text":"这a九八九。","beginTime":44980,"endTime":47720,"channelId":0},{"speakerRole":"agent","index":23,"text":"是的呃，","beginTime":48120,"endTime":49481,"channelId":0},{"speakerRole":"agent","index":24,"text":"它是目前是全款的吗？","beginTime":49481,"endTime":51291,"channelId":0},{"speakerRole":"agent","index":25,"text":"还是有按揭贷款呢？","beginTime":51291,"endTime":52900,"channelId":0},{"speakerRole":"agent","index":26,"text":"按揭在还呃，","beginTime":53780,"endTime":55622,"channelId":0},{"speakerRole":"agent","index":27,"text":"还有多久结束，","beginTime":55622,"endTime":57200,"channelId":0},{"speakerRole":"agent","index":28,"text":"还有多久结束？","beginTime":58380,"endTime":61200,"channelId":0},{"speakerRole":"agent","index":29,"text":"对嗯。","beginTime":61200,"endTime":62140,"channelId":0},{"speakerRole":"agent","index":30,"text":"还有一年多吧，","beginTime":67320,"endTime":68702,"channelId":0},{"speakerRole":"agent","index":31,"text":"哦那你的日本是可以做到抵押的呀，","beginTime":68702,"endTime":72160,"channelId":0},{"speakerRole":"agent","index":32,"text":"没有拿回来是吧？","beginTime":72640,"endTime":74337,"channelId":0},{"speakerRole":"agent","index":33,"text":"嗯，","beginTime":74337,"endTime":74580,"channelId":0},{"speakerRole":"agent","index":34,"text":"对哦，","beginTime":74940,"endTime":76240,"channelId":0},{"speakerRole":"agent","index":35,"text":"那暂时打理不用了，","beginTime":76240,"endTime":77680,"channelId":0},{"speakerRole":"agent","index":36,"text":"因为我们做全款车有一本，","beginTime":77680,"endTime":80280,"channelId":0},{"speakerRole":"agent","index":37,"text":"好吧，","beginTime":80620,"endTime":81158,"channelId":0},{"speakerRole":"agent","index":38,"text":"那打扰您了哦。","beginTime":81158,"endTime":82774,"channelId":0},{"speakerRole":"agent","index":39,"text":"哎好，","beginTime":82774,"endTime":83313,"channelId":0},{"speakerRole":"agent","index":40,"text":"再见。","beginTime":83313,"endTime":83852,"channelId":0},{"speakerRole":"agent","index":41,"text":"嗯，","beginTime":83852,"endTime":84121,"channelId":0},{"speakerRole":"agent","index":42,"text":"好的。","beginTime":84121,"endTime":84660,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:10:57','2026-05-22 01:10:59','2026-05-22 01:10:52','2026-05-22 01:10:59','system','system','BATCH-20260522-030772',NULL),
(205498,'rec_9ef8ff5ee27d41049dcda433','ext_70941a18a79e42dbadbe0bf08057f801','ccd07003-6cea-4bc9-9a2a-afffdfffcc15.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/0cf9ed90cf1d4f6688626cde35a6275a.mp3',2,120,'mp3',120816,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎，","beginTime":740,"endTime":920,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":920,"endTime":1281,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问是李先生是吧？","beginTime":1281,"endTime":2725,"channelId":0},{"speakerRole":"agent","index":3,"text":"哎，","beginTime":2725,"endTime":2905,"channelId":0},{"speakerRole":"agent","index":4,"text":"对哪位？","beginTime":2905,"endTime":3446,"channelId":0},{"speakerRole":"agent","index":5,"text":"哎，","beginTime":3446,"endTime":3627,"channelId":0},{"speakerRole":"agent","index":6,"text":"李先生您好，","beginTime":3627,"endTime":4529,"channelId":0},{"speakerRole":"agent","index":7,"text":"我这边是支付宝精选特价的放款专员哈。","beginTime":4529,"endTime":7597,"channelId":0},{"speakerRole":"agent","index":8,"text":"就是您今今天凌晨的时候，","beginTime":7597,"endTime":9582,"channelId":0},{"speakerRole":"agent","index":9,"text":"不是在支付宝申请了一笔资金嘛，","beginTime":9582,"endTime":12108,"channelId":0},{"speakerRole":"agent","index":10,"text":"我都有在发那个啊，","beginTime":12108,"endTime":13552,"channelId":0},{"speakerRole":"agent","index":11,"text":"不是不不是，","beginTime":13552,"endTime":14454,"channelId":0},{"speakerRole":"agent","index":12,"text":"那个我看你那个你那个太吓人了，","beginTime":14454,"endTime":16980,"channelId":0},{"speakerRole":"agent","index":13,"text":"你是看到那个利息，","beginTime":16980,"endTime":18424,"channelId":0},{"speakerRole":"agent","index":14,"text":"觉得利息太高了是吧，","beginTime":18424,"endTime":20048,"channelId":0},{"speakerRole":"agent","index":15,"text":"你说二十万，","beginTime":20048,"endTime":20950,"channelId":0},{"speakerRole":"agent","index":16,"text":"他那个三年他妈八万块钱利息，","beginTime":20950,"endTime":23296,"channelId":0},{"speakerRole":"agent","index":17,"text":"你真的太恐怖了。","beginTime":23296,"endTime":24560,"channelId":0},{"speakerRole":"agent","index":18,"text":"算了算了，","beginTime":24560,"endTime":25281,"channelId":0},{"speakerRole":"agent","index":19,"text":"您看到的那个利息哈，","beginTime":25281,"endTime":26905,"channelId":0},{"speakerRole":"agent","index":20,"text":"您先听我讲吧。","beginTime":26905,"endTime":27988,"channelId":0},{"speakerRole":"agent","index":21,"text":"对，","beginTime":27988,"endTime":28169,"channelId":0},{"speakerRole":"agent","index":22,"text":"就是您看到的利息。","beginTime":28169,"endTime":29612,"channelId":0},{"speakerRole":"agent","index":23,"text":"第一个它是它是您目前只是一个预估状态，","beginTime":29612,"endTime":32860,"channelId":0},{"speakerRole":"agent","index":24,"text":"就是进只进行那个初审的一个预估状态。","beginTime":32860,"endTime":35928,"channelId":0},{"speakerRole":"agent","index":25,"text":"它并不是说您最后的一个那个最终的一个利息合格，","beginTime":35928,"endTime":39898,"channelId":0},{"speakerRole":"agent","index":26,"text":"就是这样的。","beginTime":39898,"endTime":40800,"channelId":0},{"speakerRole":"agent","index":27,"text":"因为您自己也能看到，","beginTime":40800,"endTime":42425,"channelId":0},{"speakerRole":"agent","index":28,"text":"就是它有一行提示叫做呃最终的额度和利息，","beginTime":42425,"endTime":45853,"channelId":0},{"speakerRole":"agent","index":29,"text":"以实际放款为主。","beginTime":45853,"endTime":47116,"channelId":0},{"speakerRole":"agent","index":30,"text":"这个您看到了吧？","beginTime":47116,"endTime":48380,"channelId":0},{"speakerRole":"agent","index":31,"text":"他那个你像我这个借二十万，","beginTime":48700,"endTime":50690,"channelId":0},{"speakerRole":"agent","index":32,"text":"如果的话，","beginTime":50690,"endTime":51354,"channelId":0},{"speakerRole":"agent","index":33,"text":"只要一两个月还的话，","beginTime":51354,"endTime":52847,"channelId":0},{"speakerRole":"agent","index":34,"text":"他那个是怎么算利息，","beginTime":52847,"endTime":54340,"channelId":0},{"speakerRole":"agent","index":35,"text":"我不要几年的，","beginTime":54340,"endTime":55335,"channelId":0},{"speakerRole":"agent","index":36,"text":"我只要这几个月就行了，","beginTime":55335,"endTime":56994,"channelId":0},{"speakerRole":"agent","index":37,"text":"再到年底几个月就行了，","beginTime":56994,"endTime":58652,"channelId":0},{"speakerRole":"agent","index":38,"text":"提前还嘛几个月的那他就是这样的呀。","beginTime":58652,"endTime":61353,"channelId":0},{"speakerRole":"agent","index":39,"text":"就是您用多久产生多久的利息的呀？","beginTime":61353,"endTime":63890,"channelId":0},{"speakerRole":"agent","index":40,"text":"是这样的哥，","beginTime":63890,"endTime":64736,"channelId":0},{"speakerRole":"agent","index":41,"text":"而且它上面还有些什么，","beginTime":64736,"endTime":66427,"channelId":0},{"speakerRole":"agent","index":42,"text":"你要提前还赔付呃，","beginTime":66427,"endTime":67781,"channelId":0},{"speakerRole":"agent","index":43,"text":"赔付违约金什么什么玩意儿，","beginTime":67781,"endTime":69810,"channelId":0},{"speakerRole":"agent","index":44,"text":"你就没看上面写了吗？","beginTime":69810,"endTime":71333,"channelId":0},{"speakerRole":"agent","index":45,"text":"他违约金这个东西它确实是有还有误违约金，","beginTime":71333,"endTime":74547,"channelId":0},{"speakerRole":"agent","index":46,"text":"但是它是这样的一个一个情况才会产生。","beginTime":74547,"endTime":77422,"channelId":0},{"speakerRole":"agent","index":47,"text":"就是一年以内基金结清的话，","beginTime":77422,"endTime":79452,"channelId":0},{"speakerRole":"agent","index":48,"text":"它才会产生一个违约金违约金的。","beginTime":79452,"endTime":81820,"channelId":0},{"speakerRole":"agent","index":49,"text":"呃，","beginTime":81820,"endTime":81990,"channelId":0},{"speakerRole":"agent","index":50,"text":"对啊，","beginTime":81990,"endTime":82328,"channelId":0},{"speakerRole":"agent","index":51,"text":"我提前还没，","beginTime":82328,"endTime":83174,"channelId":0},{"speakerRole":"agent","index":52,"text":"他是这样的违约金，","beginTime":83174,"endTime":84802,"channelId":0},{"speakerRole":"agent","index":53,"text":"他是这样的哈哥就是一年以内结结清的话，","beginTime":84802,"endTime":87696,"channelId":0},{"speakerRole":"agent","index":54,"text":"会有一个剩余本金的百分之四的一个违约金。","beginTime":87696,"endTime":90752,"channelId":0},{"speakerRole":"agent","index":55,"text":"就是比如说您生的违金有个一万块钱，","beginTime":90752,"endTime":93325,"channelId":0},{"speakerRole":"agent","index":56,"text":"他就是四百块钱的一个违约金，","beginTime":93325,"endTime":95415,"channelId":0},{"speakerRole":"agent","index":57,"text":"是这这种形式。","beginTime":95415,"endTime":96380,"channelId":0},{"speakerRole":"agent","index":58,"text":"然后一年以后基金结清的话，","beginTime":96380,"endTime":98310,"channelId":0},{"speakerRole":"agent","index":59,"text":"它是没有任何违约金存在的。","beginTime":98310,"endTime":100240,"channelId":0},{"speakerRole":"agent","index":60,"text":"那算了算了算了算了，","beginTime":101520,"endTime":103288,"channelId":0},{"speakerRole":"agent","index":61,"text":"太麻烦了，","beginTime":103288,"endTime":104074,"channelId":0},{"speakerRole":"agent","index":62,"text":"你去看吧，","beginTime":104074,"endTime":104860,"channelId":0},{"speakerRole":"agent","index":63,"text":"有违约金，","beginTime":105100,"endTime":105754,"channelId":0},{"speakerRole":"agent","index":64,"text":"这个东西是所有平台它都是有的呀。","beginTime":105754,"endTime":108209,"channelId":0},{"speakerRole":"agent","index":65,"text":"对，","beginTime":108209,"endTime":108373,"channelId":0},{"speakerRole":"agent","index":66,"text":"就认为也不是我只有我们这有，","beginTime":108373,"endTime":110501,"channelId":0},{"speakerRole":"agent","index":67,"text":"而且违约金的话，","beginTime":110501,"endTime":111647,"channelId":0},{"speakerRole":"agent","index":68,"text":"我们才百分之四的一个违金，","beginTime":111647,"endTime":113611,"channelId":0},{"speakerRole":"agent","index":69,"text":"比那些百五百六十块钱，","beginTime":113611,"endTime":115248,"channelId":0},{"speakerRole":"agent","index":70,"text":"现在都低很多。","beginTime":115248,"endTime":116230,"channelId":0},{"speakerRole":"agent","index":71,"text":"没事，","beginTime":116230,"endTime":116557,"channelId":0},{"speakerRole":"agent","index":72,"text":"我在我我我在邮政上面去搞吧。","beginTime":116557,"endTime":118685,"channelId":0},{"speakerRole":"agent","index":73,"text":"好，","beginTime":118685,"endTime":118848,"channelId":0},{"speakerRole":"agent","index":74,"text":"现在嗯您是。","beginTime":118848,"endTime":120800,"channelId":0}]}',80,NULL,NULL,0,0,2,'2026-05-22 01:10:57','2026-05-22 01:11:02','2026-05-22 01:10:54','2026-05-22 01:11:02','system','system','BATCH-20260522-030772',NULL),
