(205516,'rec_c4404ce274d8448ca92a256c','ext_c31a6182c3124e6481db289d94bec01f','00873cd7-4467-434f-a73f-b1189caf9a89.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/0f4125e0ab0d4b598e1c70b535ddbbfc.mp3',2,164,'mp3',166824,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"你好喂你好，","beginTime":1120,"endTime":2443,"channelId":0},{"speakerRole":"agent","index":1,"text":"请问是六六五的刘先生吗？","beginTime":2443,"endTime":5355,"channelId":0},{"speakerRole":"agent","index":2,"text":"嗯，","beginTime":5355,"endTime":5620,"channelId":0},{"speakerRole":"agent","index":3,"text":"你好，","beginTime":6240,"endTime":6637,"channelId":0},{"speakerRole":"agent","index":4,"text":"我这边是支付宝新选车贷客服经理，","beginTime":6637,"endTime":9620,"channelId":0},{"speakerRole":"agent","index":5,"text":"有收到您新电商务平台提交给车主贷，","beginTime":9620,"endTime":12802,"channelId":0},{"speakerRole":"agent","index":6,"text":"对吧？","beginTime":12802,"endTime":13200,"channelId":0},{"speakerRole":"agent","index":7,"text":"你那个密码太高了，","beginTime":13780,"endTime":15860,"channelId":0},{"speakerRole":"agent","index":8,"text":"就不需要了。","beginTime":15860,"endTime":17160,"channelId":0},{"speakerRole":"agent","index":9,"text":"这个利息主要是根据您周转十天来算的。","beginTime":18160,"endTime":21436,"channelId":0},{"speakerRole":"agent","index":10,"text":"您这边大概这个资金需要周转多久呢？","beginTime":21436,"endTime":24520,"channelId":0},{"speakerRole":"agent","index":11,"text":"我像那种就像随随随机循环，","beginTime":26520,"endTime":30788,"channelId":0},{"speakerRole":"agent","index":12,"text":"然后就是有时候时间长一点，","beginTime":30788,"endTime":34500,"channelId":0},{"speakerRole":"agent","index":13,"text":"有时候时间短一点，","beginTime":34500,"endTime":35720,"channelId":0},{"speakerRole":"agent","index":14,"text":"我们这个资金可以支持随时提前结清的啊，","beginTime":36080,"endTime":39596,"channelId":0},{"speakerRole":"agent","index":15,"text":"提前结清。","beginTime":39596,"endTime":40377,"channelId":0},{"speakerRole":"agent","index":16,"text":"他是还剩余的本金，","beginTim