(205522,'rec_27ad64ebd45f4220b808d74e','ext_58c1f8b0bc744ec0840cfdf00775dd51','c2a484e2-c8fb-4d6c-9a00-92149d4d0d98.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/983ffa9e436b47a0a71bcfb65232087e.mp3',2,102,'mp3',103176,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎，","beginTime":500,"endTime":913,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好你好你好，","beginTime":913,"endTime":2973,"channelId":0},{"speakerRole":"agent","index":2,"text":"吴哥。","beginTime":2973,"endTime":3310,"channelId":0},{"speakerRole":"agent","index":3,"text":"哎，","beginTime":3310,"endTime":3479,"channelId":0},{"speakerRole":"agent","index":4,"text":"我这边是支付宝提醒车贷的客户经理，","beginTime":3479,"endTime":6174,"channelId":0},{"speakerRole":"agent","index":5,"text":"就看到您在早上的时候提交了这个车主贷的申请哈。","beginTime":6174,"endTime":9880,"channelId":0},{"speakerRole":"agent","index":6,"text":"哦我看了一下大概有多少额度，","beginTime":10220,"endTime":12360,"channelId":0},{"speakerRole":"agent","index":7,"text":"这边给到您的额度是二十万哦。","beginTime":13440,"endTime":16460,"channelId":0},{"speakerRole":"agent","index":8,"text":"哎您的车牌号是鲁c d c五九九三是吧？","beginTime":16720,"endTime":20931,"channelId":0},{"speakerRole":"agent","index":9,"text":"啊，","beginTime":20931,"endTime":21179,"channelId":0},{"speakerRole":"agent","index":10,"text":"对啊，","beginTime":21179,"endTime":21674,"channelId":0},{"speakerRole":"agent","index":11,"text":"这个车辆是你们名下了吗？","beginTime":21674,"endTime":24400,"channelId":0},{"speakerRole":"agent","index":12,"text":"啊，","beginTime":24780,"endTime":25021,"channelId":0},{"speakerRole":"agent","index":13,"text":"是我的啊，","beginTime":25021,"endTime":25987,"channelId":0},{"speakerRole":"agent","index":14,"text":"是纯电家居的吗？","beginTime":25987,"endTime":27678,"channelId":0},{"speakerRole":"agent","index":15,"text":"哥都好。","beginTime":27678,"endTime":28564,"channelId":0},{"speakerRole":"agent","index":16,"text":"哎，","beginTime":28564,"endTime":28766,"channelId":0},{"speakerRole":"agent","index":17,"text":"那您就是符合我们办理条件的，","beginTime":28766,"endTime":31396,"channelId":0},{"speakerRole":"agent","index":18,"text":"就您需要资金的时候，","beginTime":31396,"endTime":33216,"channelId":0},{"speakerRole":"agent","index":19,"text":"您随时就是来办理就可以了。","beginTime":33216,"endTime":35643,"channelId":0},{"speakerRole":"agent","index":20,"text":"然后您的那个利息太高了，","beginTime":35643,"endTime":37868,"channelId":0},{"speakerRole":"agent","index":21,"text":"在你们那个那个什么那个人的还款，","beginTime":37868,"endTime":40753,"channelId":0},{"speakerRole":"agent","index":22,"text":"其他还款还有手续费，","beginTime":40753,"endTime":42223,"channelId":0},{"speakerRole":"agent","index":23,"text":"所以我就没。","beginTime":42223,"endTime":43040,"channelId":0},{"speakerRole":"agent","index":24,"text":"哥，","beginTime":43720,"endTime":43891,"channelId":0},{"speakerRole":"agent","index":25,"text":"我们是办理是没有手续费的，","beginTime":43891,"endTime":45945,"channelId":0},{"speakerRole":"agent","index":26,"text":"我们提前结束一个违约金，","beginTime":45945,"endTime":47827,"channelId":0},{"speakerRole":"agent","index":27,"text":"一年六十一次的话呃，","beginTime":47827,"endTime":49368,"channelId":0},{"speakerRole":"agent","index":28,"text":"他会说明剩余本金的百分之四。","beginTime":49368,"endTime":51593,"channelId":0},{"speakerRole":"agent","index":29,"text":"然后这个利息的话是有违约金嘛呃，","beginTime":51593,"endTime":54160,"channelId":0},{"speakerRole":"agent","index":30,"text":"你的利息的话是百分之十八，","beginTime":54160,"endTime":56214,"channelId":0},{"speakerRole":"agent","index":31,"text":"那咱们算的三率就相当于一万块钱每一个一百八十。","beginTime":56214,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":32,"text":"我知道，","beginTime":60800,"endTime":61292,"channelId":0},{"speakerRole":"agent","index":33,"text":"但是我是说您提前还款有这个违约金吗？","beginTime":61292,"endTime":64080,"channelId":0},{"speakerRole":"agent","index":34,"text":"我们会提前还款。","beginTime":64320,"endTime":66420,"channelId":0},{"speakerRole":"agent","index":35,"text":"嗯，","beginTime":66900,"endTime":67110,"channelId":0},{"speakerRole":"agent","index":36,"text":"您这个资金大概用多久嘛？","beginTime":67110,"endTime":69420,"channelId":0},{"speakerRole":"agent","index":37,"text":"什么玩意？","beginTime":70100,"endTime":71360,"channelId":0},{"speakerRole":"agent","index":38,"text":"七个月。","beginTime":71880,"endTime":72408,"channelId":0},{"speakerRole":"agent","index":39,"text":"嗯嗯，","beginTime":72408,"endTime":72761,"channelId":0},{"speakerRole":"agent","index":40,"text":"那您就考虑一下吧，","beginTime":72761,"endTime":74171,"channelId":0},{"speakerRole":"agent","index":41,"text":"因为我们这个就提供还款，","beginTime":74171,"endTime":76110,"channelId":0},{"speakerRole":"agent","index":42,"text":"应该都有违约金的。","beginTime":76110,"endTime":77521,"channelId":0},{"speakerRole":"agent","index":43,"text":"我们百分之四十的还是比比较低的，","beginTime":77521,"endTime":80165,"channelId":0},{"speakerRole":"agent","index":44,"text":"大可以去对比一下，","beginTime":80165,"endTime":81575,"channelId":0},{"speakerRole":"agent","index":45,"text":"其他的品牌，","beginTime":81575,"endTime":82457,"channelId":0},{"speakerRole":"agent","index":46,"text":"都是百分之六到八的。","beginTime":82457,"endTime":84043,"channelId":0},{"speakerRole":"agent","index":47,"text":"嗯，","beginTime":84043,"endTime":84220,"channelId":0},{"speakerRole":"agent","index":48,"text":"哎，","beginTime":84720,"endTime":84913,"channelId":0},{"speakerRole":"agent","index":49,"text":"我这边方便加您一个微信啊。","beginTime":84913,"endTime":87237,"channelId":0},{"speakerRole":"agent","index":50,"text":"五哥，","beginTime":87237,"endTime":87624,"channelId":0},{"speakerRole":"agent","index":51,"text":"就您如果需要您直接联系嘛，","beginTime":87624,"endTime":89948,"channelId":0},{"speakerRole":"agent","index":52,"text":"反正我这边也不打扰您了。","beginTime":89948,"endTime":92079,"channelId":0},{"speakerRole":"agent","index":53,"text":"好好好，","beginTime":92079,"endTime":92660,"channelId":0},{"speakerRole":"agent","index":54,"text":"您是叫甘雪哈。","beginTime":94360,"endTime":95841,"channelId":0},{"speakerRole":"agent","index":55,"text":"对，","beginTime":95841,"endTime":96088,"channelId":0},{"speakerRole":"agent","index":56,"text":"嗯，","beginTime":96088,"endTime":96335,"channelId":0},{"speakerRole":"agent","index":57,"text":"你这个名字好，","beginTime":96335,"endTime":97816,"channelId":0},{"speakerRole":"agent","index":58,"text":"零一七。","beginTime":97816,"endTime":98556,"channelId":0},{"speakerRole":"agent","index":59,"text":"好好，","beginTime":98556,"endTime":99050,"channelId":0},{"speakerRole":"agent","index":60,"text":"我这边添加您了哈，","beginTime":99050,"endTime":101025,"channelId":0},{"speakerRole":"agent","index":61,"text":"再见。","beginTime":101025,"endTime":101519,"channelId":0},{"speakerRole":"agent","index":62,"text":"好好嗯。","beginTime":101519,"endTime":102260,"channelId":0}]}',80,NULL,NULL,0,0,2,'2026-05-22 01:10:57','2026-05-22 01:11:00','2026-05-22 01:10:52','2026-05-22 01:11:00','system','system','BATCH-20260522-030772',NULL),
(205523,'rec_87ef50cda3d147808e9e9434','ext_d98aa72d0689490a92914a6f99af1fc1','c850bd32-ce86-492f-9d4a-113f6e83d369.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/a23ba537deb8467bbbf8fe987137390b.mp3',2,81,'mp3',83160,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎，","beginTime":1000,"endTime":1196,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":1196,"endTime":1588,"channelId":0},{"speakerRole":"agent","index":2,"text":"哎，","beginTime":1588,"endTime":1784,"channelId":0},{"speakerRole":"agent","index":3,"text":"请问是手机尾号五零七八的李先生是吧？","beginTime":1784,"endTime":5120,"channelId":0},{"speakerRole":"agent","index":4,"text":"嗯，","beginTime":5600,"endTime":5783,"channelId":0},{"speakerRole":"agent","index":5,"text":"哎你好，","beginTime":5783,"endTime":6334,"channelId":0},{"speakerRole":"agent","index":6,"text":"李先生。","beginTime":6334,"endTime":6884,"channelId":0},{"speakerRole":"agent","index":7,"text":"就是您在支付宝上申请的这个车贷资金啊，","beginTime":6884,"endTime":10188,"channelId":0},{"speakerRole":"agent","index":8,"text":"您那边还需要使用吗？","beginTime":10188,"endTime":11840,"channelId":0},{"speakerRole":"agent","index":9,"text":"初始额度是给您估的是呃八万四千二百元的高度的吗？","beginTime":12080,"endTime":18010,"channelId":0},{"speakerRole":"agent","index":10,"text":"车产太少了没哦，","beginTime":18010,"endTime":20891,"channelId":0},{"speakerRole":"agent","index":11,"text":"你觉得资金有点少是吧？","beginTime":20891,"endTime":22608,"channelId":0},{"speakerRole":"agent","index":12,"text":"您您大概就是说要用到多少吗？","beginTime":22608,"endTime":24840,"channelId":0},{"speakerRole":"agent","index":13,"text":"十多万呢，","beginTime":25820,"endTime":26820,"channelId":0},{"speakerRole":"agent","index":14,"text":"你们家还有没有其他的车辆吗？","beginTime":27060,"endTime":29460,"channelId":0},{"speakerRole":"agent","index":15,"text":"有啊，","beginTime":30480,"endTime":31440,"channelId":0},{"speakerRole":"agent","index":16,"text":"也也有其他的车辆是吧，","beginTime":31920,"endTime":33701,"channelId":0},{"speakerRole":"agent","index":17,"text":"那您可以用其他的车辆这个进行一个就是说上传嘛。","beginTime":33701,"endTime":37620,"channelId":0},{"speakerRole":"agent","index":18,"text":"嗯啊你其他车辆是全款车吗？","beginTime":38620,"endTime":42340,"channelId":0},{"speakerRole":"agent","index":19,"text":"按揭是哦，","beginTime":43400,"endTime":44967,"channelId":0},{"speakerRole":"agent","index":20,"text":"全车是二级车啊，","beginTime":44967,"endTime":46276,"channelId":0},{"speakerRole":"agent","index":21,"text":"就只有这个车是全款。","beginTime":46276,"endTime":47960,"channelId":0},{"speakerRole":"agent","index":22,"text":"嗯，","beginTime":48680,"endTime":48850,"channelId":0},{"speakerRole":"agent","index":23,"text":"嗯，","beginTime":48850,"endTime":49021,"channelId":0},{"speakerRole":"agent","index":24,"text":"那我建议您这边就是说如果说额度有这么多，","beginTime":49021,"endTime":52270,"channelId":0},{"speakerRole":"agent","index":25,"text":"还是可以先用着嘛。","beginTime":52270,"endTime":53637,"channelId":0},{"speakerRole":"agent","index":26,"text":"你要能缓解一部分投资压力吗？","beginTime":53637,"endTime":55860,"channelId":0},{"speakerRole":"agent","index":27,"text":"嗯，","beginTime":56760,"endTime":56949,"channelId":0},{"speakerRole":"agent","index":28,"text":"就是说您嗯因为另外一个车是按揭车啊，","beginTime":56949,"endTime":60176,"channelId":0},{"speakerRole":"agent","index":29,"text":"您这个车的三万多的额度的话，","beginTime":60176,"endTime":62644,"channelId":0},{"speakerRole":"agent","index":30,"text":"您可以先使用。","beginTime":62644,"endTime":63783,"channelId":0},{"speakerRole":"agent","index":31,"text":"这样这样也可以就是缓解一部分你的经济压力的嘛。","beginTime":63783,"endTime":67960,"channelId":0},{"speakerRole":"agent","index":32,"text":"没经济压力啊，","beginTime":68200,"endTime":69720,"channelId":0},{"speakerRole":"agent","index":33,"text":"我要我他爸给他进去哦，","beginTime":69720,"endTime":72803,"channelId":0},{"speakerRole":"agent","index":34,"text":"就是说还是比较大额的哈。","beginTime":72803,"endTime":75480,"channelId":0},{"speakerRole":"agent","index":35,"text":"嗯嗯，","beginTime":75940,"endTime":76388,"channelId":0},{"speakerRole":"agent","index":36,"text":"那确实那没有办法了，","beginTime":76388,"endTime":78407,"channelId":0},{"speakerRole":"agent","index":37,"text":"这边就打扰您了嘛哈好，","beginTime":78407,"endTime":80651,"channelId":0},{"speakerRole":"agent","index":38,"text":"拜拜。","beginTime":80651,"endTime":81100,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:10:57','2026-05-22 01:10:59','2026-05-22 01:10:53','2026-05-22 01:10:59','system','system','BATCH-20260522-030772',NULL),
