(205525,'rec_edb253aecdee4e6e9c6b3043','ext_c49555be468948a0a1081b28a94119ba','d40f7c60-7cd7-4435-9882-2c4d32e5bf9b.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/7d695986ee4c4dc8a36996914ddb0db1.mp3',2,1299,'mp3',1313496,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂喂，","beginTime":0,"endTime":2666,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好你好，","beginTime":2666,"endTime":4300,"channelId":0},{"speakerRole":"agent","index":2,"text":"嗯，","beginTime":4540,"endTime":4752,"channelId":0},{"speakerRole":"agent","index":3,"text":"请问是手机尾号零六九三的吴女士吗？","beginTime":4752,"endTime":8160,"channelId":0},{"speakerRole":"agent","index":4,"text":"嗯，","beginTime":8800,"endTime":9700,"channelId":0},{"speakerRole":"agent","index":5,"text":"哎，","beginTime":9940,"endTime":10094,"channelId":0},{"speakerRole":"agent","index":6,"text":"打扰您了。","beginTime":10094,"endTime":10711,"channelId":0},{"speakerRole":"agent","index":7,"text":"吴女士，","beginTime":10711,"endTime":11174,"channelId":0},{"speakerRole":"agent","index":8,"text":"我这边是那个小米商机的工作人员，","beginTime":11174,"endTime":13488,"channelId":0},{"speakerRole":"agent","index":9,"text":"就是您在支付宝上面刚才申请的那个新选车贷这边疫情通过了，","beginTime":13488,"endTime":17654,"channelId":0},{"speakerRole":"agent","index":10,"text":"您有注意到吗？","beginTime":17654,"endTime":18580,"channelId":0},{"speakerRole":"agent","index":11,"text":"呃呃，","beginTime":20080,"endTime":20640,"channelId":0},{"speakerRole":"agent","index":12,"text":"什么，","beginTime":20640,"endTime":21200,"channelId":0},{"speakerRole":"agent","index":13,"text":"哎，","beginTime":21640,"endTime":21861,"channelId":0},{"speakerRole":"agent","index":14,"text":"我就说您这边在支付宝上面申请的蚂蚁星选车贷这边预审通过了。","beginTime":21861,"endTime":28053,"channelId":0},{"speakerRole":"agent","index":15,"text":"您有注意到吗？","beginTime":28053,"endTime":29380,"channelId":0},{"speakerRole":"agent","index":16,"text":"我我没看到。","beginTime":29780,"endTime":32442,"channelId":0},{"speakerRole":"agent","index":17,"text":"哎嗯哦。","beginTime":32442,"endTime":34040,"channelId":0},{"speakerRole":"agent","index":18,"text":"呃，","beginTime":36180,"endTime":36362,"channelId":0},{"speakerRole":"agent","index":19,"text":"这边呢，","beginTime":36362,"endTime":36909,"channelId":0},{"speakerRole":"agent","index":20,"text":"我到时候给您说一下吧，","beginTime":36909,"endTime":38732,"channelId":0},{"speakerRole":"agent","index":21,"text":"就是您本次的这个放款流程的话，","beginTime":38732,"endTime":41285,"channelId":0},{"speakerRole":"agent","index":22,"text":"我这边的话协助您进行办理。","beginTime":41285,"endTime":43474,"channelId":0},{"speakerRole":"agent","index":23,"text":"呃，","beginTime":43474,"endTime":43656,"channelId":0},{"speakerRole":"agent","index":24,"text":"预审额度的话是五万九千九，","beginTime":43656,"endTime":45844,"channelId":0},{"speakerRole":"agent","index":25,"text":"呃，","beginTime":45844,"endTime":46027,"channelId":0},{"speakerRole":"agent","index":26,"text":"能满足您这边的一个资金需求。","beginTime":46027,"endTime":48397,"channelId":0},{"speakerRole":"agent","index":27,"text":"不，","beginTime":48397,"endTime":48580,"channelId":0},{"speakerRole":"agent","index":28,"text":"我要不了那么多，","beginTime":48860,"endTime":50780,"channelId":0},{"speakerRole":"agent","index":29,"text":"我是指定要的。","beginTime":50780,"endTime":52425,"channelId":0},{"speakerRole":"agent","index":30,"text":"呃，","beginTime":52425,"endTime":52700,"channelId":0},{"speakerRole":"agent","index":31,"text":"您大概要多少呢？","beginTime":52700,"endTime":54620,"channelId":0},{"speakerRole":"agent","index":32,"text":"一两万两两万是一两万是吧？","beginTime":55480,"endTime":59690,"channelId":0},{"speakerRole":"agent","index":33,"text":"嗯，","beginTime":59690,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":34,"text":"呃那您大概什么时候用的？","beginTime":60120,"endTime":62160,"channelId":0},{"speakerRole":"agent","index":35,"text":"嗯，","beginTime":62480,"endTime":62679,"channelId":0},{"speakerRole":"agent","index":36,"text":"就现在等着用了，","beginTime":62679,"endTime":64074,"channelId":0},{"speakerRole":"agent","index":37,"text":"现在等着用了，","beginTime":64074,"endTime":65270,"channelId":0},{"speakerRole":"agent","index":38,"text":"那车辆的绿本和那行驶证在手上没有停车证，","beginTime":65270,"endTime":70853,"channelId":0},{"speakerRole":"agent","index":39,"text":"没没在没在这边，","beginTime":70853,"endTime":72613,"channelId":0},{"speakerRole":"agent","index":40,"text":"绿本跟行驶证都没有吗？","beginTime":72613,"endTime":75126,"channelId":0},{"speakerRole":"agent","index":41,"text":"日本有行驶证的话，","beginTime":75126,"endTime":77404,"channelId":0},{"speakerRole":"agent","index":42,"text":"那个交管幺二幺二三上面，","beginTime":77404,"endTime":79702,"channelId":0},{"speakerRole":"agent","index":43,"text":"你这边有没有电子版的？","beginTime":79702,"endTime":81791,"channelId":0},{"speakerRole":"agent","index":44,"text":"有，","beginTime":81791,"endTime":82000,"channelId":0},{"speakerRole":"agent","index":45,"text":"那你现在的话，","beginTime":82340,"endTime":83458,"channelId":0},{"speakerRole":"agent","index":46,"text":"先下载一下电子版的，","beginTime":83458,"endTime":85136,"channelId":0},{"speakerRole":"agent","index":47,"text":"这个先上传一下吧。","beginTime":85136,"endTime":86627,"channelId":0},{"speakerRole":"agent","index":48,"text":"好吧。","beginTime":86627,"endTime":87000,"channelId":0},{"speakerRole":"agent","index":49,"text":"哦，","beginTime":87620,"endTime":87912,"channelId":0},{"speakerRole":"agent","index":50,"text":"呃电子版的有啊，","beginTime":87912,"endTime":89960,"channelId":0},{"speakerRole":"agent","index":51,"text":"电子版的，","beginTime":90200,"endTime":90905,"channelId":0},{"speakerRole":"agent","index":52,"text":"你就你是这样子吧，","beginTime":90905,"endTime":92317,"channelId":0},{"speakerRole":"agent","index":53,"text":"我刚才用企业微信添加您，","beginTime":92317,"endTime":94257,"channelId":0},{"speakerRole":"agent","index":54,"text":"您看一下呀，","beginTime":94257,"endTime":95140,"channelId":0},{"speakerRole":"agent","index":55,"text":"我发给你看看吗？","beginTime":96180,"endTime":97450,"channelId":0},{"speakerRole":"agent","index":56,"text":"呃，","beginTime":97450,"endTime":97632,"channelId":0},{"speakerRole":"agent","index":57,"text":"不用发给我。","beginTime":97632,"endTime":98539,"channelId":0},{"speakerRole":"agent","index":58,"text":"您这边的话，","beginTime":98539,"endTime":99447,"channelId":0},{"speakerRole":"agent","index":59,"text":"我给您说具体怎么上传，","beginTime":99447,"endTime":101262,"channelId":0},{"speakerRole":"agent","index":60,"text":"怎么个流程，","beginTime":101262,"endTime":102170,"channelId":0},{"speakerRole":"agent","index":61,"text":"知道吧？","beginTime":102170,"endTime":102714,"channelId":0},{"speakerRole":"agent","index":62,"text":"因为您着急的话，","beginTime":102714,"endTime":103985,"channelId":0},{"speakerRole":"agent","index":63,"text":"这边的话就晚上给您去去做那个终审，","beginTime":103985,"endTime":106889,"channelId":0},{"speakerRole":"agent","index":64,"text":"终审通过了，","beginTime":106889,"endTime":107797,"channelId":0},{"speakerRole":"agent","index":65,"text":"这边马上就可以申请放款。","beginTime":107797,"endTime":109793,"channelId":0},{"speakerRole":"agent","index":66,"text":"是这意思，","beginTime":109793,"endTime":110520,"channelId":0},{"speakerRole":"agent","index":67,"text":"他这个一万块一个月大概多少钱？","beginTime":111540,"endTime":114620,"channelId":0},{"speakerRole":"agent","index":68,"text":"嗯，","beginTime":115040,"endTime":115232,"channelId":0},{"speakerRole":"agent","index":69,"text":"这个线目前我看不到，","beginTime":115232,"endTime":116961,"channelId":0},{"speakerRole":"agent","index":70,"text":"因为就是说是咱们这边有高有低每个人的资质情况不一样。","beginTime":116961,"endTime":121766,"channelId":0},{"speakerRole":"agent","index":71,"text":"最低的话这边的话我看是百分之八都有。","beginTime":121766,"endTime":125033,"channelId":0},{"speakerRole":"agent","index":72,"text":"然后呢，","beginTime":125033,"endTime":125609,"channelId":0},{"speakerRole":"agent","index":73,"text":"最高的话是不超过二十三点九克就不一样。","beginTime":125609,"endTime":129760,"channelId":0},{"speakerRole":"agent","index":74,"text":"您资金大概用多久吗？","beginTime":130000,"endTime":131847,"channelId":0},{"speakerRole":"agent","index":75,"text":"三年的我们是三年的啊，","beginTime":131847,"endTime":133900,"channelId":0},{"speakerRole":"agent","index":76,"text":"然后用多久嘛？","beginTime":135660,"endTime":138180,"channelId":0},{"speakerRole":"agent","index":77,"text":"大概。","beginTime":138180,"endTime":138620,"channelId":0},{"speakerRole":"agent","index":78,"text":"一年嘛就一年，","beginTime":141060,"endTime":142135,"channelId":0},{"speakerRole":"agent","index":79,"text":"因为一年的话，","beginTime":142135,"endTime":143210,"channelId":0},{"speakerRole":"agent","index":80,"text":"那影响也不大。","beginTime":143210,"endTime":144286,"channelId":0},{"speakerRole":"agent","index":81,"text":"因为一年的话，","beginTime":144286,"endTime":145361,"channelId":0},{"speakerRole":"agent","index":82,"text":"到时候提前还款就可以了。","beginTime":145361,"endTime":147333,"channelId":0},{"speakerRole":"agent","index":83,"text":"咱们也可以说来了，","beginTime":147333,"endTime":148767,"channelId":0},{"speakerRole":"agent","index":84,"text":"也是可以随借随还的嘛。","beginTime":148767,"endTime":150560,"channelId":0},{"speakerRole":"agent","index":85,"text":"一年的话一年以后的话，","beginTime":151100,"endTime":152631,"channelId":0},{"speakerRole":"agent","index":86,"text":"这边的话我给您到时候申请一下，","beginTime":152631,"endTime":154775,"channelId":0},{"speakerRole":"agent","index":87,"text":"把这个违约金给您也免掉，","beginTime":154775,"endTime":156460,"channelId":0},{"speakerRole":"agent","index":88,"text":"也没有说不会承担多多余的费用嘛。","beginTime":156920,"endTime":160840,"channelId":0},{"speakerRole":"agent","index":89,"text":"嗯嗯，","beginTime":161940,"endTime":162430,"channelId":0},{"speakerRole":"agent","index":90,"text":"你你现在就要是吧，","beginTime":162430,"endTime":164390,"channelId":0},{"speakerRole":"agent","index":91,"text":"就上午是不是嗯能弄死了嘛，","beginTime":164390,"endTime":171950,"channelId":0},{"speakerRole":"agent","index":92,"text":"就就呃对你如果说资料资料齐全的话，","beginTime":171950,"endTime":177056,"channelId":0},{"speakerRole":"agent","index":93,"text":"那今天上午应该问题不大。","beginTime":177056,"endTime":178948,"channelId":0},{"speakerRole":"agent","index":94,"text":"那您这样子吧，","beginTime":178948,"endTime":179980,"channelId":0},{"speakerRole":"agent","index":95,"text":"您先通过通过一下我微信，","beginTime":180100,"endTime":182188,"channelId":0},{"speakerRole":"agent","index":96,"text":"我稍后我给您说那个具体的申请流程怎么来走，","beginTime":182188,"endTime":185984,"channelId":0},{"speakerRole":"agent","index":97,"text":"您看行吗？","beginTime":185984,"endTime":186744,"channelId":0},{"speakerRole":"agent","index":98,"text":"因为如果说您这边的话要改金额，","beginTime":186744,"endTime":189401,"channelId":0},{"speakerRole":"agent","index":99,"text":"您是确定最最多要两万是吧？","beginTime":189401,"endTime":191680,"channelId":0},{"speakerRole":"agent","index":100,"text":"他意思说你申请了，","beginTime":192800,"endTime":194731,"channelId":0},{"speakerRole":"agent","index":101,"text":"然后就是说呃申请在那里不用，","beginTime":194731,"endTime":197870,"channelId":0},{"speakerRole":"agent","index":102,"text":"你是不要钱的吗？","beginTime":197870,"endTime":199560,"channelId":0},{"speakerRole":"agent","index":103,"text":"那肯定的呀。","beginTime":199940,"endTime":201280,"channelId":0},{"speakerRole":"agent","index":104,"text":"但是我们这个就是说是要固定一个额度，","beginTime":201960,"endTime":205277,"channelId":0},{"speakerRole":"agent","index":105,"text":"比如说哈这边的话给您现在的话是五万九千九。","beginTime":205277,"endTime":209180,"channelId":0},{"speakerRole":"agent","index":106,"text":"您如果说确定要两万，","beginTime":210080,"endTime":211749,"channelId":0},{"speakerRole":"agent","index":107,"text":"那我们后面这块可以把这个金额直接给您改成两万。","beginTime":211749,"endTime":215831,"channelId":0},{"speakerRole":"agent","index":108,"text":"那您就最多只能提两万，","beginTime":215831,"endTime":217686,"channelId":0},{"speakerRole":"agent","index":109,"text":"走，","beginTime":217686,"endTime":217872,"channelId":0},{"speakerRole":"agent","index":110,"text":"明白意思吗？","beginTime":217872,"endTime":218800,"channelId":0},{"speakerRole":"agent","index":111,"text":"嗯，","beginTime":220020,"endTime":220218,"channelId":0},{"speakerRole":"agent","index":112,"text":"因为咱这是车底贷，","beginTime":220218,"endTime":221804,"channelId":0},{"speakerRole":"agent","index":113,"text":"然后不是那个什么呃网贷啊，",