ginTime":78405,"endTime":79763,"channelId":0},{"speakerRole":"agent","index":37,"text":"没有搜索到，","beginTime":79763,"endTime":80894,"channelId":0},{"speakerRole":"agent","index":38,"text":"您看方便添加我的体味吗？","beginTime":80894,"endTime":83382,"channelId":0},{"speakerRole":"agent","index":39,"text":"我给您报一下，","beginTime":83382,"endTime":84740,"channelId":0},{"speakerRole":"agent","index":40,"text":"等一下，","beginTime":85940,"endTime":86424,"channelId":0},{"speakerRole":"agent","index":41,"text":"我今天没空，","beginTime":86424,"endTime":87231,"channelId":0},{"speakerRole":"agent","index":42,"text":"能晚一点吧。","beginTime":87231,"endTime":88038,"channelId":0},{"speakerRole":"agent","index":43,"text":"啊，","beginTime":88038,"endTime":88200,"channelId":0},{"speakerRole":"agent","index":44,"text":"嗯可以的，","beginTime":88440,"endTime":89204,"channelId":0},{"speakerRole":"agent","index":45,"text":"就是咱们添加一下体温，","beginTime":89204,"endTime":91115,"channelId":0},{"speakerRole":"agent","index":46,"text":"您有空的时候可以随时联系我，","beginTime":91115,"endTime":93600,"channelId":0},{"speakerRole":"agent","index":47,"text":"可以吗？","beginTime":94980,"endTime":95900,"channelId":0},{"speakerRole":"agent","index":48,"text":"你晚点给他打电话给我。","beginTime":97080,"endTime":98740,"channelId":0},{"speakerRole":"agent","index":49,"text":"呃，","beginTime":99000,"endTime":99243,"channelId":0},{"speakerRole":"agent","index":50,"text":"哦那您大概什么时候方便呀？","beginTime":99243,"endTime":102160,"channelId":0},{"speakerRole":"agent","index":51,"text":"下午吧下午吧啊下午呃大概几点，","beginTime":102780,"endTime":107000,"channelId":0},{"speakerRole":"agent","index":52,"text":"下午三四点吧。","beginTime":108320,"endTime":109920,"channelId":0},{"speakerRole":"agent","index":53,"text":"行好嘞，","beginTime":110820,"endTime":111735,"channelId":0},{"speakerRole":"agent","index":54,"text":"行，","beginTime":111735,"endTime":112040,"channelId":0},{"speakerRole":"agent","index":55,"text":"那您先忙啊，","beginTime":112040,"endTime":113565,"channelId":0},{"speakerRole":"agent","index":56,"text":"嗯嗯，","beginTime":113565,"endTime":114175,"channelId":0},{"speakerRole":"agent","index":57,"text":"祝您生活愉快，","beginTime":114175,"endTime":116005,"channelId":0},{"speakerRole":"agent","index":58,"text":"再见啊。","beginTime":116005,"endTime":116920,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:11:02','2026-05-22 01:11:04','2026-05-22 01:10:58','2026-05-22 01:11:04','system','system','BATCH-20260522-030772',NULL),
