(205540,'rec_c39e3006d93e4a62813ba74f','ext_9a0bd07da3af42dc98c192b937214c6e','345d6d36-f46e-4b9f-9e5f-631116790be6.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/934595f4bf1d4ebbae1876816a0e00d6.mp3',2,57,'mp3',60768,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":920,"endTime":1157,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好嗯哎你好，","beginTime":1157,"endTime":2581,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问是手机尾号幺七幺三的张先生吗？","beginTime":2581,"endTime":6380,"channelId":0},{"speakerRole":"agent","index":3,"text":"嗯，","beginTime":6620,"endTime":7600,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎你好，","beginTime":7840,"endTime":8314,"channelId":0},{"speakerRole":"agent","index":5,"text":"哥，","beginTime":8314,"endTime":8472,"channelId":0},{"speakerRole":"agent","index":6,"text":"我这边是支付宝心选车贷的客户经理啊。","beginTime":8472,"endTime":11160,"channelId":0},{"speakerRole":"agent","index":7,"text":"哥，","beginTime":11160,"endTime":11318,"channelId":0},{"speakerRole":"agent","index":8,"text":"我看到你今天早晨提交的资料了，","beginTime":11318,"endTime":13532,"channelId":0},{"speakerRole":"agent","index":9,"text":"然后咱这边预审已经通过了，","beginTime":13532,"endTime":15430,"channelId":0},{"speakerRole":"agent","index":10,"text":"我这边可以协助您放款，","beginTime":15430,"endTime":17011,"channelId":0},{"speakerRole":"agent","index":11,"text":"您看方便吗？","beginTime":17011,"endTime":17801,"channelId":0},{"speakerRole":"agent","index":12,"text":"哥，","beginTime":17801,"endTime":17960,"channelId":0},{"speakerRole":"agent","index":13,"text":"我要我给他看一下哦，","beginTime":18640,"endTime":21614,"channelId":0},{"speakerRole":"agent","index":14,"text":"您只是想了解一下。","beginTime":21614,"endTime":22849,"channelId":0},{"speakerRole":"agent","index":15,"text":"可以的，","beginTime":22849,"endTime":23312,"channelId":0},{"speakerRole":"agent","index":16,"text":"我跟你说一下，","beginTime":23312,"endTime":24238,"channelId":0},{"speakerRole":"agent","index":17,"text":"咱们这个全程线上办理，","beginTime":24238,"endTime":25782,"channelId":0},{"speakerRole":"agent","index":18,"text":"最快的话，","beginTime":25782,"endTime":26399,"channelId":0},{"speakerRole":"agent","index":19,"text":"一个小时就可以下款。","beginTime":26399,"endTime":27789,"channelId":0},{"speakerRole":"agent","index":20,"text":"然后没有其他的额外的费用，","beginTime":27789,"endTime":29641,"channelId":0},{"speakerRole":"agent","index":21,"text":"然后到账的价呃，","beginTime":29641,"endTime":30721,"channelId":0},{"speakerRole":"agent","index":22,"text":"额度多少，","beginTime":30721,"endTime":31339,"channelId":0},{"speakerRole":"agent","index":23,"text":"到账就是多少个，","beginTime":31339,"endTime":32420,"channelId":0},{"speakerRole":"agent","index":24,"text":"我没用出来啊，","beginTime":32900,"endTime":35178,"channelId":0},{"speakerRole":"agent","index":25,"text":"现在没有资金需求。","beginTime":35178,"endTime":36450,"channelId":0},{"speakerRole":"agent","index":26,"text":"没事，","beginTime":36450,"endTime":36767,"channelId":0},{"speakerRole":"agent","index":27,"text":"哥，","beginTime":36767,"endTime":36926,"channelId":0},{"speakerRole":"agent","index":28,"text":"那咱加个微信可以吗？","beginTime":36926,"endTime":38356,"channelId":0},{"speakerRole":"agent","index":29,"text":"到时候有需要的话，","beginTime":38356,"endTime":39627,"channelId":0},{"speakerRole":"agent","index":30,"text":"咱可以随时联系好好的哥，","beginTime":39627,"endTime":43474,"channelId":0},{"speakerRole":"agent","index":31,"text":"我用企业微信加一下您。","beginTime":43474,"endTime":45321,"channelId":0},{"speakerRole":"agent","index":32,"text":"然后您的微信首页会收到一个服务通知，","beginTime":45321,"endTime":48461,"channelId":0},{"speakerRole":"agent","index":33,"text":"然后麻烦您就是嗯长安c d i v码就加上我了。","beginTime":48461,"endTime":52155,"channelId":0},{"speakerRole":"agent","index":34,"text":"哥嗯嗯，","beginTime":52155,"endTime":53103,"channelId":0},{"speakerRole":"agent","index":35,"text":"好嘞，","beginTime":53103,"endTime":53487,"channelId":0},{"speakerRole":"agent","index":36,"text":"哥，","beginTime":53487,"endTime":53679,"channelId":0},{"speakerRole":"agent","index":37,"text":"那不打扰您了，","beginTime":53679,"endTime":54830,"channelId":0},{"speakerRole":"agent","index":38,"text":"麻烦你加一下微信，","beginTime":54830,"endTime":56365,"channelId":0},{"speakerRole":"agent","index":39,"text":"那祝您生活愉快哥。","beginTime":56365,"endTime":57900,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:11:35','2026-05-22 01:11:37','2026-05-22 01:11:32','2026-05-22 01:11:37','system','system','BATCH-20260522-030772',NULL),
(205541,'rec_25659096bca2434e85258a2b','ext_701a7a7eeb554ccaade2a89702b65acd','538d2f14-0404-45d2-bf2b-13d2a1acac26.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/ae67a29c36d641809399b93ba0fec32a.mp3',2,137,'mp3',142272,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"我说你你喂，","beginTime":200,"endTime":2226,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":2226,"endTime":2720,"channelId":0},{"speakerRole":"agent","index":2,"text":"是沈先生是吧，","beginTime":2720,"endTime":4200,"channelId":0},{"speakerRole":"agent","index":3,"text":"嗯，","beginTime":4880,"endTime":5197,"channelId":0},{"speakerRole":"agent","index":4,"text":"不是陈先生，","beginTime":5197,"endTime":6782,"channelId":0},{"speakerRole":"agent","index":5,"text":"是嗯，","beginTime":6782,"endTime":7689,"channelId":0},{"speakerRole":"agent","index":6,"text":"哎你好，","beginTime":7689,"endTime":8199,"channelId":0},{"speakerRole":"agent","index":7,"text":"我这边是那个支付宝的工作人员，","beginTime":8199,"endTime":10578,"channelId":0},{"speakerRole":"agent","index":8,"text":"您在支付宝上面提交的那个月七零五八c v这个车牌呃，","beginTime":10578,"endTime":14657,"channelId":0},{"speakerRole":"agent","index":9,"text":"就目前的话那个绿本的话能拍的照片吗？","beginTime":14657,"endTime":17546,"channelId":0},{"speakerRole":"agent","index":10,"text":"因为前两天不是加个微信，","beginTime":17546,"endTime":19416,"channelId":0},{"speakerRole":"agent","index":11,"text":"您看就不方便嘛。","beginTime":19416,"endTime":20605,"channelId":0},{"speakerRole":"agent","index":12,"text":"呃现在的话您可以先上传一个绿本的照片啊，","beginTime":20605,"endTime":23834,"channelId":0},{"speakerRole":"agent","index":13,"text":"然后的话给你这边的话，","beginTime":23834,"endTime":25533,"channelId":0},{"speakerRole":"agent","index":14,"text":"全新人生人生额度可以给您保留这个额度。","beginTime":25533,"endTime":28592,"channelId":0},{"speakerRole":"agent","index":15,"text":"更新方面，","beginTime":28592,"endTime":29272,"channelId":0},{"speakerRole":"agent","index":16,"text":"如果说有需要都可以来办理，","beginTime":29272,"endTime":31312,"channelId":0},{"speakerRole":"agent","index":17,"text":"但这个额度也是看到快过期了嘛，","beginTime":31312,"endTime":33691,"channelId":0},{"speakerRole":"agent","index":18,"text":"然后再次联系到您了，","beginTime":33691,"endTime":35220,"channelId":0},{"speakerRole":"agent","index":19,"text":"就是这边给您这个支支付宝。","beginTime":35220,"endTime":37260,"channelId":0},{"speakerRole":"agent","index":20,"text":"您现在的话就是说可以上传那个是登记地址，","beginTime":37500,"endTime":40989,"channelId":0},{"speakerRole":"agent","index":21,"text":"告诉他你是拍一张还是拍几张，","beginTime":40989,"endTime":45380,"channelId":0},{"speakerRole":"agent","index":22,"text":"您就那个荔浦的一二页和三十页跳什么就行了。","beginTime":45620,"endTime":48959,"channelId":0},{"speakerRole":"agent","index":23,"text":"他那上面的话有那个呃要求，","beginTime":48959,"endTime":50963,"channelId":0},{"speakerRole":"agent","index":24,"text":"而且我发给你的，","beginTime":50963,"endTime":52132,"channelId":0},{"speakerRole":"agent","index":25,"text":"就按照我发给你的那个模板啊，","beginTime":52132,"endTime":54302,"channelId":0},{"speakerRole":"agent","index":26,"text":"一二列连着拍，","beginTime":54302,"endTime":55304,"channelId":0},{"speakerRole":"agent","index":27,"text":"二四页连着拍就行了。","beginTime":55304,"endTime":56807,"channelId":0},{"speakerRole":"agent","index":28,"text":"然后你把那个行行驶证拍张照片直接传上去就可以了。","beginTime":56807,"endTime":60612,"channelId":0},{"speakerRole":"agent","index":29,"text":"到时的话，","beginTime":60612,"endTime":61224,"channelId":0},{"speakerRole":"agent","index":30,"text":"这边审核通过之后，","beginTime":61224,"endTime":62448,"channelId":0},{"speakerRole":"agent","index":31,"text":"麻烦您到时候额度给你发一个里。","beginTime":62448,"endTime":64590,"channelId":0},{"speakerRole":"agent","index":32,"text":"您到时候刚好有需要就可以帮明白了吗？","beginTime":64590,"endTime":67700,"channelId":0},{"speakerRole":"agent","index":33,"text":"这个又不是说您这边到时候就直接给你打款到账了啊。","beginTime":69320,"endTime":73258,"channelId":0},{"speakerRole":"agent","index":34,"text":"这个因为您目前的话只是提到了那个出彩。","beginTime":73258,"endTime":76500,"channelId":0},{"speakerRole":"agent","index":35,"text":"因为这边的话你要上次行驶怎么地啊？","beginTime":76500,"endTime":79096,"channelId":0},{"speakerRole":"agent","index":36,"text":"因为上次跟你说了嘛，","beginTime":79096,"endTime":80557,"channelId":0},{"speakerRole":"agent","index":37,"text":"那个日本的照片上传东西，","beginTime":80557,"endTime":82342,"channelId":0},{"speakerRole":"agent","index":38,"text":"它主要是验证您这个车辆是否是抛弃的，","beginTime":82342,"endTime":85100,"channelId":0},{"speakerRole":"agent","index":39,"text":"或者是否是事故车。","beginTime":85100,"endTime":86399,"channelId":0},{"speakerRole":"agent","index":40,"text":"所以这样的话，","beginTime":86399,"endTime":87372,"channelId":0},{"speakerRole":"agent","index":41,"text":"到时候就办理不了，","beginTime":87372,"endTime":88670,"channelId":0},{"speakerRole":"agent","index":42,"text":"明白了吗？","beginTime":88670,"endTime":89320,"channelId":0},{"speakerRole":"agent","index":43,"text":"嗯，","beginTime":89780,"endTime":89946,"channelId":0},{"speakerRole":"agent","index":44,"text":"哎对，","beginTime":89946,"endTime":90278,"channelId":0},{"speakerRole":"agent","index":45,"text":"到时候的话，","beginTime":90278,"endTime":91108,"channelId":0},{"speakerRole":"agent","index":46,"text":"您先呃这边拍到那个绿本一二点，","beginTime":91108,"endTime":93433,"channelId":0},{"speakerRole":"agent","index":47,"text":"连着拍啊，","beginTime":93433,"endTime":94098,"channelId":0},{"speakerRole":"agent","index":48,"text":"三四点连着拍。","beginTime":94098,"endTime":95094,"channelId":0},{"speakerRole":"agent","index":49,"text":"到时候您调整大片之后，","beginTime":95094,"endTime":96755,"channelId":0},{"speakerRole":"agent","index":50,"text":"到时候人有过过久的话，","beginTime":96755,"endTime":98416,"channelId":0},{"speakerRole":"agent","index":51,"text":"您这边可以看一下具体的一个方案，","beginTime":98416,"endTime":100907,"channelId":0},{"speakerRole":"agent","index":52,"text":"好吧。","beginTime":100907,"endTime":101240,"channelId":0},{"speakerRole":"agent","index":53,"text":"你今天这边能拍到吗？","beginTime":103780,"endTime":105460,"channelId":0},{"speakerRole":"agent","index":54,"text":"等一下拍啊哦，","beginTime":106740,"endTime":108654,"channelId":0},{"speakerRole":"agent","index":55,"text":"现在可以开吗？","beginTime":108654,"endTime":109940,"channelId":0},{"speakerRole":"agent","index":56,"text":"嗯，","beginTime":110220,"endTime":110399,"channelId":0},{"speakerRole":"agent","index":57,"text":"哦那你看的招程是吧，","beginTime":110399,"endTime":112012,"channelId":0},{"speakerRole":"agent","index":58,"text":"到时候你不懂的就微信互动吧，","beginTime":112012,"endTime":114342,"channelId":0},{"speakerRole":"agent","index":59,"text":"好吧，","beginTime":114342,"endTime":114701,"channelId":0},{"speakerRole":"agent","index":60,"text":"行，","beginTime":114701,"endTime":114880,"channelId":0},{"speakerRole":"agent","index":61,"text":"哥。","beginTime":114880,"endTime":115060,"channelId":0},{"speakerRole":"agent","index":62,"text":"嗯，","beginTime":117760,"endTime":117902,"channelId":0},{"speakerRole":"agent","index":63,"text":"因为我看到目前的话，","beginTime":117902,"endTime":119187,"channelId":0},{"speakerRole":"agent","index":64,"text":"您还是有还完的这个额度哈，","beginTime":119187,"endTime":120899,"channelId":0},{"speakerRole":"agent","index":65,"text":"就是我们是可以提交还款的哈。","beginTime":120899,"endTime":122755,"channelId":0},{"speakerRole":"agent","index":66,"text":"您到时候多久算多久啊，","beginTime":122755,"endTime":124182,"channelId":0},{"speakerRole":"agent","index":67,"text":"随时有钱都可以提交还提交还款。","beginTime":124182,"endTime":126180,"channelId":0},{"speakerRole":"agent","index":68,"text":"你后面的利息他不计算掉，","beginTime":126180,"endTime":127750,"channelId":0},{"speakerRole":"agent","index":69,"text":"就交给你本人就行了，","beginTime":127750,"endTime":129034,"channelId":0},{"speakerRole":"agent","index":70,"text":"好吧。","beginTime":129034,"endTime":129320,"channelId":0},{"speakerRole":"agent","index":71,"text":"嗯嗯，","beginTime":129820,"endTime":130159,"channelId":0},{"speakerRole":"agent","index":72,"text":"好的好的，","beginTime":130159,"endTime":130838,"channelId":0},{"speakerRole":"agent","index":73,"text":"那您等会儿到时候嘛，","beginTime":130838,"endTime":132366,"channelId":0},{"speakerRole":"agent","index":74,"text":"到时候好了，","beginTime":132366,"endTime":133215,"channelId":0},{"speakerRole":"agent","index":75,"text":"到时候你不听懂我一下哈。","beginTime":133215,"endTime":135082,"channelId":0},{"speakerRole":"agent","index":76,"text":"那咱们微信沟通吧，","beginTime":135082,"endTime":136440,"channelId":0},{"speakerRole":"agent","index":77,"text":"好吧，","beginTime":136440,"endTime":136780,"channelId":0},{"speakerRole":"agent","index":78,"text":"先总。","beginTime":136780,"endTime":137120,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:11:37','2026-05-22 01:11:40','2026-05-22 01:11:33','2026-05-22 01:11:40','system','system','BATCH-20260522-030772',NULL),
