Id":0},{"speakerRole":"agent","index":17,"text":"十二期。","beginTime":33115,"endTime":33773,"channelId":0},{"speakerRole":"agent","index":18,"text":"呃，","beginTime":33773,"endTime":33993,"channelId":0},{"speakerRole":"agent","index":19,"text":"那你这边是这样子的啊，","beginTime":33993,"endTime":36186,"channelId":0},{"speakerRole":"agent","index":20,"text":"我们这边办理也是需要有绿本的，","beginTime":36186,"endTime":39256,"channelId":0},{"speakerRole":"agent","index":21,"text":"就是需要你这个结清以后才能办，","beginTime":39256,"endTime":42326,"channelId":0},{"speakerRole":"agent","index":22,"text":"你这边可以提前结清吗？","beginTime":42326,"endTime":44520,"channelId":0},{"speakerRole":"agent","index":23,"text":"啊，","beginTime":45860,"endTime":47540,"channelId":0},{"speakerRole":"agent","index":24,"text":"那我要再看一下。","beginTime":47780,"endTime":49252,"channelId":0},{"speakerRole":"agent","index":25,"text":"嗯，","beginTime":49252,"endTime":49462,"channelId":0},{"speakerRole":"agent","index":26,"text":"好的，","beginTime":49462,"endTime":49883,"channelId":0},{"speakerRole":"agent","index":27,"text":"行，","beginTime":49883,"endTime":50093,"channelId":0},{"speakerRole":"agent","index":28,"text":"好，","beginTime":50093,"endTime":50304,"channelId":0},{"speakerRole":"agent","index":29,"text":"没关系。","beginTime":50304,"endTime":50935,"channelId":0},{"speakerRole":"agent","index":30,"text":"这样吧，","beginTime":50935,"endTime":51566,"channelId":0},{"speakerRole":"agent","index":31,"text":"我企业微信加您后期有呃，","beginTime":51566,"endTime":53880,"channelId":0},{"speakerRole":"agent","index":32,"text":"可以结清。","beginTime":53880,"endTime":54721,"channelId":0},{"speakerRole":"agent","index":33,"text":"需要的话，","beginTime":54721,"endTime":55562,"channelId":0},{"speakerRole":"agent","index":34,"text":"你可以这个企业微信上面联系我的啊，","beginTime":55562,"endTime":58928,"channelId":0},{"speakerRole":"agent","index":35,"text":"我叫张灿灿，","beginTime":58928,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":36,"text":"嗯，","beginTime":60000,"endTime":60259,"channelId":0},{"speakerRole":"agent","index":37,"text":"o k嗯，","beginTime":60259,"endTime":61036,"channelId":0},{"speakerRole":"agent","index":38,"text":"好好好好，","beginTime":61036,"endTime":62072,"channelId":0},{"speakerRole":"agent","index":39,"text":"那就先不打扰你了啊，","beginTime":62072,"endTime":64403,"channelId":0},{"speakerRole":"agent","index":40,"text":"好，","beginTime":64403,"endTime":64662,"channelId":0},{"speakerRole":"agent","index":41,"text":"再见。","beginTime":64662,"endTime":65180,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:10:32','2026-05-22 01:10:34','2026-05-22 01:10:31','2026-05-22 01:10:34','system','system','BATCH-20260522-030772',NULL),
(205543,'rec_f271265bd611434db32bd9d2','ext_3f8de921e538496e832b189c842e870b','3844a1d2-854e-4ddb-b7d9-e277c7b396f2.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/c72287d042f04be99da89ed71fc5bea8.mp3',2,146,'mp3',147384,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":0,"endTime":312,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":312,"endTime":936,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问是李先生吗？","beginTime":936,"endTime":3120,"channelId":0},{"speakerRole":"agent","index":3,"text":"晚一点我再说啊。","beginTime":4060,"endTime":5316,"channelId":0},{"speakerRole":"agent","index":4,"text":"你好，","beginTime":5316,"endTime":5675,"channelId":0},{"speakerRole":"agent","index":5,"text":"我是支付宝生产车贷的。","beginTime":5675,"endTime":7470,"channelId":0},{"speakerRole":"agent","index":6,"text":"您刚才提交的车主在线通过了，","beginTime":7470,"endTime":9803,"channelId":0},{"speakerRole":"agent","index":7,"text":"你有注意到吗？","beginTime":9803,"endTime":10880,"channelId":0},{"speakerRole":"agent","index":8,"text":"嗯，","beginTime":11320,"endTime":11526,"channelId":0},{"speakerRole":"agent","index":9,"text":"没有呃，","beginTime":11526,"endTime":13042,"channelId":0},{"speakerRole":"agent","index":10,"text":"您可以在支付宝查看一下，","beginTime":13042,"endTime":15052,"channelId":0},{"speakerRole":"agent","index":11,"text":"接下来由我协助您走后面的放款流程。","beginTime":15052,"endTime":17975,"channelId":0},{"speakerRole":"agent","index":12,"text":"我们全程现场签约是没有任何手续费的哈。","beginTime":17975,"endTime":21263,"channelId":0},{"speakerRole":"agent","index":13,"text":"您觉得的青a h七八二三这辆车在您自己名下吗？","beginTime":21263,"endTime":25100,"channelId":0},{"speakerRole":"agent","index":14,"text":"都出一声公司名下哦，","beginTime":26220,"endTime":30760,"channelId":0},{"speakerRole":"agent","index":15,"text":"因为这个是我们需要车主本人办理才可以哦，","beginTime":30760,"endTime":34199,"channelId":0},{"speakerRole":"agent","index":16,"text":"要个人名下才行。","beginTime":34199,"endTime":35466,"channelId":0},{"speakerRole":"agent","index":17,"text":"您自己名下有没有查询款车辆呢？","beginTime":35466,"endTime":38000,"channelId":0},{"speakerRole":"agent","index":18,"text":"嗯，","beginTime":39440,"endTime":39608,"channelId":0},{"speakerRole":"agent","index":19,"text":"就是您方方便用您自己名下的车辆办理吧。","beginTime":39608,"endTime":42640,"channelId":0},{"speakerRole":"agent","index":20,"text":"说嗯，","beginTime":42900,"endTime":44225,"channelId":0},{"speakerRole":"agent","index":21,"text":"好的，","beginTime":44225,"endTime":44555,"channelId":0},{"speakerRole":"agent","index":22,"text":"那这边可以帮您核实一下您的车辆信息。","beginTime":44555,"endTime":47364,"channelId":0},{"speakerRole":"agent","index":23,"text":"就是您可以把那个车牌车的行驶证照片发给我一下，","beginTime":47364,"endTime":50999,"channelId":0},{"speakerRole":"agent","index":24,"text":"帮您预估一下额度的手机号是您微信吗？","beginTime":50999,"endTime":53807,"channelId":0},{"speakerRole":"agent","index":25,"text":"我这边取得是下一下您嗯。","beginTime":53807,"endTime":57520,"channelId":0},{"speakerRole":"agent","index":26,"text":"哦，","beginTime":60000,"endTime":60149,"channelId":0},{"speakerRole":"agent","index":27,"text":"我这边已经添加您了，","beginTime":60149,"endTime":61497,"channelId":0},{"speakerRole":"agent","index":28,"text":"在微信服务通知里面，","beginTime":61497,"endTime":62845,"channelId":0},{"speakerRole":"agent","index":29,"text":"您看有没有收到呢？","beginTime":62845,"endTime":64043,"channelId":0},{"speakerRole":"agent","index":30,"text":"一个乘车小喇叭，","beginTime":64043,"endTime":65091,"channelId":0},{"speakerRole":"agent","index":31,"text":"我叫吴孟男，","beginTime":65091,"endTime":65840,"channelId":0},{"speakerRole":"agent","index":32,"text":"就在您微信的聊天界面，","beginTime":67260,"endTime":69095,"channelId":0},{"speakerRole":"agent","index":33,"text":"一个橙色小喇叭。","beginTime":69095,"endTime":70380,"channelId":0},{"speakerRole":"agent","index":34,"text":"行，","beginTime":72660,"endTime":72934,"channelId":0},{"speakerRole":"agent","index":35,"text":"我还想给微信，","beginTime":72934,"endTime":74580,"channelId":0},{"speakerRole":"agent","index":36,"text":"你说什么，","beginTime":75540,"endTime":76270,"channelId":0},{"speakerRole":"agent","index":37,"text":"你声音有点小的，","beginTime":76270,"endTime":77549,"channelId":0},{"speakerRole":"agent","index":38,"text":"都听不清利息是多少啊？","beginTime":77549,"endTime":79603,"channelId":0},{"speakerRole":"agent","index":39,"text":"利息的话，","beginTime":79603,"endTime":80312,"channelId":0},{"speakerRole":"agent","index":40,"text":"这边因为您这边还没上传资料，","beginTime":80312,"endTime":82617,"channelId":0},{"speakerRole":"agent","index":41,"text":"上传资料过后才会确定您的利息。","beginTime":82617,"endTime":85100,"channelId":0},{"speakerRole":"agent","index":42,"text":"我们利息都是八点四到一三一四，","beginTime":85360,"endTime":87560,"channelId":0},{"speakerRole":"agent","index":43,"text":"一万块钱是多少？","beginTime":89020,"endTime":91522,"channelId":0},{"speakerRole":"agent","index":44,"text":"嗯，","beginTime":91522,"endTime":91880,"channelId":0},{"speakerRole":"agent","index":45,"text":"最高的话也就一千块钱一个月。","beginTime":93140,"endTime":95800,"channelId":0},{"speakerRole":"agent","index":46,"text":"好好。","beginTime":96080,"endTime":96940,"channelId":0},{"speakerRole":"agent","index":47,"text":"你看看有没有收到呢，","beginTime":105760,"endTime":108001,"channelId":0},{"speakerRole":"agent","index":48,"text":"哦哦，","beginTime":108001,"endTime":108500,"channelId":0},{"speakerRole":"agent","index":49,"text":"一万，","beginTime":108820,"endTime":109189,"channelId":0},{"speakerRole":"agent","index":50,"text":"如果一万块钱一年的话，","beginTime":109189,"endTime":111034,"channelId":0},{"speakerRole":"agent","index":51,"text":"一千块钱左右哈，","beginTime":111034,"endTime":112326,"channelId":0},{"speakerRole":"agent","index":52,"text":"就错了，","beginTime":112326,"endTime":112880,"channelId":0},{"speakerRole":"agent","index":53,"text":"一年一天嗯，","beginTime":114180,"endTime":116260,"channelId":0},{"speakerRole":"agent","index":54,"text":"对。","beginTime":116260,"endTime":116800,"channelId":0},{"speakerRole":"agent","index":55,"text":"嗯，","beginTime":127140,"endTime":127293,"channelId":0},{"speakerRole":"agent","index":56,"text":"好的，","beginTime":127293,"endTime":127600,"channelId":0},{"speakerRole":"agent","index":57,"text":"我收到的。","beginTime":127600,"endTime":128213,"channelId":0},{"speakerRole":"agent","index":58,"text":"那您把行驶证照片可以发给我一下，","beginTime":128213,"endTime":130513,"channelId":0},{"speakerRole":"agent","index":59,"text":"我这边帮您评估一下额度。","beginTime":130513,"endTime":132200,"channelId":0},{"speakerRole":"agent","index":60,"text":"电子都可以吗？","beginTime":134300,"endTime":135520,"channelId":0},{"speakerRole":"agent","index":61,"text":"可以呀。","beginTime":136200,"endTime":137360,"channelId":0},{"speakerRole":"agent","index":62,"text":"那到时候有什么问题，","beginTime":141020,"endTime":142544,"channelId":0},{"speakerRole":"agent","index":63,"text":"微信随时联系我们。","beginTime":142544,"endTime":143900,"channelId":0},{"speakerRole":"agent","index":64,"text":"嗯，","beginTime":144700,"endTime":145030,"channelId":0},{"speakerRole":"agent","index":65,"text":"好，","beginTime":145030,"endTime":145360,"channelId":0},{"speakerRole":"agent","index":66,"text":"拜拜。","beginTime":145360,"endTime":146020,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:10:47','2026-05-22 01:10:49','2026-05-22 01:10:44','2026-05-22 01:10:49','system','system','BATCH-20260522-030772',NULL),
