ndTime":201357,"channelId":0},{"speakerRole":"agent","index":133,"text":"因为我这边电话您是联系不过来的。","beginTime":201357,"endTime":203447,"channelId":0},{"speakerRole":"agent","index":134,"text":"呃，","beginTime":203447,"endTime":203586,"channelId":0},{"speakerRole":"agent","index":135,"text":"方便的话，","beginTime":203586,"endTime":204143,"channelId":0},{"speakerRole":"agent","index":136,"text":"我就添加一下您。","beginTime":204143,"endTime":205118,"channelId":0},{"speakerRole":"agent","index":137,"text":"您后有这个需要的话，","beginTime":205118,"endTime":206372,"channelId":0},{"speakerRole":"agent","index":138,"text":"你随时联系我就行了，","beginTime":206372,"endTime":207625,"channelId":0},{"speakerRole":"agent","index":139,"text":"有问题你随时找我。","beginTime":207625,"endTime":208740,"channelId":0},{"speakerRole":"agent","index":140,"text":"嗯，","beginTime":208980,"endTime":209140,"channelId":0},{"speakerRole":"agent","index":141,"text":"好的，","beginTime":209140,"endTime":209460,"channelId":0},{"speakerRole":"agent","index":142,"text":"呃，","beginTime":209460,"endTime":209620,"channelId":0},{"speakerRole":"agent","index":143,"text":"支付宝上面它是有显示我的名字的。","beginTime":209620,"endTime":212020,"channelId":0},{"speakerRole":"agent","index":144,"text":"重庆小米椒金住持阳，","beginTime":212020,"endTime":213460,"channelId":0},{"speakerRole":"agent","index":145,"text":"您是可以看到的。","beginTime":213460,"endTime":214580,"channelId":0},{"speakerRole":"agent","index":146,"text":"嗯，","beginTime":214820,"endTime":214986,"channelId":0},{"speakerRole":"agent","index":147,"text":"好的，","beginTime":214986,"endTime":215319,"channelId":0},{"speakerRole":"agent","index":148,"text":"呃，","beginTime":215319,"endTime":215485,"channelId":0},{"speakerRole":"agent","index":149,"text":"这个刘刘里说不清楚您的微信名称，","beginTime":215485,"endTime":217980,"channelId":0},{"speakerRole":"agent","index":150,"text":"对吧？","beginTime":217980,"endTime":218313,"channelId":0},{"speakerRole":"agent","index":151,"text":"对，","beginTime":218313,"endTime":218479,"channelId":0},{"speakerRole":"agent","index":152,"text":"好的，","beginTime":218479,"endTime":218812,"channelId":0},{"speakerRole":"agent","index":153,"text":"对我添加您了啊。","beginTime":218812,"endTime":219976,"channelId":0},{"speakerRole":"agent","index":154,"text":"您官方的微信会有一个服务通知，","beginTime":219976,"endTime":222305,"channelId":0},{"speakerRole":"agent","index":155,"text":"您点击进去就是通讯、小米消金朱志阳，","beginTime":222305,"endTime":224966,"channelId":0},{"speakerRole":"agent","index":156,"text":"就是我的一个微信名片，","beginTime":224966,"endTime":226630,"channelId":0},{"speakerRole":"agent","index":157,"text":"您扫码识别添加一下。","beginTime":226630,"endTime":228127,"channelId":0},{"speakerRole":"agent","index":158,"text":"好吧。","beginTime":228127,"endTime":228460,"channelId":0},{"speakerRole":"agent","index":159,"text":"好的好的，","beginTime":228700,"endTime":229374,"channelId":0},{"speakerRole":"agent","index":160,"text":"哎，","beginTime":229374,"endTime":229543,"channelId":0},{"speakerRole":"agent","index":161,"text":"好，","beginTime":229543,"endTime":229712,"channelId":0},{"speakerRole":"agent","index":162,"text":"行行，","beginTime":229712,"endTime":230049,"channelId":0},{"speakerRole":"agent","index":163,"text":"那我这边先不打扰您了啊。","beginTime":230049,"endTime":231905,"channelId":0},{"speakerRole":"agent","index":164,"text":"好，","beginTime":231905,"endTime":232073,"channelId":0},{"speakerRole":"agent","index":165,"text":"再见啊。","beginTime":232073,"endTime":232580,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 01:11:27','2026-05-22 01:11:31','2026-05-22 01:11:23','2026-05-22 01:11:31','system','system','BATCH-20260522-030772',NULL),
