(205564,'rec_c483236f109f45b4a64611a7','ext_36ec6350e59d4a78bc667b4463c6f15c','38c2ec1e-af1a-47bf-864a-a2084bcaed84.mp3',2023391656704524699,8,2057750945180004354,2,5,'/data/upload/records/2023391656704524699/20260522/3237bbf6485e41a5aec59b5a089c5360.mp3',2,89,'mp3',91728,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"给你走流，","beginTime":140,"endTime":1056,"channelId":0},{"speakerRole":"agent","index":1,"text":"你说我这边喂喂，","beginTime":1056,"endTime":2660,"channelId":0},{"speakerRole":"agent","index":2,"text":"你好哎，","beginTime":2660,"endTime":3347,"channelId":0},{"speakerRole":"agent","index":3,"text":"你好，","beginTime":3347,"endTime":3805,"channelId":0},{"speakerRole":"agent","index":4,"text":"是沈先生，","beginTime":3805,"endTime":4721,"channelId":0},{"speakerRole":"agent","index":5,"text":"对吧？","beginTime":4721,"endTime":5180,"channelId":0},{"speakerRole":"agent","index":6,"text":"啊，","beginTime":5420,"endTime":5615,"channelId":0},{"speakerRole":"agent","index":7,"text":"哎你好，","beginTime":5615,"endTime":6201,"channelId":0},{"speakerRole":"agent","index":8,"text":"我昨天晚上看你哦，","beginTime":6201,"endTime":7765,"channelId":0},{"speakerRole":"agent","index":9,"text":"嗯七就今天早上七点四十九分的时候，","beginTime":7765,"endTime":10893,"channelId":0},{"speakerRole":"agent","index":10,"text":"你有在支付宝上面进行一个操作，","beginTime":10893,"endTime":13629,"channelId":0},{"speakerRole":"agent","index":11,"text":"下款呢，","beginTime":13629,"endTime":14216,"channelId":0},{"speakerRole":"agent","index":12,"text":"这边是需要安排吗？","beginTime":14216,"endTime":15780,"channelId":0},{"speakerRole":"agent","index":13,"text":"哦，","beginTime":16920,"endTime":17141,"channelId":0},{"speakerRole":"agent","index":14,"text":"我先看一下考虑呃，","beginTime":17141,"endTime":18915,"channelId":0},{"speakerRole":"agent","index":15,"text":"你是担心哪方面嘛，","beginTime":18915,"endTime":20689,"channelId":0},{"speakerRole":"agent","index":16,"text":"你可以跟我说哦，","beginTime":20689,"endTime":22890,"channelId":0},{"speakerRole":"agent","index":17,"text":"没有那个那个时间有点长哦。","beginTime":22890,"endTime":26065,"channelId":0},{"speakerRole":"agent","index":18,"text":"呃，","beginTime":26065,"endTime":26250,"channelId":0},{"speakerRole":"agent","index":19,"text":"是这样的是这样，","beginTime":26250,"endTime":27549,"channelId":0},{"speakerRole":"agent","index":20,"text":"的哥，","beginTime":27549,"endTime":27920,"channelId":0},{"speakerRole":"agent","index":21,"text":"你先听我说车主的，","beginTime":27920,"endTime":29403,"channelId":0},{"speakerRole":"agent","index":22,"text":"它是默认的一个三十六期。","beginTime":29403,"endTime":31443,"channelId":0},{"speakerRole":"agent","index":23,"text":"然后你用多久，","beginTime":31443,"endTime":32556,"channelId":0},{"speakerRole":"agent","index":24,"text":"我们就算你多久的那些可以可以提前结清的。","beginTime":32556,"endTime":36080,"channelId":0},{"speakerRole":"agent","index":25,"text":"你大你大概用多久时间吧，","beginTime":38160,"endTime":40312,"channelId":0},{"speakerRole":"agent","index":26,"text":"这个钱。","beginTime":40312,"endTime":40900,"channelId":0},{"speakerRole":"agent","index":27,"text":"应该半年左右吧，","beginTime":42920,"endTime":44190,"channelId":0},{"speakerRole":"agent","index":28,"text":"那你用半年或者一年，","beginTime":44190,"endTime":45823,"channelId":0},{"speakerRole":"agent","index":29,"text":"就你提前结清就可以了呀。","beginTime":45823,"endTime":47820,"channelId":0},{"speakerRole":"agent","index":30,"text":"嗯但是没有违约金啊，","beginTime":48680,"endTime":50244,"channelId":0},{"speakerRole":"agent","index":31,"text":"你一年之后它是没有违约金的。","beginTime":50244,"endTime":52504,"channelId":0},{"speakerRole":"agent","index":32,"text":"就如果说违约金的话，","beginTime":52504,"endTime":54069,"channelId":0},{"speakerRole":"agent","index":33,"text":"我可以帮你把。","beginTime":54069,"endTime":55112,"channelId":0},{"speakerRole":"agent","index":34,"text":"因为他正常情况下，","beginTime":55112,"endTime":56503,"channelId":0},{"speakerRole":"agent","index":35,"text":"违约金是百分之六，","beginTime":56503,"endTime":57893,"channelId":0},{"speakerRole":"agent","index":36,"text":"我可以帮你把违约金申请到。","beginTime":57893,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":37,"text":"不是啊，","beginTime":60000,"endTime":60476,"channelId":0},{"speakerRole":"agent","index":38,"text":"如果说你用满一年就没有任何违约金。","beginTime":60476,"endTime":63020,"channelId":0},{"speakerRole":"agent","index":39,"text":"呃，","beginTime":64280,"endTime":64451,"channelId":0},{"speakerRole":"agent","index":40,"text":"没事，","beginTime":64451,"endTime":64795,"channelId":0},{"speakerRole":"agent","index":41,"text":"我先考虑一下吧，","beginTime":64795,"endTime":65997,"channelId":0},{"speakerRole":"agent","index":42,"text":"这样吧，","beginTime":65997,"endTime":66512,"channelId":0},{"speakerRole":"agent","index":43,"text":"行吧，","beginTime":66512,"endTime":66856,"channelId":0},{"speakerRole":"agent","index":44,"text":"这样吧，","beginTime":66856,"endTime":67371,"channelId":0},{"speakerRole":"agent","index":45,"text":"这样就是我加你一个微信吧，","beginTime":67371,"endTime":69432,"channelId":0},{"speakerRole":"agent","index":46,"text":"我用我的企业微信添加你。","beginTime":69432,"endTime":71322,"channelId":0},{"speakerRole":"agent","index":47,"text":"你到时候如果说方便了，","beginTime":71322,"endTime":73040,"channelId":0},{"speakerRole":"agent","index":48,"text":"就微信上面我们两个沟通就可以了，","beginTime":73040,"endTime":75616,"channelId":0},{"speakerRole":"agent","index":49,"text":"好吧。","beginTime":75616,"endTime":75960,"channelId":0},{"speakerRole":"agent","index":50,"text":"啊，","beginTime":76340,"endTime":76532,"channelId":0},{"speakerRole":"agent","index":51,"text":"好好，","beginTime":76532,"endTime":76917,"channelId":0},{"speakerRole":"agent","index":52,"text":"你是你的那个微信是叫沈明吗？","beginTime":76917,"endTime":79420,"channelId":0},{"speakerRole":"agent","index":53,"text":"对对对，","beginTime":79700,"endTime":80180,"channelId":0},{"speakerRole":"agent","index":54,"text":"哎，","beginTime":80180,"endTime":80340,"channelId":0},{"speakerRole":"agent","index":55,"text":"我加你了，","beginTime":80340,"endTime":80980,"channelId":0},{"speakerRole":"agent","index":56,"text":"就是你的微信有一个黄色的喇叭服务通知，","beginTime":80980,"endTime":83860,"channelId":0},{"speakerRole":"agent","index":57,"text":"点进去识别二维码就可以通过我哈。","beginTime":83860,"endTime":86260,"channelId":0},{"speakerRole":"agent","index":58,"text":"啊。","beginTime":86580,"endTime":86928,"channelId":0},{"speakerRole":"agent","index":59,"text":"嗯嗯，","beginTime":86928,"endTime":87625,"channelId":0},{"speakerRole":"agent","index":60,"text":"好嘞好嘞。","beginTime":87625,"endTime":89020,"channelId":0}]}',80,NULL,NULL,0,0,2,'2026-05-22 01:11:32','2026-05-22 01:11:35','2026-05-22 01:11:28','2026-05-22 01:11:35','system','system','BATCH-20260522-030772',NULL);
