channelId":0},{"speakerRole":"agent","index":95,"text":"你要点到了呀，","beginTime":149644,"endTime":151548,"channelId":0},{"speakerRole":"agent","index":96,"text":"哥点赞。","beginTime":151548,"endTime":152500,"channelId":0},{"speakerRole":"agent","index":97,"text":"呃，","beginTime":153100,"endTime":153350,"channelId":0},{"speakerRole":"agent","index":98,"text":"呃，","beginTime":153350,"endTime":153600,"channelId":0},{"speakerRole":"agent","index":99,"text":"三月份呢工地上我干的工程要抵出去了。","beginTime":153600,"endTime":157880,"channelId":0},{"speakerRole":"agent","index":100,"text":"那个是哦，","beginTime":157880,"endTime":158736,"channelId":0},{"speakerRole":"agent","index":101,"text":"哦，","beginTime":158736,"endTime":158950,"channelId":0},{"speakerRole":"agent","index":102,"text":"你的意思是直接抵出去了。","beginTime":158950,"endTime":161303,"channelId":0},{"speakerRole":"agent","index":103,"text":"对哦，","beginTime":161303,"endTime":161731,"channelId":0},{"speakerRole":"agent","index":104,"text":"哦哦，","beginTime":161731,"endTime":162159,"channelId":0},{"speakerRole":"agent","index":105,"text":"那边抵的话，","beginTime":162159,"endTime":163228,"channelId":0},{"speakerRole":"agent","index":106,"text":"能给你抵多少钱呢？","beginTime":163228,"endTime":164940,"channelId":0},{"speakerRole":"agent","index":107,"text":"嗯，","beginTime":166460,"endTime":167120,"channelId":0},{"speakerRole":"agent","index":108,"text":"肯定最少得六十多万，","beginTime":168060,"endTime":170025,"channelId":0},{"speakerRole":"agent","index":109,"text":"六十多万了，","beginTime":170025,"endTime":171117,"channelId":0},{"speakerRole":"agent","index":110,"text":"六十多万，","beginTime":171117,"endTime":171991,"channelId":0},{"speakerRole":"agent","index":111,"text":"那得六。","beginTime":171991,"endTime":172646,"channelId":0},{"speakerRole":"agent","index":112,"text":"十多万哥，","beginTime":172646,"endTime":173520,"channelId":0},{"speakerRole":"agent","index":113,"text":"我现在卖也能卖四十多万吧。","beginTime":174000,"endTime":175977,"channelId":0},{"speakerRole":"agent","index":114,"text":"嗯你卖的话，