nelId":0},{"speakerRole":"agent","index":134,"text":"别要了吗？","beginTime":198989,"endTime":199875,"channelId":0},{"speakerRole":"agent","index":135,"text":"那肯定要过户的话，","beginTime":199875,"endTime":201755,"channelId":0},{"speakerRole":"agent","index":136,"text":"那白大哥你要说不用过户的话，","beginTime":201755,"endTime":204292,"channelId":0},{"speakerRole":"agent","index":137,"text":"光把车抵给他的话，","beginTime":204292,"endTime":205853,"channelId":0},{"speakerRole":"agent","index":138,"text":"那你们咱们要过户，","beginTime":205853,"endTime":207414,"channelId":0},{"speakerRole":"agent","index":139,"text":"怎么这一哥你不行，","beginTime":207414,"endTime":209122,"channelId":0},{"speakerRole":"agent","index":140,"text":"你把车抵给他，","beginTime":209122,"endTime":210180,"channelId":0},{"speakerRole":"agent","index":141,"text":"让他要开着，","beginTime":210180,"endTime":211062,"channelId":0},{"speakerRole":"agent","index":142,"text":"你到说说说说另去了，","beginTime":211062,"endTime":212650,"channelId":0},{"speakerRole":"agent","index":143,"text":"你别从这带啊。","beginTime":212650,"endTime":213709,"channelId":0},{"speakerRole":"agent","index":144,"text":"哥，","beginTime":213709,"endTime":213885,"channelId":0},{"speakerRole":"agent","index":145,"text":"你不两天你用的钱也多了。","beginTime":213885,"endTime":215826,"channelId":0},{"speakerRole":"agent","index":146,"text":"哥，","beginTime":215826,"endTime":216002,"channelId":0},{"speakerRole":"agent","index":147,"text":"嗯，","beginTime":216002,"endTime":216179,"channelId":0},{"speakerRole":"agent","index":148,"text":"不用了，","beginTime":216179,"endTime":216708,"channelId":0},{"speakerRole":"agent","index":149,"text":"不用了，","beginTime":216708,"endTime":217237,"channelId":0},{"speakerRole":"agent","index":150,"text":"就这吧。","beginTime":217237,"endTime":217767,"channelId":0},{"speakerRole":"agent","index":151,"text":"先啊。","beginTime":217767,"endTime":218120,"channelId":0},{"speakerRole":"agent","index":152,"text":"行，","beginTime":218120,"endTime":218296,"channelId":0},{"speakerRole":"agent","index":153,"text":"哥，","beginTime":218296,"endTime":218472,"channelId":0},{"speakerRole":"agent","index":154,"text":"你要不我加你就企业微信吧。","beginTime":218472,"endTime":220590,"channelId":0},{"speakerRole":"agent","index":155,"text":"哥，","beginTime":220590,"endTime":220766,"channelId":0},{"speakerRole":"agent","index":156,"text":"我就企业微信加您好友。","beginTime":220766,"endTime":222530,"channelId":0},{"speakerRole":"agent","index":157,"text":"然后您后续要是嗯有需要的话，","beginTime":222530,"endTime":224824,"channelId":0},{"speakerRole":"agent","index":158,"text":"你再跟我联系，","beginTime":224824,"endTime":225882,"channelId":0},{"speakerRole":"agent","index":159,"text":"行吧，","beginTime":225882,"endTime":226235,"channelId":0},{"speakerRole":"agent","index":160,"text":"哥，","beginTime":226235,"endTime":226412,"channelId":0},{"speakerRole":"agent","index":161,"text":"嗯，","beginTime":226412,"endTime":226588,"channelId":0},{"speakerRole":"agent","index":162,"text":"七点半吧啊，","beginTime":226588,"endTime":227470,"channelId":0},{"speakerRole":"agent","index":163,"text":"行行哥。","beginTime":227470,"endTime":228000,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:38','2026-05-22 00:23:42','2026-05-22 00:23:35','2026-05-22 00:23:42','system','system','BATCH-20260522-207060',NULL),
(205573,'rec_948f2c8eb72840718592a267','ext_eaa6e9b747984a8a80d7520ea5625c03','8e2090ed-44a7-4799-b41e-8a10c3c5d67d.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/e9abe17284284fc0a6f4766b57ffdf95.mp3',2,102,'mp3',103680,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":0,"endTime":188,"channelId":0},{"speakerRole":"agent","index":1,"text":"你喂你好，","beginTime":188,"endTime":943,"channelId":0},{"speakerRole":"agent","index":2,"text":"哎，","beginTime":943,"endTime":1132,"channelId":0},{"speakerRole":"agent","index":3,"text":"你好，","beginTime":1132,"endTime":1509,"channelId":0},{"speakerRole":"agent","index":4,"text":"陈先生吗？","beginTime":1509,"endTime":2264,"channelId":0},{"speakerRole":"agent","index":5,"text":"呃，","beginTime":2264,"endTime":2453,"channelId":0},{"speakerRole":"agent","index":6,"text":"哪位呃，","beginTime":2453,"endTime":3019,"channelId":0},{"speakerRole":"agent","index":7,"text":"支付宝新能车的官方客服经理，","beginTime":3019,"endTime":5472,"channelId":0},{"speakerRole":"agent","index":8,"text":"就刚才后台看到这边提交了一个车主要的申请订单。","beginTime":5472,"endTime":9624,"channelId":0},{"speakerRole":"agent","index":9,"text":"这个是您本人申请提交的对吧？","beginTime":9624,"endTime":12077,"channelId":0},{"speakerRole":"agent","index":10,"text":"对啊，","beginTime":12077,"endTime":12454,"channelId":0},{"speakerRole":"agent","index":11,"text":"您这边确实已经通过了，","beginTime":12454,"endTime":14341,"channelId":0},{"speakerRole":"agent","index":12,"text":"给您的额度是七万八。","beginTime":14341,"endTime":16040,"channelId":0},{"speakerRole":"agent","index":13,"text":"我这边是对接什么放款呢？","beginTime":16040,"endTime":18115,"channelId":0},{"speakerRole":"agent","index":14,"text":"简单核对一下车辆，","beginTime":18115,"endTime":19625,"channelId":0},{"speakerRole":"agent","index":15,"text":"对接您填的车牌号是晋d四五六九v这个是本理想车辆，","beginTime":19625,"endTime":24154,"channelId":0},{"speakerRole":"agent","index":16,"text":"没错吧？","beginTime":24154,"endTime":24720,"channelId":0},{"speakerRole":"agent","index":17,"text":"对呃，","beginTime":24720,"endTime":25098,"channelId":0},{"speakerRole":"agent","index":18,"text":"目前这个设置全款按揭状态，","beginTime":25098,"endTime":27362,"channelId":0},{"speakerRole":"agent","index":19,"text":"现在小管有行驶证，","beginTime":27362,"endTime":29215,"channelId":0},{"speakerRole":"agent","index":20,"text":"日本都在是吗？","beginTime":29215,"endTime":30350,"channelId":0},{"speakerRole":"agent","index":21,"text":"对，","beginTime":30350,"endTime":30539,"channelId":0},{"speakerRole":"agent","index":22,"text":"嗯，","beginTime":30539,"endTime":30728,"channelId":0},{"speakerRole":"agent","index":23,"text":"可以的。","beginTime":30728,"endTime":31295,"channelId":0},{"speakerRole":"agent","index":24,"text":"然后前面您这边是符合放款条件的，","beginTime":31295,"endTime":34133,"channelId":0},{"speakerRole":"agent","index":25,"text":"我们是全程线上办理，","beginTime":34133,"endTime":35835,"channelId":0},{"speakerRole":"agent","index":26,"text":"没有任何的手续费服务费。","beginTime":35835,"endTime":37916,"channelId":0},{"speakerRole":"agent","index":27,"text":"然后资料完善之后的话，","beginTime":37916,"endTime":39808,"channelId":0},{"speakerRole":"agent","index":28,"text":"当天可以放款，","beginTime":39808,"endTime":40943,"channelId":0},{"speakerRole":"agent","index":29,"text":"订单也是是直接循环的。","beginTime":40943,"endTime":42835,"channelId":0},{"speakerRole":"agent","index":30,"text":"你这个资金的话大概要等什么时候使用啊，","beginTime":42835,"endTime":46240,"channelId":0},{"speakerRole":"agent","index":31,"text":"哎呀，","beginTime":47200,"endTime":47604,"channelId":0},{"speakerRole":"agent","index":32,"text":"我最近看看吧，","beginTime":47604,"endTime":48819,"channelId":0},{"speakerRole":"agent","index":33,"text":"嗯，","beginTime":48819,"endTime":49021,"channelId":0},{"speakerRole":"agent","index":34,"text":"就是，","beginTime":49021,"endTime":49426,"channelId":0},{"speakerRole":"agent","index":35,"text":"暂时不用，","beginTime":49426,"endTime":50236,"channelId":0},{"speakerRole":"agent","index":36,"text":"是说备用灯泡还是什么不用了，","beginTime":50236,"endTime":52868,"channelId":0},{"speakerRole":"agent","index":37,"text":"用得上的话，","beginTime":52868,"endTime":53880,"channelId":0},{"speakerRole":"agent","index":38,"text":"没办法，","beginTime":53880,"endTime":54487,"channelId":0},{"speakerRole":"agent","index":39,"text":"就只能带了哦。","beginTime":54487,"endTime":55909,"channelId":0},{"speakerRole":"agent","index":40,"text":"因为你目前不是只填了一个车牌号码，","beginTime":55909,"endTime":58623,"channelId":0},{"speakerRole":"agent","index":41,"text":"需要完善一下车辆，","beginTime":58623,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":42,"text":"我们要核实试驾车辆。","beginTime":60000,"endTime":61562,"channelId":0},{"speakerRole":"agent","index":43,"text":"车辆核实通过之后，","beginTime":61562,"endTime":62951,"channelId":0},{"speakerRole":"agent","index":44,"text":"这个钱的话，","beginTime":62951,"endTime":63819,"channelId":0},{"speakerRole":"agent","index":45,"text":"就可以随时进行提取使用了。","beginTime":63819,"endTime":65902,"channelId":0},{"speakerRole":"agent","index":46,"text":"然后的话提取到你的账户之后的话，","beginTime":65902,"endTime":68506,"channelId":0},{"speakerRole":"agent","index":47,"text":"就可以进行正常一个支付。","beginTime":68506,"endTime":70416,"channelId":0},{"speakerRole":"agent","index":48,"text":"你最近准备用来做什么的呀？","beginTime":70416,"endTime":72500,"channelId":0},{"speakerRole":"agent","index":49,"text":"什么，","beginTime":72960,"endTime":73412,"channelId":0},{"speakerRole":"agent","index":50,"text":"我说你这里是怎么用来做评的呀？","beginTime":73412,"endTime":76580,"channelId":0},{"speakerRole":"agent","index":51,"text":"我是做工地的啊，","beginTime":77920,"endTime":79236,"channelId":0},{"speakerRole":"agent","index":52,"text":"就是上不上资金周转是吧？","beginTime":79236,"endTime":81304,"channelId":0},{"speakerRole":"agent","index":53,"text":"对对对，","beginTime":81304,"endTime":81868,"channelId":0},{"speakerRole":"agent","index":54,"text":"嗯，","beginTime":81868,"endTime":82056,"channelId":0},{"speakerRole":"agent","index":55,"text":"可以的。","beginTime":82056,"endTime":82620,"channelId":0},{"speakerRole":"agent","index":56,"text":"然后的话回头我用官方体验加上你。","beginTime":82620,"endTime":85440,"channelId":0},{"speakerRole":"agent","index":57,"text":"然后后面我把那个上传资料的模板和用款流程发给你微信上。","beginTime":85440,"endTime":90328,"channelId":0},{"speakerRole":"agent","index":58,"text":"我之前走到了微信，","beginTime":90328,"endTime":91832,"channelId":0},{"speakerRole":"agent","index":59,"text":"你再问我好吧，","beginTime":91832,"endTime":92960,"channelId":0},{"speakerRole":"agent","index":60,"text":"行了行了行了，","beginTime":93200,"endTime":94453,"channelId":0},{"speakerRole":"agent","index":61,"text":"嗯，","beginTime":94453,"endTime":94661,"channelId":0},{"speakerRole":"agent","index":62,"text":"好好，","beginTime":94661,"endTime":95079,"channelId":0},{"speakerRole":"agent","index":63,"text":"我是官方企业家，","beginTime":95079,"endTime":96541,"channelId":0},{"speakerRole":"agent","index":64,"text":"你在微信聊天中有服务通知，","beginTime":96541,"endTime":99047,"channelId":0},{"speakerRole":"agent","index":65,"text":"你看一下看一下。","beginTime":99047,"endTime":100509,"channelId":0},{"speakerRole":"agent","index":66,"text":"嗯，","beginTime":100509,"endTime":100718,"channelId":0},{"speakerRole":"agent","index":67,"text":"好嗯嗯，","beginTime":100718,"endTime":101344,"channelId":0},{"speakerRole":"agent","index":68,"text":"好好，","beginTime":101344,"endTime":101762,"channelId":0},{"speakerRole":"agent","index":69,"text":"再见。","beginTime":101762,"endTime":102180,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:38','2026-05-22 00:23:41','2026-05-22 00:23:36','2026-05-22 00:23:41','system','system','BATCH-20260522-207060',NULL),
(205574,'rec_03f49f4e05144b9ea0f492ad','ext_042f44ca8337466084e4aa9cdc08bddc','45ce2df4-064c-4c34-b3f3-1f7f92d7ee05.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/88e412fcbed04888a712f248232797a5.mp3',2,79,'mp3',80352,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"花儿的哥哥，","beginTime":0,"endTime":1320,"channelId":0},{"speakerRole":"agent","index":1,"text":"喂喂，","beginTime":1980,"endTime":3413,"channelId":0},{"speakerRole":"agent","index":2,"text":"你好你好，","beginTime":3413,"endTime":4789,"channelId":0},{"speakerRole":"agent","index":3,"text":"请是欧先生吗？","beginTime":4789,"endTime":6078,"channelId":0},{"speakerRole":"agent","index":4,"text":"嗯，","beginTime":6078,"endTime":6293,"channelId":0},{"speakerRole":"agent","index":5,"text":"哪位？","beginTime":6293,"endTime":6722,"channelId":0},{"speakerRole":"agent","index":6,"text":"你好，","beginTime":6722,"endTime":7152,"channelId":0},{"speakerRole":"agent","index":7,"text":"欧先生，","beginTime":7152,"endTime":7796,"channelId":0},{"speakerRole":"agent","index":8,"text":"我这边是支付宝汽车车贷客户经理。","beginTime":7796,"endTime":11018,"channelId":0},{"speakerRole":"agent","index":9,"text":"呃，","beginTime":11018,"endTime":11233,"channelId":0},{"speakerRole":"agent","index":10,"text":"您在我们这边平台上有申请车主的申请额度已通过了，","beginTime":11233,"endTime":16173,"channelId":0},{"speakerRole":"agent","index":11,"text":"是十二万一千九百，","beginTime":16173,"endTime":17892,"channelId":0},{"speakerRole":"agent","index":12,"text":"这个是你本人申请的吗？","beginTime":17892,"endTime":20040,"channelId":0},{"speakerRole":"agent","index":13,"text":"呃，","beginTime":21360,"endTime":21575,"channelId":0},{"speakerRole":"agent","index":14,"text":"对对对，","beginTime":21575,"endTime":22220,"channelId":0},{"speakerRole":"agent","index":15,"text":"哎，","beginTime":22220,"endTime":22435,"channelId":0},{"speakerRole":"agent","index":16,"text":"我来电的话是核对您的信息，","beginTime":22435,"endTime":25016,"channelId":0},{"speakerRole":"agent","index":17,"text":"协助您是放款您这边的一个信息，","beginTime":25016,"endTime":28028,"channelId":0},{"speakerRole":"agent","index":18,"text":"我这已通过哈是十二万一千九百。","beginTime":28028,"endTime":31040,"channelId":0},{"speakerRole":"agent","index":19,"text":"这个您车牌号提供的是浙g零二x m九呃，","beginTime":31280,"endTime":35674,"channelId":0},{"speakerRole":"agent","index":20,"text":"车子是您本人名下的对吧？","beginTime":35674,"endTime":38360,"channelId":0},{"speakerRole":"agent","index":21,"text":"嗯，","beginTime":38880,"endTime":39193,"channelId":0},{"speakerRole":"agent","index":22,"text":"是的，","beginTime":39193,"endTime":39820,"channelId":0},{"speakerRole":"agent","index":23,"text":"目前车子是全款吗？","beginTime":40220,"endTime":41890,"channelId":0},{"speakerRole":"agent","index":24,"text":"还是有按揭贷款呢？","beginTime":41890,"endTime":43560,"channelId":0},{"speakerRole":"agent","index":25,"text":"呃，","beginTime":43800,"endTime":44020,"channelId":0},{"speakerRole":"agent","index":26,"text":"按揭贷款嗯还有多久没听？","beginTime":44020,"endTime":47700,"channelId":0},{"speakerRole":"agent","index":27,"text":"呃，","beginTime":48580,"endTime":48944,"channelId":0},{"speakerRole":"agent","index":28,"text":"还有两年还有两年是吧？","beginTime":48944,"endTime":52280,"channelId":0},{"speakerRole":"agent","index":29,"text":"嗯，","beginTime":52520,"endTime":53160,"channelId":0},{"speakerRole":"agent","index":30,"text":"哦那您这个日本有没有呀？","beginTime":53600,"endTime":56980,"channelId":0},{"speakerRole":"agent","index":31,"text":"呃绿本没有，","beginTime":57540,"endTime":58840,"channelId":0},{"speakerRole":"agent","index":32,"text":"日本没有的是吧？","beginTime":59100,"endTime":61400,"channelId":0},{"speakerRole":"agent","index":33,"text":"嗯，","beginTime":63000,"endTime":63206,"channelId":0},{"speakerRole":"agent","index":34,"text":"好的，","beginTime":63206,"endTime":63620,"channelId":0},{"speakerRole":"agent","index":35,"text":"那这边的话，","beginTime":63620,"endTime":64653,"channelId":0},{"speakerRole":"agent","index":36,"text":"您申请的是超速的，","beginTime":64653,"endTime":66306,"channelId":0},{"speakerRole":"agent","index":37,"text":"它需要有日本才能办理。","beginTime":66306,"endTime":68373,"channelId":0},{"speakerRole":"agent","index":38,"text":"名下还有其他的车子吗？","beginTime":68373,"endTime":70440,"channelId":0},{"speakerRole":"agent","index":39,"text":"呃，","beginTime":71160,"endTime":71733,"channelId":0},{"speakerRole":"agent","index":40,"text":"没有哦，","beginTime":71733,"endTime":73863,"channelId":0},{"speakerRole":"agent","index":41,"text":"那行，","beginTime":73863,"endTime":74231,"channelId":0},{"speakerRole":"agent","index":42,"text":"那我就不打扰你了哈，","beginTime":74231,"endTime":75885,"channelId":0},{"speakerRole":"agent","index":43,"text":"暂时不符合我们的八点要求，","beginTime":75885,"endTime":78090,"channelId":0},{"speakerRole":"agent","index":44,"text":"感谢您的接听，","beginTime":78090,"endTime":79192,"channelId":0},{"speakerRole":"agent","index":45,"text":"再见。","beginTime":79192,"endTime":79560,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:41','2026-05-22 00:23:43','2026-05-22 00:23:37','2026-05-22 00:23:43','system','system','BATCH-20260522-207060',NULL),
(205575,'rec_fdc4045a862e4370b6275465','ext_40d45e99cc34471cbf35c107c0d06200','68b4e644-c34e-4ee8-a420-d9b6d935c01c.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/605a59f5bacc4fd3a32cbe8617fc06fc.mp3',2,74,'mp3',76176,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":1480,"endTime":1756,"channelId":0},{"speakerRole":"agent","index":1,"text":"马先生，","beginTime":1756,"endTime":2585,"channelId":0},{"speakerRole":"agent","index":2,"text":"哎，","beginTime":2585,"endTime":2862,"channelId":0},{"speakerRole":"agent","index":3,"text":"你好哦，","beginTime":2862,"endTime":3691,"channelId":0},{"speakerRole":"agent","index":4,"text":"我这边是新选车贷的。","beginTime":3691,"endTime":6180,"channelId":0},{"speakerRole":"agent","index":5,"text":"喂，","beginTime":8420,"endTime":9220,"channelId":0},{"speakerRole":"agent","index":6,"text":"呃您说哎，","beginTime":9600,"endTime":10345,"channelId":0},{"speakerRole":"agent","index":7,"text":"就是您昨天不是在新选车贷里面提交了一个资料嘛，","beginTime":10345,"endTime":14448,"channelId":0},{"speakerRole":"agent","index":8,"text":"然后一直就没联系上您。","beginTime":14448,"endTime":16312,"channelId":0},{"speakerRole":"agent","index":9,"text":"呃，","beginTime":16312,"endTime":16499,"channelId":0},{"speakerRole":"agent","index":10,"text":"刚刚看到您进去看了一下还款表嘛，","beginTime":16499,"endTime":19296,"channelId":0},{"speakerRole":"agent","index":11,"text":"您这个时间是今天需要几款吗？","beginTime":19296,"endTime":21720,"channelId":0},{"speakerRole":"agent","index":12,"text":"啊，","beginTime":23320,"endTime":23493,"channelId":0},{"speakerRole":"agent","index":13,"text":"那你就得用什么车抵押什么的吧，","beginTime":23493,"endTime":25917,"channelId":0},{"speakerRole":"agent","index":14,"text":"是吧，","beginTime":25917,"endTime":26264,"channelId":0},{"speakerRole":"agent","index":15,"text":"不需要啊，","beginTime":26264,"endTime":26956,"channelId":0},{"speakerRole":"agent","index":16,"text":"我们这个没有车抵押呀，","beginTime":26956,"endTime":28688,"channelId":0},{"speakerRole":"agent","index":17,"text":"我们这个他是不押车，","beginTime":28688,"endTime":30247,"channelId":0},{"speakerRole":"agent","index":18,"text":"不愿意抽，","beginTime":30247,"endTime":30940,"channelId":0},{"speakerRole":"agent","index":19,"text":"也不押，","beginTime":30940,"endTime":31459,"channelId":0},{"speakerRole":"agent","index":20,"text":"你都用用钥匙的。","beginTime":31459,"endTime":32672,"channelId":0},{"speakerRole":"agent","index":21,"text":"只是说我们放款了过后，","beginTime":32672,"endTime":34403,"channelId":0},{"speakerRole":"agent","index":22,"text":"你那个绿本是需要寄到你们当地的一个车管所去帮你抵押登记。","beginTime":34403,"endTime":39080,"channelId":0},{"speakerRole":"agent","index":23,"text":"就是一直意思就是牙本不牙齿对理科没什么影响的。","beginTime":39520,"endTime":44560,"channelId":0},{"speakerRole":"agent","index":24,"text":"呃，","beginTime":44900,"endTime":45103,"channelId":0},{"speakerRole":"agent","index":25,"text":"我车本现在已经还没还完呢，","beginTime":45103,"endTime":47541,"channelId":0},{"speakerRole":"agent","index":26,"text":"我得来来年七月份再还完吧。","beginTime":47541,"endTime":49980,"channelId":0},{"speakerRole":"agent","index":27,"text":"哦，","beginTime":49980,"endTime":50183,"channelId":0},{"speakerRole":"agent","index":28,"text":"等于你现在车的是抵押的状态，","beginTime":50183,"endTime":52825,"channelId":0},{"speakerRole":"agent","index":29,"text":"满意十岁我我车是贷款车没还完呢呃，","beginTime":52825,"endTime":56077,"channelId":0},{"speakerRole":"agent","index":30,"text":"还要有几个月吗？","beginTime":56077,"endTime":57500,"channelId":0},{"speakerRole":"agent","index":31,"text":"嗯，","beginTime":57800,"endTime":58133,"channelId":0},{"speakerRole":"agent","index":32,"text":"还有一年一年一年就是还有一年十四个月吧。","beginTime":58133,"endTime":64460,"channelId":0},{"speakerRole":"agent","index":33,"text":"哦那还挺久的嘛。","beginTime":64840,"endTime":66002,"channelId":0},{"speakerRole":"agent","index":34,"text":"那那那这种这种情况下我们做不了，","beginTime":66002,"endTime":68492,"channelId":0},{"speakerRole":"agent","index":35,"text":"需要你那边解押的时候，","beginTime":68492,"endTime":70152,"channelId":0},{"speakerRole":"agent","index":36,"text":"我们这边才可以做。","beginTime":70152,"endTime":71480,"channelId":0},{"speakerRole":"agent","index":37,"text":"嗯，","beginTime":71720,"endTime":71950,"channelId":0},{"speakerRole":"agent","index":38,"text":"那好嘞嗯哎好嘞好嘞，","beginTime":71950,"endTime":74020,"channelId":0},{"speakerRole":"agent","index":39,"text":"嗯好，","beginTime":74020,"endTime":74480,"channelId":0},{"speakerRole":"agent","index":40,"text":"拜拜。","beginTime":74480,"endTime":74940,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:43','2026-05-22 00:23:45','2026-05-22 00:23:39','2026-05-22 00:23:45','system','system','BATCH-20260522-207060',NULL),
