annelId":0},{"speakerRole":"agent","index":210,"text":"我看一下啊，","beginTime":574760,"endTime":575783,"channelId":0},{"speakerRole":"agent","index":211,"text":"我试一下我试一下，","beginTime":575783,"endTime":577420,"channelId":0},{"speakerRole":"agent","index":212,"text":"我看一下下啊嗯看一下像嗯。","beginTime":577940,"endTime":584800,"channelId":0},{"speakerRole":"agent","index":213,"text":"但是有没有怎么办？","beginTime":588880,"endTime":590680,"channelId":0},{"speakerRole":"agent","index":214,"text":"三四页没有的话，","beginTime":591120,"endTime":592722,"channelId":0},{"speakerRole":"agent","index":215,"text":"一个月是吧，","beginTime":592722,"endTime":593866,"channelId":0},{"speakerRole":"agent","index":216,"text":"你先把幼儿园三四页的话，","beginTime":593866,"endTime":596870,"channelId":0},{"speakerRole":"agent","index":217,"text":"就查一二年。","beginTime":596870,"endTime":597760,"channelId":0},{"speakerRole":"agent","index":218,"text":"嗯嗯，","beginTime":600500,"endTime":601025,"channelId":0},{"speakerRole":"agent","index":219,"text":"那先看一下嗯，","beginTime":601025,"endTime":604400,"channelId":0},{"speakerRole":"agent","index":220,"text":"好了就行了。","beginTime":604400,"endTime":605800,"channelId":0},{"speakerRole":"agent","index":221,"text":"微信再说，","beginTime":610540,"endTime":612440,"channelId":0},{"speakerRole":"agent","index":222,"text":"还有十多万没还期刚买的车吗？","beginTime":613280,"endTime":615520,"channelId":0},{"speakerRole":"agent","index":223,"text":"嗯嗯，","beginTime":617440,"endTime":618056,"channelId":0},{"speakerRole":"agent","index":224,"text":"我做生意贷款呢啊什么时间买的车呀，","beginTime":618056,"endTime":622984,"channelId":0},{"speakerRole":"agent","index":225,"text":"汽车嗯，","beginTime":622984,"endTime":624980,"channelId":0},{"speakerRole":"agent","index":226,"text":"一九年吧，","beginTime":625620,"endTime":626950,"channelId":0},{"speakerRole":"agent","index":227,"text":"二零年啊。","beginTime":626950,"endTime":628280,"channelId":0},{"speakerRole":"agent","index":228,"text":"我想听不到，","beginTime":632140,"endTime":633263,"channelId":0},{"speakerRole":"agen