76445,"endTime":76628,"channelId":0},{"speakerRole":"agent","index":37,"text":"绿绿您的那您那个绿本的话是在海南电路那边，","beginTime":76628,"endTime":80305,"channelId":0},{"speakerRole":"agent","index":38,"text":"还是在您自己手上的，","beginTime":80305,"endTime":81960,"channelId":0},{"speakerRole":"agent","index":39,"text":"哪个啊？","beginTime":82520,"endTime":83560,"channelId":0},{"speakerRole":"agent","index":40,"text":"呃，","beginTime":84020,"endTime":84230,"channelId":0},{"speakerRole":"agent","index":41,"text":"在厂家那边是吧？","beginTime":84230,"endTime":85700,"channelId":0},{"speakerRole":"agent","index":42,"text":"对，","beginTime":86320,"endTime":86591,"channelId":0},{"speakerRole":"agent","index":43,"text":"还在这里面啊。","beginTime":86591,"endTime":88220,"channelId":0},{"speakerRole":"agent","index":44,"text":"嗯那您这个目前的话可能还做不了，","beginTime":88740,"endTime":90937,"channelId":0},{"speakerRole":"agent","index":45,"text":"也就是我们这个贷款的话，","beginTime":90937,"endTime":92549,"channelId":0},{"speakerRole":"agent","index":46,"text":"是需要您这个绿本照片的。","beginTime":92549,"endTime":94160,"channelId":0},{"speakerRole":"agent","index":47,"text":"你有吗？","beginTime":94160,"endTime":94600,"channelId":0},{"speakerRole":"agent","index":48,"text":"我没问过他，","beginTime":96220,"endTime":97016,"channelId":0},{"speakerRole":"agent","index":49,"text":"我我可以问他拍照给你吗？","beginTime":97016,"endTime":98767,"channelId":0},{"speakerRole":"agent","index":50,"text":"怎么样？","beginTime":98767,"endTime":99245,"channelId":0},{"speakerRole":"agent","index":51,"text":"呃，","beginTime":99245,"endTime":99404,"channelId":0},{"speakerRole":"agent","index":52,"text":"拍照的话，","beginTime":99404,"endTime":100041,"channelId":0},{"speakerRole":"agent","index":53,"text":"那您这边那如果说您这边有照片的话，","beginTime":100041,"endTime":102588,"channelId":0},{"speakerRole":"agent","index":54,"text":"您在那个支付宝后台您上传，","beginTime":102588,"endTime":104498,"channelId":0},{"speakerRole":"agent","index":55,"text":"就是您点击那个去借钱的话，","beginTime":104498,"endTime":106409,"channelId":0},{"speakerRole":"agent","index":56,"text":"您按照它的流程，","beginTime":106409,"endTime":107523,"channelId":0},{"speakerRole":"agent","index":57,"text":"您上传一下哦。","beginTime":107523,"endTime":108962,"channelId":0},{"speakerRole":"agent","index":58,"text":"好好好好好，","beginTime":108962,"endTime":109673,"channelId":0},{"speakerRole":"agent","index":59,"text":"行，","beginTime":109673,"endTime":109815,"channelId":0},{"speakerRole":"agent","index":60,"text":"那您那您问一下，","beginTime":109815,"endTime":110811,"channelId":0},{"speakerRole":"agent","index":61,"text":"我这边直接给您添加一下。","beginTime":110811,"endTime":112375,"channelId":0},{"speakerRole":"agent","index":62,"text":"您您稍后通过一下，","beginTime":112375,"endTime":113513,"channelId":0},{"speakerRole":"agent","index":63,"text":"有问题的话，","beginTime":113513,"endTime":114224,"channelId":0},{"speakerRole":"agent","index":64,"text":"您随时那个微信上联系我就行了。","beginTime":114224,"endTime":116215,"channelId":0},{"speakerRole":"agent","index":65,"text":"好吧，","beginTime":116215,"endTime":116500,"channelId":0},{"speakerRole":"agent","index":66,"text":"好好啊，","beginTime":116740,"endTime":117835,"channelId":0},{"speakerRole":"agent","index":67,"text":"这个黄建是您的微信名称吗？","beginTime":117835,"endTime":119942,"channelId":0},{"speakerRole":"agent","index":68,"text":"对，","beginTime":119942,"endTime":120118,"channelId":0},{"speakerRole":"agent","index":69,"text":"哎，","beginTime":120118,"endTime":120294,"channelId":0},{"speakerRole":"agent","index":70,"text":"好嘞，","beginTime":120294,"endTime":120645,"channelId":0},{"speakerRole":"agent","index":71,"text":"我添加您了啊。","beginTime":120645,"endTime":121698,"channelId":0},{"speakerRole":"agent","index":72,"text":"您看一下您那个呃微信的聊天界面呢，","beginTime":121698,"endTime":124508,"channelId":0},{"speakerRole":"agent","index":73,"text":"它会有一个服务通知，","beginTime":124508,"endTime":126088,"channelId":0},{"speakerRole":"agent","index":74,"text":"好吧。","beginTime":126088,"endTime":126440,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:24:24','2026-05-22 00:24:26','2026-05-2