:0},{"speakerRole":"agent","index":17,"text":"是全呃，","beginTime":29468,"endTime":30131,"channelId":0},{"speakerRole":"agent","index":18,"text":"是全款车，","beginTime":30131,"endTime":31014,"channelId":0},{"speakerRole":"agent","index":19,"text":"那是可以办理的那您这辆车的行驶证和预本目前有没有在您身边呢？","beginTime":31014,"endTime":37420,"channelId":0},{"speakerRole":"agent","index":20,"text":"我手机上看就有吗？","beginTime":38440,"endTime":40033,"channelId":0},{"speakerRole":"agent","index":21,"text":"呃，","beginTime":40033,"endTime":40232,"channelId":0},{"speakerRole":"agent","index":22,"text":"那行，","beginTime":40232,"endTime":40630,"channelId":0},{"speakerRole":"agent","index":23,"text":"那可以直接在支付宝上面去提交车辆。","beginTime":40630,"endTime":43816,"channelId":0},{"speakerRole":"agent","index":24,"text":"您这笔资金的话，","beginTime":43816,"endTime":45210,"channelId":0},{"speakerRole":"agent","index":25,"text":"您是打算什么时候需要用吗？","beginTime":45210,"endTime":47600,"channelId":0},{"speakerRole":"agent","index":26,"text":"最好今天能啊，","beginTime":48800,"endTime":49830,"channelId":0},{"speakerRole":"agent","index":27,"text":"今天能放款的吗？","beginTime":49830,"endTime":51032,"channelId":0},{"speakerRole":"agent","index":28,"text":"今天可以啊，","beginTime":51032,"endTime":51891,"channelId":0},{"speakerRole":"agent","index":29,"text":"今天您把这些资料提交好了之后审核通过，","beginTime":51891,"endTime":54982,"channelId":0},{"speakerRole":"agent","index":30,"text":"然后就可以放款到账了啊。","beginTime":54982,"endTime":57288,"channelId":0},{"speakerRole":"agent","index":31,"text":"好好，","beginTime":57288,"endTime":57665,"channelId":0},{"speakerRole":"agent","index":32,"text":"哎，","beginTime":57665,"endTime":57853,"channelId":0},{"speakerRole":"agent","index":33,"text":"我加您一个微信吧，","beginTime":57853,"endTime":59360,"channelId":0},{"speakerRole":"agent","index":34,"text":"您的微信名称是叫共赢是吧？","beginTime":59360,"endTime":61620,"channelId":0},{"speakerRole":"agent","index":35,"text":"哎哎，","beginTime":62000,"endTime":62382,"channelId":0},{"speakerRole":"agent","index":36,"text":"您看一下您的微信页面上有没有一个橙色的服务通知喇叭啊，","beginTime":62382,"endTime":67775,"channelId":0},{"speakerRole":"agent","index":37,"text":"好好嗯，","beginTime":67775,"endTime":68361,"channelId":0},{"speakerRole":"agent","index":38,"text":"然后您长按识别就可以，","beginTime":68361,"endTime":70315,"channelId":0},{"speakerRole":"agent","index":39,"text":"然后把这些呃要求发给你哦。","beginTime":70315,"endTime":72660,"channelId":0},{"speakerRole":"agent","index":40,"text":"嗯嗯，","beginTime":73060,"endTime":73508,"channelId":0},{"speakerRole":"agent","index":41,"text":"好的，","beginTime":73508,"endTime":73956,"channelId":0},{"speakerRole":"agent","index":42,"text":"行，","beginTime":73956,"endTime":74180,"channelId":0},{"speakerRole":"agent","index":43,"text":"那我这边就暂时挂断哈。","beginTime":74180,"endTime":76420,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:33','2026-05-22 00:23:35','2026-05-22 00:23:31','2026-05-22 00:23:35','system','system','BATCH-20260522-207060',NULL),
(205595,'rec_127bf8540cf04a9fa17384a7','ext_d64192c88fe7435cbe3b0937cb0f5422','6a4a0b74-48eb-482a-9428-7b1e7a0904ed.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/e1d19ff225c8434b839798d9b2253a60.mp3',2,351,'mp3',353016,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":1080,"endTime":1349,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":1349,"endTime":1887,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问是刘先生吗？","beginTime":1887,"endTime":3770,"channelId":0},{"speakerRole":"agent","index":3,"text":"嗯，","beginTime":3770,"endTime":4040,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎刘哥您好，","beginTime":4280,"endTime":5066,"channelId":0},{"speakerRole":"agent","index":5,"text":"我这边是支付宝精选车贷的客户经理啊。","beginTime":5066,"endTime":7740,"channelId":0},{"speakerRole":"agent","index":6,"text":"呃您这边刚刚在我们支付宝上看到了，","beginTime":8340,"endTime":10706,"channelId":0},{"speakerRole":"agent","index":7,"text":"不是直接个车贷申请嘛，","beginTime":10706,"endTime":12186,"channelId":0},{"speakerRole":"agent","index":8,"text":"已经预审通过了啊，","beginTime":12186,"endTime":13369,"channelId":0},{"speakerRole":"agent","index":9,"text":"有个两万七千六的额度。","beginTime":13369,"endTime":14848,"channelId":0},{"speakerRole":"agent","index":10,"text":"这笔资金咱们今天可需要使用啊嗯他最少弄他最少要弄两万，","beginTime":14848,"endTime":22170,"channelId":0},{"speakerRole":"agent","index":11,"text":"我用不了那么多。","beginTime":22170,"endTime":23920,"channelId":0},{"speakerRole":"agent","index":12,"text":"那您资金需求是多少呀？","beginTime":24160,"endTime":26020,"channelId":0},{"speakerRole":"agent","index":13,"text":"我自己需求就大几千吧，","beginTime":26400,"endTime":29042,"channelId":0},{"speakerRole":"agent","index":14,"text":"一万左右哦哦。","beginTime":29042,"endTime":30744,"channelId":0},{"speakerRole":"agent","index":15,"text":"这边您可以就是提出来，","beginTime":30744,"endTime":32367,"channelId":0},{"speakerRole":"agent","index":16,"text":"然后后续您提前还款不就行了吗？","beginTime":32367,"endTime":34640,"channelId":0},{"speakerRole":"agent","index":17,"text":"他又不是说非得要固定三十六期之后再还你，","beginTime":35640,"endTime":38540,"channelId":0},{"speakerRole":"agent","index":18,"text":"你那个哪天资金全部滚动完，","beginTime":38540,"endTime":40373,"channelId":0},{"speakerRole":"agent","index":19,"text":"你给还进去不就行了吗？","beginTime":40373,"endTime":41900,"channelId":0},{"speakerRole":"agent","index":20,"text":"不用不用看，","beginTime":42660,"endTime":43580,"channelId":0},{"speakerRole":"agent","index":21,"text":"我看他那个利息太高了，","beginTime":43580,"endTime":45420,"channelId":0},{"speakerRole":"agent","index":22,"text":"利息您的资料都没提交上来，","beginTime":46400,"endTime":48238,"channelId":0},{"speakerRole":"agent","index":23,"text":"你的脑粒子都没出来呢，","beginTime":48238,"endTime":49769,"channelId":0},{"speakerRole":"agent","index":24,"text":"只有把资料提交上来之后，","beginTime":49769,"endTime":51454,"channelId":0},{"speakerRole":"agent","index":25,"text":"你的利息才会出来。","beginTime":51454,"endTime":52680,"channelId":0},{"speakerRole":"agent","index":26,"text":"我看见借两万多的五百多，","beginTime":53620,"endTime":56460,"channelId":0},{"speakerRole":"agent","index":27,"text":"这两万五百多。","beginTime":58100,"endTime":59440,"channelId":0},{"speakerRole":"agent","index":28,"text":"那个利息您把资料提交上来之后，","beginTime":62500,"endTime":64945,"channelId":0},{"speakerRole":"agent","index":29,"text":"利息可能会变的呀，","beginTime":64945,"endTime":66343,"channelId":0},{"speakerRole":"agent","index":30,"text":"因为这是初始额度，","beginTime":66343,"endTime":67741,"channelId":0},{"speakerRole":"agent","index":31,"text":"初始利息。","beginTime":67741,"endTime":68440,"channelId":0},{"speakerRole":"agent","index":32,"text":"您看您这边那个当前这个晋a零零呃x q u这个车子一个，","beginTime":72240,"endTime":77757,"channelId":0},{"speakerRole":"agent","index":33,"text":"你知道吧？","beginTime":77757,"endTime":78640,"channelId":0},{"speakerRole":"agent","index":34,"text":"嗯，","beginTime":78900,"endTime":79135,"channelId":0},{"speakerRole":"agent","index":35,"text":"咱们是城管多长时间可以啊？","beginTime":79135,"endTime":83015,"channelId":0},{"speakerRole":"agent","index":36,"text":"咱们是全款车还是按揭车啊？","beginTime":83015,"endTime":86080,"channelId":0},{"speakerRole":"agent","index":37,"text":"按揭我已经还完了哦，","beginTime":87960,"endTime":90427,"channelId":0},{"speakerRole":"agent","index":38,"text":"那就是存款人吗？","beginTime":90427,"endTime":92345,"channelId":0},{"speakerRole":"agent","index":39,"text":"嗯嗯，","beginTime":92345,"endTime":93132,"channelId":0},{"speakerRole":"agent","index":40,"text":"可以的，","beginTime":93132,"endTime":93648,"channelId":0},{"speakerRole":"agent","index":41,"text":"这边是符合我们的办理条件的呀。","beginTime":93648,"endTime":96060,"channelId":0},{"speakerRole":"agent","index":42,"text":"嗯最近我看他的他的力气太高了，","beginTime":97060,"endTime":101637,"channelId":0},{"speakerRole":"agent","index":43,"text":"我我想的意思是这样的，","beginTime":101637,"endTime":104330,"channelId":0},{"speakerRole":"agent","index":44,"text":"您的那个资料没有提交上来，","beginTime":104330,"endTime":106877,"channelId":0},{"speakerRole":"agent","index":45,"text":"你的电脑利率才还没出来。","beginTime":106877,"endTime":109211,"channelId":0},{"speakerRole":"agent","index":46,"text":"我们正常的一万块钱到每个月的话，","beginTime":109211,"endTime":112395,"channelId":0},{"speakerRole":"agent","index":47,"text":"是呃，","beginTime":112395,"endTime":112819,"channelId":0},{"speakerRole":"agent","index":48,"text":"月通过费率大概八十三到一百一十四之间哦，","beginTime":112819,"endTime":118105,"channelId":0},{"speakerRole":"agent","index":49,"text":"那那这个这个还可以接受，","beginTime":118105,"endTime":120360,"channelId":0},{"speakerRole":"agent","index":50,"text":"反正八十三到一百一十四之间可能不会高于一百一十。","beginTime":120360,"endTime":125075,"channelId":0},{"speakerRole":"agent","index":51,"text":"但是但是呢也估计于八十三就是这样的一个情况。","beginTime":125075,"endTime":129380,"channelId":0},{"speakerRole":"agent","index":52,"text":"您这边可以考虑嘛，","beginTime":132200,"endTime":133386,"channelId":0},{"speakerRole":"agent","index":53,"text":"这边不是说我这边给您打电话，","beginTime":133386,"endTime":135313,"channelId":0},{"speakerRole":"agent","index":54,"text":"不是说让您就是现在就给借出来，","beginTime":135313,"endTime":137389,"channelId":0},{"speakerRole":"agent","index":55,"text":"您考虑吗？","beginTime":137389,"endTime":137982,"channelId":0},{"speakerRole":"agent","index":56,"text":"您把我的那个截微信加上，","beginTime":137982,"endTime":139613,"channelId":0},{"speakerRole":"agent","index":57,"text":"后续呢，","beginTime":139613,"endTime":140058,"channelId":0},{"speakerRole":"agent","index":58,"text":"您那个什么时候需要您跟我说，","beginTime":140058,"endTime":141986,"channelId":0},{"speakerRole":"agent","index":59,"text":"我这边协助您放款了就可以了。","beginTime":141986,"endTime":143913,"channelId":0},{"speakerRole":"agent","index":60,"text":"我这边是之方，","beginTime":143913,"endTime":144803,"channelId":0},{"speakerRole":"agent","index":61,"text":"好吧，","beginTime":144803,"endTime":145100,"channelId":0},{"speakerRole":"agent","index":62,"text":"他这个就没有什么填填资料之类的。","beginTime":146020,"endTime":148927,"channelId":0},{"speakerRole":"agent","index":63,"text":"有不是我跟你讲啊，","beginTime":148927,"endTime":150478,"channelId":0},{"speakerRole":"agent","index":64,"text":"您当前不是一个两万七千六楼度嘛，","beginTime":150478,"endTime":153385,"channelId":0},{"speakerRole":"agent","index":65,"text":"下面有个去借钱，","beginTime":153385,"endTime":154742,"channelId":0},{"speakerRole":"agent","index":66,"text":"你看到了吧，","beginTime":154742,"endTime":155711,"channelId":0},{"speakerRole":"agent","index":67,"text":"三个字嗯嗯嗯，","beginTime":155711,"endTime":156874,"channelId":0},{"speakerRole":"agent","index":68,"text":"三个字点击进去，","beginTime":156874,"endTime":158231,"channelId":0},{"speakerRole":"agent","index":69,"text":"不是说写码就到您账户去去借钱，","beginTime":158231,"endTime":160945,"channelId":0},{"speakerRole":"agent","index":70,"text":"然后点进去。","beginTime":160945,"endTime":161914,"channelId":0},{"speakerRole":"agent","index":71,"text":"第一步呢需要您绑个银行卡，","beginTime":161914,"endTime":164240,"channelId":0},{"speakerRole":"agent","index":72,"text":"我们放款是放到银行卡里面的，","beginTime":164240,"endTime":166760,"channelId":0},{"speakerRole":"agent","index":73,"text":"我这边直接已经有银行卡了。","beginTime":167000,"endTime":169860,"channelId":0},{"speakerRole":"agent","index":74,"text":"嗯，","beginTime":170100,"endTime":170251,"channelId":0},{"speakerRole":"agent","index":75,"text":"不是，","beginTime":170251,"endTime":170554,"channelId":0},{"speakerRole":"agent","index":76,"text":"您那边需要绑定，","beginTime":170554,"endTime":171615,"channelId":0},{"speakerRole":"agent","index":77,"text":"您不是说支付宝上绑定的银行卡，","beginTime":171615,"endTime":173738,"channelId":0},{"speakerRole":"agent","index":78,"text":"就是那个银行卡。","beginTime":173738,"endTime":174799,"channelId":0},{"speakerRole":"agent","index":79,"text":"我们需要您绑定一个银行卡，","beginTime":174799,"endTime":176618,"channelId":0},{"speakerRole":"agent","index":80,"text":"我们需要您绑定那个呃放款是放到绑定的那个银行卡里面的。","beginTime":176618,"endTime":180560,"channelId":0},{"speakerRole":"agent","index":81,"text":"返回来写好之后，","beginTime":180840,"endTime":182291,"channelId":0},{"speakerRole":"agent","index":82,"text":"然后再填写一下简单的个人资料，","beginTime":182291,"endTime":185195,"channelId":0},{"speakerRole":"agent","index":83,"text":"然后上传一下日本定行驶证的照片，","beginTime":185195,"endTime":188307,"channelId":0},{"speakerRole":"agent","index":84,"text":"提交到他这就就可以了。","beginTime":188307,"endTime":190381,"channelId":0},{"speakerRole":"agent","index":85,"text":"他这就他这就没有，","beginTime":190381,"endTime":192040,"channelId":0},{"speakerRole":"agent","index":86,"text":"他直接去点那个去借钱，","beginTime":192040,"endTime":194115,"channelId":0},{"speakerRole":"agent","index":87,"text":"直接就是什么借多久，","beginTime":194115,"endTime":195981,"channelId":0},{"speakerRole":"agent","index":88,"text":"怎么还收款账户，","beginTime":195981,"endTime":197433,"channelId":0},{"speakerRole":"agent","index":89,"text":"只有这三个。","beginTime":197433,"endTime":198470,"channelId":0},{"speakerRole":"agent","index":90,"text":"对呀，","beginTime":198470,"endTime":198885,"channelId":0},{"speakerRole":"agent","index":91,"text":"收款账户就是银行卡呀。","beginTime":198885,"endTime":200960,"channelId":0},{"speakerRole":"agent","index":92,"text":"嗯我这个已经有了这个银行卡了呀，","beginTime":201200,"endTime":203804,"channelId":0},{"speakerRole":"agent","index":93,"text":"嗯然后银行卡这边下一步的话，","beginTime":203804,"endTime":206062,"channelId":0},{"speakerRole":"agent","index":94,"text":"就要您直接那个写个人资料了啊。","beginTime":206062,"endTime":209470,"channelId":0},{"speakerRole":"agent","index":95,"text":"嗯你银行绑定了之后，","beginTime":209470,"endTime":212160,"channelId":0},{"speakerRole":"agent","index":96,"text":"下面再往下点的话，","beginTime":212160,"endTime":213600,"channelId":0},{"speakerRole":"agent","index":97,"text":"就是让你提交资料，","beginTime":213600,"endTime":215040,"channelId":0},{"speakerRole":"agent","index":98,"text":"然后那个没有，","beginTime":215040,"endTime":216120,"channelId":0},{"speakerRole":"agent","index":99,"text":"下边就下边就是确认，","beginTime":216120,"endTime":217740,"channelId":0},{"speakerRole":"agent","index":100,"text":"确认了，","beginTime":217740,"endTime":218280,"channelId":0},{"speakerRole":"agent","index":101,"text":"确认之后再填写资料呀。","beginTime":218280,"endTime":220080,"channelId":0},{"speakerRole":"agent","index":102,"text":"他一步一步来呀，","beginTime":220080,"endTime":221340,"channelId":0},{"speakerRole":"agent","index":103,"text":"第一步是绑银行卡呀，","beginTime":221340,"endTime":222960,"channelId":0},{"speakerRole":"agent","index":104,"text":"然后再填写资料，","beginTime":222960,"endTime":224220,"channelId":0},{"speakerRole":"agent","index":105,"text":"然后再上传日本照片呀嗯啊啊啊出来了，","beginTime":224220,"endTime":228200,"channelId":0},{"speakerRole":"agent","index":106,"text":"你放心，","beginTime":228200,"endTime":228860,"channelId":0},{"speakerRole":"agent","index":107,"text":"不会移步到您那个账户了，","beginTime":228860,"endTime":231280,"channelId":0},{"speakerRole":"agent","index":108,"text":"那肯定是你的。","beginTime":231280,"endTime":232600,"channelId":0},{"speakerRole":"agent","index":109,"text":"而且我那机动机动车的那个登记证不在登记站，","beginTime":232600,"endTime":237000,"channelId":0},{"speakerRole":"agent","index":110,"text":"在在哪里啊，","beginTime":237000,"endTime":238428,"channelId":0},{"speakerRole":"agent","index":111,"text":"在家里，","beginTime":238428,"endTime":239154,"channelId":0},{"speakerRole":"agent","index":112,"text":"在老家放着呢。","beginTime":239154,"endTime":240607,"channelId":0},{"speakerRole":"agent","index":113,"text":"那您在外地呀嗯你你家有多远啊？","beginTime":240607,"endTime":245100,"channelId":0},{"speakerRole":"agent","index":114,"text":"我家在山西，","beginTime":245860,"endTime":247096,"channelId":0},{"speakerRole":"agent","index":115,"text":"我现在在河北，","beginTime":247096,"endTime":248580,"channelId":0},{"speakerRole":"agent","index":116,"text":"这个还挺远的，","beginTime":249760,"endTime":251005,"channelId":0},{"speakerRole":"agent","index":117,"text":"是吧？","beginTime":251005,"endTime":251420,"channelId":0},{"speakerRole":"agent","index":118,"text":"嗯，","beginTime":251880,"endTime":252066,"channelId":0},{"speakerRole":"agent","index":119,"text":"那也没关系，","beginTime":252066,"endTime":253001,"channelId":0},{"speakerRole":"agent","index":120,"text":"您可以去那个您当那个您边上的车管所去补办一个嘛。","beginTime":253001,"endTime":257300,"channelId":0},{"speakerRole":"agent","index":121,"text":"那么我现在三个月了，","beginTime":260140,"endTime":262080,"channelId":0},{"speakerRole":"agent","index":122,"text":"我现在没那个时间啊，","beginTime":262360,"endTime":264400,"channelId":0},{"speakerRole":"agent","index":123,"text":"没时间。","beginTime":264740,"endTime":265840,"channelId":0},{"speakerRole":"agent","index":124,"text":"对，","beginTime":266520,"endTime":266766,"channelId":0},{"speakerRole":"agent","index":125,"text":"我就看试一下往上行不行哦，","beginTime":266766,"endTime":270400,"channelId":0},{"speakerRole":"agent","index":126,"text":"他那个您您您您现在有没有那个您之前那个绿本照片，","beginTime":270400,"endTime":275466,"channelId":0},{"speakerRole":"agent","index":127,"text":"有没有啊？","beginTime":275466,"endTime":276347,"channelId":0},{"speakerRole":"agent","index":128,"text":"那个呃拍过照片，","beginTime":276347,"endTime":277888,"channelId":0},{"speakerRole":"agent","index":129,"text":"那个陈佳林那个没有没有，","beginTime":277888,"endTime":280311,"channelId":0},{"speakerRole":"agent","index":130,"text":"那那那会儿那都早已经删完了。","beginTime":280311,"endTime":283174,"channelId":0},{"speakerRole":"agent","index":131,"text":"那个那个还完，","beginTime":283174,"endTime":284496,"channelId":0},{"speakerRole":"agent","index":132,"text":"我还完那个分期的时候，","beginTime":284496,"endTime":286698,"channelId":0},{"speakerRole":"agent","index":133,"text":"已经删了，","beginTime":286698,"endTime":287580,"channelId":0},{"speakerRole":"agent","index":134,"text":"全部都删掉了，","beginTime":287820,"endTime":288843,"channelId":0},{"speakerRole":"agent","index":135,"text":"是吧？","beginTime":288843,"endTime":289185,"channelId":0},{"speakerRole":"agent","index":136,"text":"那你家里面有没有在家里面，","beginTime":289185,"endTime":291232,"channelId":0},{"speakerRole":"agent","index":137,"text":"让他让家里人给你拍一下呗。","beginTime":291232,"endTime":293280,"channelId":0},{"speakerRole":"agent","index":138,"text":"家里没人，","beginTime":295340,"endTime":296680,"channelId":0},{"speakerRole":"agent","index":139,"text":"都在外地啊，","beginTime":297480,"endTime":299563,"channelId":0},{"speakerRole":"agent","index":140,"text":"嗯那只能就是说您去补办一个，","beginTime":299563,"endTime":304140,"channelId":0},{"speakerRole":"agent","index":141,"text":"他补办很快的。","beginTime":304380,"endTime":305800,"channelId":0},{"speakerRole":"agent","index":142,"text":"也也也也就是十块钱的工本费，","beginTime":306700,"endTime":309534,"channelId":0},{"speakerRole":"agent","index":143,"text":"然后时间也很快。","beginTime":309534,"endTime":311060,"channelId":0},{"speakerRole":"agent","index":144,"text":"算了，","beginTime":319120,"endTime":319605,"channelId":0},{"speakerRole":"agent","index":145,"text":"我完了再说吧。","beginTime":319605,"endTime":321060,"channelId":0},{"speakerRole":"agent","index":146,"text":"嗯没关系，","beginTime":321540,"endTime":322068,"channelId":0},{"speakerRole":"agent","index":147,"text":"您这边就是把我微信加一下嘛，","beginTime":322068,"endTime":323784,"channelId":0},{"speakerRole":"agent","index":148,"text":"后续有什么需求，","beginTime":323784,"endTime":324708,"channelId":0},{"speakerRole":"agent","index":149,"text":"咱们直接微信上跟我说就可以了。","beginTime":324708,"endTime":326556,"channelId":0},{"speakerRole":"agent","index":150,"text":"好吧，","beginTime":326556,"endTime":326820,"channelId":0},{"speakerRole":"agent","index":151,"text":"要要跟没关系好吧，","beginTime":327060,"endTime":328596,"channelId":0},{"speakerRole":"agent","index":152,"text":"那个微信在哪了？","beginTime":328596,"endTime":329941,"channelId":0},{"speakerRole":"agent","index":153,"text":"微信您在那个微信首页上面，","beginTime":329941,"endTime":332246,"channelId":0},{"speakerRole":"agent","index":154,"text":"您看一下有个呃服务通知，","beginTime":332246,"endTime":334358,"channelId":0},{"speakerRole":"agent","index":155,"text":"有个黄色的呀，","beginTime":334358,"endTime":335511,"channelId":0},{"speakerRole":"agent","index":156,"text":"服务通知有没有看到。","beginTime":335511,"endTime":337240,"channelId":0},{"speakerRole":"agent","index":157,"text":"嗯，","beginTime":337480,"endTime":337654,"channelId":0},{"speakerRole":"agent","index":158,"text":"行，","beginTime":337654,"endTime":337829,"channelId":0},{"speakerRole":"agent","index":159,"text":"我到时候等一会儿看一下吧。","beginTime":337829,"endTime":339923,"channelId":0},{"speakerRole":"agent","index":160,"text":"嗯有好的服务通知，","beginTime":339923,"endTime":341320,"channelId":0},{"speakerRole":"agent","index":161,"text":"然后您点击进去呃，","beginTime":341320,"endTime":342717,"channelId":0},{"speakerRole":"agent","index":162,"text":"长按一两秒就可以通过了，","beginTime":342717,"endTime":344637,"channelId":0},{"speakerRole":"agent","index":163,"text":"直接通过好吧。","beginTime":344637,"endTime":345684,"channelId":0},{"speakerRole":"agent","index":164,"text":"嗯，","beginTime":345684,"endTime":345859,"channelId":0},{"speakerRole":"agent","index":165,"text":"行，","beginTime":345859,"endTime":346033,"channelId":0},{"speakerRole":"agent","index":166,"text":"我到时候看一下啊。","beginTime":346033,"endTime":347430,"channelId":0},{"speakerRole":"agent","index":167,"text":"嗯，","beginTime":347430,"endTime":347604,"channelId":0},{"speakerRole":"agent","index":168,"text":"好的好的，","beginTime":347604,"endTime":348303,"channelId":0},{"speakerRole":"agent","index":169,"text":"那就不打扰您了啊。","beginTime":348303,"endTime":349699,"channelId":0},{"speakerRole":"agent","index":170,"text":"嗯嗯嗯，","beginTime":349699,"endTime":350223,"channelId":0},{"speakerRole":"agent","index":171,"text":"好，","beginTime":350223,"endTime":350398,"channelId":0},{"speakerRole":"agent","index":172,"text":"感谢，","beginTime":350398,"endTime":350747,"channelId":0},{"speakerRole":"agent","index":173,"text":"再见啊，","beginTime":350747,"endTime":351270,"channelId":0},{"speakerRole":"agent","index":174,"text":"拜拜。","beginTime":351270,"endTime":351620,"channelId":0}]}',80,NULL,NULL,0,0,2,'2026-05-22 00:23:36','2026-05-22 00:23:39','2026-05-22 00:23:33','2026-05-22 00:23:39','system','system','BATCH-20260522-207060',NULL),
(205596,'rec_e74b54b14096448e9c4f54e9','ext_850594a3d83e4b52b1460f9686637ea0','6f727acb-2aa4-414c-950e-6864f9b6373e.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/0dcf1630e10d4ef5b9791737237e137c.mp3',2,165,'mp3',166752,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":1180,"endTime":1401,"channelId":0},{"speakerRole":"agent","index":1,"text":"你哎，","beginTime":1401,"endTime":1845,"channelId":0},{"speakerRole":"agent","index":2,"text":"徐先生，","beginTime":1845,"endTime":2511,"channelId":0},{"speakerRole":"agent","index":3,"text":"你那个没有通过一下我的微信呢，","beginTime":2511,"endTime":5616,"channelId":0},{"speakerRole":"agent","index":4,"text":"那我我你按按键，","beginTime":5616,"endTime":7169,"channelId":0},{"speakerRole":"agent","index":5,"text":"我按按那个喇叭的，","beginTime":7169,"endTime":8944,"channelId":0},{"speakerRole":"agent","index":6,"text":"你按了没有啊，","beginTime":8944,"endTime":10275,"channelId":0},{"speakerRole":"agent","index":7,"text":"你这按你这样。","beginTime":10275,"endTime":11606,"channelId":0},{"speakerRole":"agent","index":8,"text":"我跟你说的，","beginTime":11606,"endTime":12715,"channelId":0},{"speakerRole":"agent","index":9,"text":"你加吧，","beginTime":12715,"endTime":13381,"channelId":0},{"speakerRole":"agent","index":10,"text":"你那个微信打开之后啊，","beginTime":13381,"endTime":15599,"channelId":0},{"speakerRole":"agent","index":11,"text":"右上角不是有个小加号吗？","beginTime":15599,"endTime":18040,"channelId":0},{"speakerRole":"agent","index":12,"text":"小加号您点一下添加朋友，","beginTime":18660,"endTime":21520,"channelId":0},{"speakerRole":"agent","index":13,"text":"然后有一个添加企业微信，","beginTime":21920,"endTime":24376,"channelId":0},{"speakerRole":"agent","index":14,"text":"联系人，","beginTime":24376,"endTime":25046,"channelId":0},{"speakerRole":"agent","index":15,"text":"看到了吗？","beginTime":25046,"endTime":25940,"channelId":0},{"speakerRole":"agent","index":16,"text":"添加朋友，","beginTime":28420,"endTime":29570,"channelId":0},{"speakerRole":"agent","index":17,"text":"添加企业微信，","beginTime":29570,"endTime":31296,"channelId":0},{"speakerRole":"agent","index":18,"text":"联系人看到了吗？","beginTime":31296,"endTime":34196,"channelId":0},{"speakerRole":"agent","index":19,"text":"嗯嗯嗯，","beginTime":34196,"endTime":34884,"channelId":0},{"speakerRole":"agent","index":20,"text":"然后我跟您说号码，","beginTime":34884,"endTime":36717,"channelId":0},{"speakerRole":"agent","index":21,"text":"您在这里输入幺八五幺八五六零二六二零二二九幺二六。","beginTime":36717,"endTime":46240,"channelId":0},{"speakerRole":"agent","index":22,"text":"有啊，","beginTime":46980,"endTime":48460,"channelId":0},{"speakerRole":"agent","index":23,"text":"嗯幺八五六零二六九幺二六，","beginTime":50080,"endTime":52765,"channelId":0},{"speakerRole":"agent","index":24,"text":"我叫张荣，","beginTime":52765,"endTime":53660,"channelId":0},{"speakerRole":"agent","index":25,"text":"看到了是吧？","beginTime":54240,"endTime":55520,"channelId":0},{"speakerRole":"agent","index":26,"text":"你好你好。","beginTime":56200,"endTime":57260,"channelId":0},{"speakerRole":"agent","index":27,"text":"嗯嗯，","beginTime":60000,"endTime":61108,"channelId":0},{"speakerRole":"agent","index":28,"text":"你加我，","beginTime":61108,"endTime":61914,"channelId":0},{"speakerRole":"agent","index":29,"text":"我现在我现在就能看到。","beginTime":61914,"endTime":64600,"channelId":0},{"speakerRole":"agent","index":30,"text":"好了，","beginTime":68520,"endTime":68949,"channelId":0},{"speakerRole":"agent","index":31,"text":"我看到了。","beginTime":68949,"endTime":69808,"channelId":0},{"speakerRole":"agent","index":32,"text":"还有就是您刚才说的那个解押的问题啊，","beginTime":69808,"endTime":73460,"channelId":0},{"speakerRole":"agent","index":33,"text":"不用非得回广西啊，","beginTime":73460,"endTime":75178,"channelId":0},{"speakerRole":"agent","index":34,"text":"就在广东任何一个车管所都是可以办解押的哦。","beginTime":75178,"endTime":80601,"channelId":0},{"speakerRole":"agent","index":35,"text":"您现在的问题就是我给您发一下，","beginTime":80601,"endTime":83429,"channelId":0},{"speakerRole":"agent","index":36,"text":"因为咱拍照那个大本啊，","beginTime":83429,"endTime":85448,"channelId":0},{"speakerRole":"agent","index":37,"text":"还有那个行驶证啊，","beginTime":85448,"endTime":87063,"channelId":0},{"speakerRole":"agent","index":38,"text":"他是要按照要求的，","beginTime":87063,"endTime":88679,"channelId":0},{"speakerRole":"agent","index":39,"text":"我给您发过去。","beginTime":88679,"endTime":89891,"channelId":0},{"speakerRole":"agent","index":40,"text":"您拍的时候哈，","beginTime":89891,"endTime":91102,"channelId":0},{"speakerRole":"agent","index":41,"text":"四个角啊都要拍上，","beginTime":91102,"endTime":92718,"channelId":0},{"speakerRole":"agent","index":42,"text":"拍照的时候不要有感光点，","beginTime":92718,"endTime":94939,"channelId":0},{"speakerRole":"agent","index":43,"text":"尤其是右上角的那个那个条形码要拍清楚了，","beginTime":94939,"endTime":98776,"channelId":0},{"speakerRole":"agent","index":44,"text":"因为要扫描。","beginTime":98776,"endTime":99786,"channelId":0},{"speakerRole":"agent","index":45,"text":"呃，","beginTime":99786,"endTime":99988,"channelId":0},{"speakerRole":"agent","index":46,"text":"第二一个呢就是嗯在这个填写您的基本信息的时候啊，","beginTime":99988,"endTime":104632,"channelId":0},{"speakerRole":"agent","index":47,"text":"你如果是说呃，","beginTime":104632,"endTime":105844,"channelId":0},{"speakerRole":"agent","index":48,"text":"已经结婚了，","beginTime":105844,"endTime":106853,"channelId":0},{"speakerRole":"agent","index":49,"text":"你对象的这个电话什么的都要填上。","beginTime":106853,"endTime":109883,"channelId":0},{"speakerRole":"agent","index":50,"text":"但是我们不会给他打，","beginTime":109883,"endTime":111700,"channelId":0},{"speakerRole":"agent","index":51,"text":"就给您本人打个还款电话就可以了。","beginTime":111700,"endTime":114729,"channelId":0},{"speakerRole":"agent","index":52,"text":"反正很简单，","beginTime":114729,"endTime":115739,"channelId":0},{"speakerRole":"agent","index":53,"text":"我给您发那个微信上，","beginTime":115739,"endTime":117556,"channelId":0},{"speakerRole":"agent","index":54,"text":"您看一下打电话。","beginTime":117556,"endTime":118970,"channelId":0},{"speakerRole":"agent","index":55,"text":"如果如果您等价有什么操作，","beginTime":118970,"endTime":121507,"channelId":0},{"speakerRole":"agent","index":56,"text":"没有，","beginTime":121507,"endTime":121938,"channelId":0},{"speakerRole":"agent","index":57,"text":"不会不会，","beginTime":121938,"endTime":122799,"channelId":0},{"speakerRole":"agent","index":58,"text":"因为你得您自己得签字，","beginTime":122799,"endTime":124953,"channelId":0},{"speakerRole":"agent","index":59,"text":"你得同意了之后，","beginTime":124953,"endTime":126461,"channelId":0},{"speakerRole":"agent","index":60,"text":"您邮寄到本，","beginTime":126461,"endTime":127537,"channelId":0},{"speakerRole":"agent","index":61,"text":"我们才会给您去放款的。","beginTime":127537,"endTime":129691,"channelId":0},{"speakerRole":"agent","index":62,"text":"你现在那个大本你不还没解押吗？","beginTime":129691,"endTime":132706,"channelId":0},{"speakerRole":"agent","index":63,"text":"那这个肯定得一次解完押，","beginTime":132706,"endTime":135075,"channelId":0},{"speakerRole":"agent","index":64,"text":"你回来之后，","beginTime":135075,"endTime":136152,"channelId":0},{"speakerRole":"agent","index":65,"text":"我们这个就是顺丰小哥上门就给您取件显示。","beginTime":136152,"endTime":140244,"channelId":0},{"speakerRole":"agent","index":66,"text":"揽收了之后，","beginTime":140244,"endTime":141321,"channelId":0},{"speakerRole":"agent","index":67,"text":"我们才会给您放款的。","beginTime":141321,"endTime":143260,"channelId":0},{"speakerRole":"agent","index":68,"text":"我们是放款方，","beginTime":143700,"endTime":145012,"channelId":0},{"speakerRole":"agent","index":69,"text":"我们这个钱给到你，","beginTime":145012,"endTime":146761,"channelId":0},{"speakerRole":"agent","index":70,"text":"我们比你更担心，","beginTime":146761,"endTime":148292,"channelId":0},{"speakerRole":"agent","index":71,"text":"你知道吗？","beginTime":148292,"endTime":149166,"channelId":0},{"speakerRole":"agent","index":72,"text":"我不会有什么套路的，","beginTime":149166,"endTime":151134,"channelId":0},{"speakerRole":"agent","index":73,"text":"都是支付宝上的，","beginTime":151134,"endTime":152665,"channelId":0},{"speakerRole":"agent","index":74,"text":"都是合规合法的，","beginTime":152665,"endTime":154196,"channelId":0},{"speakerRole":"agent","index":75,"text":"这个是不会乱操作的，","beginTime":154196,"endTime":156164,"channelId":0},{"speakerRole":"agent","index":76,"text":"您放心就行哈。","beginTime":156164,"endTime":157476,"channelId":0},{"speakerRole":"agent","index":77,"text":"行，","beginTime":157476,"endTime":157694,"channelId":0},{"speakerRole":"agent","index":78,"text":"我从微信给您发一下哈，","beginTime":157694,"endTime":159881,"channelId":0},{"speakerRole":"agent","index":79,"text":"您看看哪里不明白，","beginTime":159881,"endTime":161630,"channelId":0},{"speakerRole":"agent","index":80,"text":"您随时问我就行哈。","beginTime":161630,"endTime":163380,"channelId":0},{"speakerRole":"agent","index":81,"text":"嗯好嘞，","beginTime":163800,"endTime":164856,"channelId":0},{"speakerRole":"agent","index":82,"text":"再见。","beginTime":164856,"endTime":165560,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:38','2026-05-22 00:23:42','2026-05-22 00:23:34','2026-05-22 00:23:42','system','system','BATCH-20260522-207060',NULL),
