(205603,'rec_ba45e1c0f5f642a898bd911e','ext_bc08f827bb9f4465a3a2209918179c46','41209fed-1712-4a68-92df-bcd3c10a084d.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/df9f4980e7f844c49a6cc18e94bfc502.mp3',2,117,'mp3',119520,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":4840,"endTime":5116,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":5116,"endTime":5670,"channelId":0},{"speakerRole":"agent","index":2,"text":"王先生。","beginTime":5670,"endTime":6500,"channelId":0},{"speakerRole":"agent","index":3,"text":"嗯，","beginTime":6840,"endTime":7560,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎你好，","beginTime":7800,"endTime":8367,"channelId":0},{"speakerRole":"agent","index":5,"text":"这边是支付宝理想车贷的客服经理。","beginTime":8367,"endTime":11203,"channelId":0},{"speakerRole":"agent","index":6,"text":"然后你不是这个月九号在支付平宝平台申请的那个车主在吗？","beginTime":11203,"endTime":16120,"channelId":0},{"speakerRole":"agent","index":7,"text":"额度有四万四千三，","beginTime":16380,"endTime":17854,"channelId":0},{"speakerRole":"agent","index":8,"text":"你手机上面也是能看到的。","beginTime":17854,"endTime":19881,"channelId":0},{"speakerRole":"agent","index":9,"text":"然后这边看到您一直没有提到是有什么顾虑和疑问吗？","beginTime":19881,"endTime":24120,"channelId":0},{"speakerRole":"agent","index":10,"text":"这需要什么时改进啊啊，","beginTime":25560,"endTime":28516,"channelId":0},{"speakerRole":"agent","index":11,"text":"我没听清楚说你们这个提出来嗯，","beginTime":28516,"endTime":33554,"channelId":0},{"speakerRole":"agent","index":12,"text":"还要不要说是就是你这个车主在吗？","beginTime":33554,"endTime":37287,"channelId":0},{"speakerRole":"agent","index":13,"text":"你现在的资金还需要吗？","beginTime":37287,"endTime":39229,"channelId":0},{"speakerRole":"agent","index":14,"text":"有解决掉吗？","beginTime":39229,"endTime":40200,"channelId":0},{"speakerRole":"agent","index":15,"text":"还好吧，","beginTime":41140,"endTime":42200,"channelId":0},{"speakerRole":"agent","index":16,"text":"对吧？","beginTime":42440