nt","index":17,"text":"呃，","beginTime":28829,"endTime":29019,"channelId":0},{"speakerRole":"agent","index":18,"text":"咱们这边呢，","beginTime":29019,"endTime":29968,"channelId":0},{"speakerRole":"agent","index":19,"text":"现在您看到的一个利息呢，","beginTime":29968,"endTime":32056,"channelId":0},{"speakerRole":"agent","index":20,"text":"不是您的一个催收利息。","beginTime":32056,"endTime":33954,"channelId":0},{"speakerRole":"agent","index":21,"text":"哥，","beginTime":33954,"endTime":34144,"channelId":0},{"speakerRole":"agent","index":22,"text":"然后咱们这边呢，","beginTime":34144,"endTime":35472,"channelId":0},{"speakerRole":"agent","index":23,"text":"它最近呢是有那个降息的政策的。","beginTime":35472,"endTime":38130,"channelId":0},{"speakerRole":"agent","index":24,"text":"哥，","beginTime":38130,"endTime":38320,"channelId":0},{"speakerRole":"agent","index":25,"text":"您刚才看到你的，","beginTime":39240,"endTime":40720,"channelId":0},{"speakerRole":"agent","index":26,"text":"嗯，","beginTime":41220,"endTime":41568,"channelId":0},{"speakerRole":"agent","index":27,"text":"咱们这边最低的话，","beginTime":41568,"endTime":44352,"channelId":0},{"speakerRole":"agent","index":28,"text":"呃，","beginTime":44352,"endTime":44700,"channelId":0},{"speakerRole":"agent","index":29,"text":"最高的话可以降到四个点。","beginTime":44940,"endTime":47720,"channelId":0},{"speakerRole":"agent","index":30,"text":"现在目前然后您那个您您看到的那个不是您的一个最终利息的，","beginTime":48140,"endTime":55160,"channelId":0},{"speakerRole":"agent","index":31,"text":"那个只是一个参考。","beginTime":55560,"endTime":56869,"channelId":0},{"speakerRole":"agent","index":32,"text":"对，","beginTime":56869,"endTime":57033,"channelId":0},{"speakerRole":"agent","index":33,"text":"您您这边，","beginTime":57033,"endTime":57688,"channelId":0},{"speakerRole":"agent","index":34,"text":"因为您这边还没提交您的资料吗？","beginTime":57688,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":35,"text":"所以呃您这边要提交的资料过后，","beginTime":60100,"endTime":62394,"channelId":0},{"speakerRole":"agent","index":36,"text":"到我们这边人审了，","beginTime":62394,"endTime":63705,