(205617,'rec_3160b2b2a23c4923ad0d98a2','ext_05bc84df6aae40c2997fb9bcfedb9d62','4a42cb10-50a1-46af-8591-9ab918d2fb65.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/93a1babd474b4b9b8878e668783f7dab.mp3',2,591,'mp3',591984,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎，","beginTime":0,"endTime":340,"channelId":0},{"speakerRole":"agent","index":1,"text":"好哎，","beginTime":340,"endTime":1172,"channelId":0},{"speakerRole":"agent","index":2,"text":"你好，","beginTime":1172,"endTime":1596,"channelId":0},{"speakerRole":"agent","index":3,"text":"请问是李女士吗？","beginTime":1596,"endTime":3080,"channelId":0},{"speakerRole":"agent","index":4,"text":"嗯，","beginTime":3460,"endTime":3634,"channelId":0},{"speakerRole":"agent","index":5,"text":"您好，","beginTime":3634,"endTime":3984,"channelId":0},{"speakerRole":"agent","index":6,"text":"哎，","beginTime":3984,"endTime":4159,"channelId":0},{"speakerRole":"agent","index":7,"text":"您好，","beginTime":4159,"endTime":4509,"channelId":0},{"speakerRole":"agent","index":8,"text":"女士，","beginTime":4509,"endTime":4858,"channelId":0},{"speakerRole":"agent","index":9,"text":"我这边是支付宝精选车贷的还款专员啊。","beginTime":4858,"endTime":7831,"channelId":0},{"speakerRole":"agent","index":10,"text":"您刚刚有在平台上面提交一笔车主贷初审给您审核通过了。","beginTime":7831,"endTime":12202,"channelId":0},{"speakerRole":"agent","index":11,"text":"呃，","beginTime":12202,"endTime":12377,"channelId":0},{"speakerRole":"agent","index":12,"text":"就是有一个三万零四百元，","beginTime":12377,"endTime":14301,"channelId":0},{"speakerRole":"agent","index":13,"text":"你有关注到吗？","beginTime":14301,"endTime":15350,"channelId":0},{"speakerRole":"agent","index":14,"text":"女士，","beginTime":15350,"endTime":15700,"channelId":0},{"speakerRole":"agent","index":15,"text":"嗯，","beginTime":16320,"endTime":16513,"channelId":0},{"speakerRole":"agent","index":16,"text":"我嗯你说吧，","beginTime":16513,"endTime":17482,"channelId":0},{"speakerRole":"agent","index":17,"text":"我只能听见你说啊，","beginTime":17482,"endTime":19032,"channelId":0},{"speakerRole":"agent","index":18,"text":"我们这边来电呢是结束，","beginTime":19032,"endTime":20970,"channelId":0},{"speakerRole":"agent","index":19,"text":"您补齐资料，","beginTime":20970,"endTime":21938,"channelId":0},{"speakerRole":"agent","index":20,"text":"走完流程给您放款的。","beginTime":21938,"endTime":23682,"channelId":0},{"speakerRole":"agent","index":21,"text":"像您当时提到的这辆贵d叉v a三八二是你本人名下的车吗？","beginTime":23682,"endTime":28720,"channelId":0},{"speakerRole":"agent","index":22,"text":"啊，","beginTime":30160,"endTime":30361,"channelId":0},{"speakerRole":"agent","index":23,"text":"怎么说啊，","beginTime":30361,"endTime":31166,"channelId":0},{"speakerRole":"agent","index":24,"text":"您这辆车的话，","beginTime":31166,"endTime":32374,"channelId":0},{"speakerRole":"agent","index":25,"text":"目前是属于全款结清，","beginTime":32374,"endTime":34186,"channelId":0},{"speakerRole":"agent","index":26,"text":"还是在按揭还款当中呢？","beginTime":34186,"endTime":36200,"channelId":0},{"speakerRole":"agent","index":27,"text":"嗯还清了的啊，","beginTime":36440,"endTime":37572,"channelId":0},{"speakerRole":"agent","index":28,"text":"还清了，","beginTime":37572,"endTime":38138,"channelId":0},{"speakerRole":"agent","index":29,"text":"那绿本的话也是在您这边的对吧？","beginTime":38138,"endTime":40780,"channelId":0},{"speakerRole":"agent","index":30,"text":"嗯，","beginTime":41220,"endTime":41476,"channelId":0},{"speakerRole":"agent","index":31,"text":"我就这么跟你说吧，","beginTime":41476,"endTime":43531,"channelId":0},{"speakerRole":"agent","index":32,"text":"这个车我就这么跟你说的，","beginTime":43531,"endTime":46356,"channelId":0},{"speakerRole":"agent","index":33,"text":"能听懂吗，","beginTime":46356,"endTime":47384,"channelId":0},{"speakerRole":"agent","index":34,"text":"能听见吗？","beginTime":47384,"endTime":48411,"channelId":0},{"speakerRole":"agent","index":35,"text":"我能听见能听见这个车木头是我，","beginTime":48411,"endTime":52186,"channelId":0},{"speakerRole":"agent","index":36,"text":"然后车不是我的，","beginTime":52186,"endTime":53599,"channelId":0},{"speakerRole":"agent","index":37,"text":"是我弟弟的。","beginTime":53599,"endTime":54607,"channelId":0},{"speakerRole":"agent","index":38,"text":"他的副头是我嘛，","beginTime":54607,"endTime":56020,"channelId":0},{"speakerRole":"agent","index":39,"text":"然后这是他的使用权，","beginTime":56260,"endTime":57934,"channelId":0},{"speakerRole":"agent","index":40,"text":"也是他他是叫我贷款给他用。","beginTime":57934,"endTime":60168,"channelId":0},{"speakerRole":"agent","index":41,"text":"然后我看到刚才说放款可以放三万多点，","beginTime":60168,"endTime":63331,"channelId":0},{"speakerRole":"agent","index":42,"text":"我想跟你商量一下，","beginTime":63331,"endTime":64820,"channelId":0},{"speakerRole":"agent","index":43,"text":"能不能少放点，","beginTime":64820,"endTime":65937,"channelId":0},{"speakerRole":"agent","index":44,"text":"放个两万可以吗？","beginTime":65937,"endTime":67240,"channelId":0},{"speakerRole":"agent","index":45,"text":"呃，","beginTime":67480,"endTime":67646,"channelId":0},{"speakerRole":"agent","index":46,"text":"两万零，","beginTime":67646,"endTime":68144,"channelId":0},{"speakerRole":"agent","index":47,"text":"那你现在输入最低贷款的话是多少？","beginTime":68144,"endTime":70637,"channelId":0},{"speakerRole":"agent","index":48,"text":"如果不行的话，","beginTime":70637,"endTime":71634,"channelId":0},{"speakerRole":"agent","index":49,"text":"我去给您申请一下。","beginTime":71634,"endTime":72964,"channelId":0},{"speakerRole":"agent","index":50,"text":"白也是可以输入两万，","beginTime":72964,"endTime":74460,"channelId":0},{"speakerRole":"agent","index":51,"text":"我那个少弄一点，","beginTime":75340,"endTime":76710,"channelId":0},{"speakerRole":"agent","index":52,"text":"最多就弄两万，","beginTime":76710,"endTime":77885,"channelId":0},{"speakerRole":"agent","index":53,"text":"不要弄多了。","beginTime":77885,"endTime":78865,"channelId":0},{"speakerRole":"agent","index":54,"text":"因为我说实话，","beginTime":78865,"endTime":80040,"channelId":0},{"speakerRole":"agent","index":55,"text":"他他因为他有那个尿毒症嘛，","beginTime":80280,"endTime":82778,"channelId":0},{"speakerRole":"agent","index":56,"text":"尿毒症，","beginTime":82778,"endTime":83403,"channelId":0},{"speakerRole":"agent","index":57,"text":"然后他就是为了帮那个有那个低保，","beginTime":83403,"endTime":86526,"channelId":0},{"speakerRole":"agent","index":58,"text":"所以复头才弄给我了，","beginTime":86526,"endTime":88400,"channelId":0},{"speakerRole":"agent","index":59,"text":"明白吗？","beginTime":88400,"endTime":89024,"channelId":0},{"speakerRole":"agent","index":60,"text":"对，","beginTime":89024,"endTime":89232,"channelId":0},{"speakerRole":"agent","index":61,"text":"没错，","beginTime":89232,"endTime":89649,"channelId":0},{"speakerRole":"agent","index":62,"text":"所以是这样子的，","beginTime":89649,"endTime":91106,"channelId":0},{"speakerRole":"agent","index":63,"text":"我的意思，","beginTime":91106,"endTime":91939,"channelId":0},{"speakerRole":"agent","index":64,"text":"他申请这个钱可能是有点急用还是干嘛，","beginTime":91939,"endTime":95479,"channelId":0},{"speakerRole":"agent","index":65,"text":"然后负责是我就相当于我来再给他用，","beginTime":95479,"endTime":98810,"channelId":0},{"speakerRole":"agent","index":66,"text":"还是他还让他还不上，","beginTime":98810,"endTime":100684,"channelId":0},{"speakerRole":"agent","index":67,"text":"肯定还是我还，","beginTime":100684,"endTime":101933,"channelId":0},{"speakerRole":"agent","index":68,"text":"对不对？","beginTime":101933,"endTime":102558,"channelId":0},{"speakerRole":"agent","index":69,"text":"然后我的意思就是说少申请五元，","beginTime":102558,"endTime":105473,"channelId":0},{"speakerRole":"agent","index":70,"text":"两万，","beginTime":105473,"endTime":105889,"channelId":0},{"speakerRole":"agent","index":71,"text":"两万贷两万，","beginTime":105889,"endTime":106930,"channelId":0},{"speakerRole":"agent","index":72,"text":"利息怎么算啊？","beginTime":106930,"endTime":108180,"channelId":0},{"speakerRole":"agent","index":73,"text":"呃，","beginTime":108680,"endTime":109520,"channelId":0},{"speakerRole":"agent","index":74,"text":"两万的话，","beginTime":109780,"endTime":110468,"channelId":0},{"speakerRole":"agent","index":75,"text":"其实也一万块钱一个月的一个平均综合业绩的话，","beginTime":110468,"endTime":114080,"channelId":0},{"speakerRole":"agent","index":76,"text":"大概是在一个一百一十四块钱左右哦。","beginTime":114080,"endTime":117996,"channelId":0},{"speakerRole":"agent","index":77,"text":"一万一万块，","beginTime":117996,"endTime":119980,"channelId":0},{"speakerRole":"agent","index":78,"text":"月月是一百多是吧，","beginTime":120000,"endTime":121433,"channelId":0},{"speakerRole":"agent","index":79,"text":"啊，","beginTime":121433,"endTime":121612,"channelId":0},{"speakerRole":"agent","index":80,"text":"一个月的一个综合平均月息的话是在一百一十四块钱左右。","beginTime":121612,"endTime":126093,"channelId":0},{"speakerRole":"agent","index":81,"text":"然后就是啊对，","beginTime":126093,"endTime":127168,"channelId":0},{"speakerRole":"agent","index":82,"text":"这是一个三年期的一个产品嘛，","beginTime":127168,"endTime":129498,"channelId":0},{"speakerRole":"agent","index":83,"text":"就是它是一个三年期的，","beginTime":129498,"endTime":131290,"channelId":0},{"speakerRole":"agent","index":84,"text":"然后三年的话它就会比一年的一个总利息的话会高一点。","beginTime":131290,"endTime":135591,"channelId":0},{"speakerRole":"agent","index":85,"text":"因为使用都使用了三十六个月嘛，","beginTime":135591,"endTime":138100,"channelId":0},{"speakerRole":"agent","index":86,"text":"在两万块钱的话，","beginTime":138340,"endTime":139488,"channelId":0},{"speakerRole":"agent","index":87,"text":"每个月的一个月供的话大概是一个七百八十四点零三，","beginTime":139488,"endTime":143262,"channelId":0},{"speakerRole":"agent","index":88,"text":"总利息的话大概是一个八千二百零三点三七，","beginTime":143262,"endTime":146380,"channelId":0},{"speakerRole":"agent","index":89,"text":"一年就是八百多了吧。","beginTime":146660,"endTime":148860,"channelId":0},{"speakerRole":"agent","index":90,"text":"这这是三单。","beginTime":149780,"endTime":150863,"channelId":0},{"speakerRole":"agent","index":91,"text":"这是三年的呀，","beginTime":150863,"endTime":152164,"channelId":0},{"speakerRole":"agent","index":92,"text":"然后我说给您说的是两万块钱的呀。","beginTime":152164,"endTime":155415,"channelId":0},{"speakerRole":"agent","index":93,"text":"哦哦哦哦，","beginTime":155415,"endTime":156282,"channelId":0},{"speakerRole":"agent","index":94,"text":"两万块就是一，","beginTime":156282,"endTime":157583,"channelId":0},{"speakerRole":"agent","index":95,"text":"两万块就是一年平均是多少，","beginTime":157583,"endTime":160184,"channelId":0},{"speakerRole":"agent","index":96,"text":"你就给我这么说，","beginTime":160184,"endTime":161701,"channelId":0},{"speakerRole":"agent","index":97,"text":"就呃，","beginTime":161701,"endTime":162134,"channelId":0},{"speakerRole":"agent","index":98,"text":"平均的一个利息嘛，","beginTime":162134,"endTime":163868,"channelId":0},{"speakerRole":"agent","index":99,"text":"一年啊，","beginTime":163868,"endTime":164519,"channelId":0},{"speakerRole":"agent","index":100,"text":"两万一年。","beginTime":164519,"endTime":165386,"channelId":0},{"speakerRole":"agent","index":101,"text":"您稍等我看一下哈，","beginTime":165386,"endTime":167120,"channelId":0},{"speakerRole":"agent","index":102,"text":"平均两万用两万块钱，","beginTime":167800,"endTime":169388,"channelId":0},{"speakerRole":"agent","index":103,"text":"每年的一个平均，","beginTime":169388,"endTime":170624,"channelId":0},{"speakerRole":"agent","index":104,"text":"连续的话大概综合连续的话大概是在一个两千七百三十四点四五左右。","beginTime":170624,"endTime":175920,"channelId":0},{"speakerRole":"agent","index":105,"text":"然后平均到一万的话，","beginTime":175920,"endTime":177508,"channelId":0},{"speakerRole":"agent","index":106,"text":"差不多就是一千三百六十八左右。","beginTime":177508,"endTime":179980,"channelId":0},{"speakerRole":"agent","index":107,"text":"嗯嗯，","beginTime":180000,"endTime":180436,"channelId":0},{"speakerRole":"agent","index":108,"text":"我想问一下，","beginTime":180436,"endTime":181527,"channelId":0},{"speakerRole":"agent","index":109,"text":"这个可不可以这样子啊，","beginTime":181527,"endTime":183709,"channelId":0},{"speakerRole":"agent","index":110,"text":"两可不可以不要三年两年行业是多少？","beginTime":183709,"endTime":187200,"channelId":0},{"speakerRole":"agent","index":111,"text":"呃，","beginTime":187680,"endTime":187857,"channelId":0},{"speakerRole":"agent","index":112,"text":"他他我们虽然是默认三十六期，","beginTime":187857,"endTime":190163,"channelId":0},{"speakerRole":"agent","index":113,"text":"但是它是支持提前结清的。","beginTime":190163,"endTim