:0},{"speakerRole":"agent","index":37,"text":"拜拜，","beginTime":62580,"endTime":63460,"channelId":0},{"speakerRole":"agent","index":38,"text":"嗯，","beginTime":64440,"endTime":64682,"channelId":0},{"speakerRole":"agent","index":39,"text":"祝您生活愉快。","beginTime":64682,"endTime":66140,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:43','2026-05-22 00:23:45','2026-05-22 00:23:38','2026-05-22 00:23:45','system','system','BATCH-20260522-207060',NULL),
