(205624,'rec_7a205efe46b44beba18d7e47','ext_830c00905b894059bc15b0027281098b','648fe674-b40e-4c07-b3b4-d28956f5fed1.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/02d15c761372436c9057f3033e5d552c.mp3',2,103,'mp3',103248,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"你好，","beginTime":0,"endTime":570,"channelId":0},{"speakerRole":"agent","index":1,"text":"是我的姓名和来电人。","beginTime":570,"endTime":3140,"channelId":0},{"speakerRole":"agent","index":2,"text":"喂喂，","beginTime":3760,"endTime":4180,"channelId":0},{"speakerRole":"agent","index":3,"text":"你好，","beginTime":4180,"endTime":4600,"channelId":0},{"speakerRole":"agent","index":4,"text":"请问是潘女士哈。","beginTime":4600,"endTime":6072,"channelId":0},{"speakerRole":"agent","index":5,"text":"嗯，","beginTime":6072,"endTime":6282,"channelId":0},{"speakerRole":"agent","index":6,"text":"你好你好，","beginTime":6282,"endTime":7123,"channelId":0},{"speakerRole":"agent","index":7,"text":"潘女士。","beginTime":7123,"endTime":7753,"channelId":0},{"speakerRole":"agent","index":8,"text":"我这边是支付宝之前车贷的客户经理。","beginTime":7753,"endTime":11116,"channelId":0},{"speakerRole":"agent","index":9,"text":"您刚才在支付宝申请了一笔车贷，","beginTime":11116,"endTime":14059,"channelId":0},{"speakerRole":"agent","index":10,"text":"对吧？","beginTime":14059,"endTime":14480,"channelId":0},{"speakerRole":"agent","index":11,"text":"啊，","beginTime":14900,"endTime":15127,"channelId":0},{"speakerRole":"agent","index":12,"text":"对啊，","beginTime":15127,"endTime":15581,"channelId":0},{"speakerRole":"agent","index":13,"text":"这边是审核都通过了，","beginTime":15581,"endTime":17624,"channelId":0},{"speakerRole":"agent","index":14,"text":"来电的话是随时能办理下款的。","beginTime":17624,"endTime":20575,"channelId":0},{"speakerRole":"agent","index":15,"text":"咱们这个车牌号苏苏j七零六八l是本人名下的车，","beginTime":20575,"endTime":25569,"channelId":0},{"speakerRole":"agent","index":16,"text":"对吧？","beginTime":25569,"endTime":26023,"channelId":0},{"speakerRole":"agent","index":17,"text":"嗯，","beginTime":26023,"endTime":26250,"channelId":0},{"speakerRole":"agent","index":18,"text":"对，","beginTime":26250,"endTime":26477,"channelId":0},{"speakerRole":"agent","index":19,"text":"全款还是按揭价格呢？","beginTime":26477,"endTime":28520,"channelId":0},{"speakerRole":"agent","index":20,"text":"嗯按揭按揭啊大概还剩多少天呢？","beginTime":29020,"endTime":34060,"channelId":0},{"speakerRole":"agent","index":21,"text":"哎呀，","beginTime":35220,"endTime":35671,"channelId":0},{"speakerRole":"agent","index":22,"text":"大概现在是几月份，","beginTime":35671,"endTime":37477,"channelId":0},{"speakerRole":"agent","index":23,"text":"五月份六七八是我说应该是五六七吧，","beginTime":37477,"endTime":41088,"channelId":0},{"speakerRole":"agent","index":24,"text":"大概五六七五一块。","beginTime":41088,"endTime":43221,"channelId":0},{"speakerRole":"agent","index":25,"text":"那你还剩多少吗？","beginTime":43221,"endTime":44880,"channelId":0},{"speakerRole":"agent","index":26,"text":"没有尾款啊，","beginTime":45360,"endTime":46345,"channelId":0},{"speakerRole":"agent","index":27,"text":"他就是五六七的贷款呃，","beginTime":46345,"endTime":49273,"channelId":0},{"speakerRole":"agent","index":28,"text":"我你是说的你你这个绿本的话是抵押在银行的对吧？","beginTime":49273,"endTime":54400,"channelId":0},{"speakerRole":"agent","index":29,"text":"嗯，","beginTime":54760,"endTime":54977,"channelId":0},{"speakerRole":"agent","index":30,"text":"对，","beginTime":54977,"endTime":55195,"channelId":0},{"speakerRole":"agent","index":31,"text":"当时在买车的时候，","beginTime":55195,"endTime":56935,"channelId":0},{"speakerRole":"agent","index":32,"text":"他做的什么汽车金融啊这东西的。","beginTime":56935,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":33,"text":"哦，","beginTime":60000,"endTime":60172,"channelId":0},{"speakerRole":"agent","index":34,"text":"对对，","beginTime":60172,"endTime":60517,"channelId":0},{"speakerRole":"agent","index":35,"text":"嗯，","beginTime":60517,"endTime":60690,"channelId":0},{"speakerRole":"agent","index":36,"text":"好的好的，","beginTime":60690,"endTime":61380,"channelId":0},{"speakerRole":"agent","index":37,"text":"嗯，","beginTime":61380,"endTime":61553,"channelId":0},{"speakerRole":"agent","index":38,"text":"那您这边的话是这样子的哈。","beginTime":61553,"endTime":63623,"channelId":0},{"speakerRole":"agent","index":39,"text":"潘潘女士，","beginTime":63623,"endTime":64313,"channelId":0},{"speakerRole":"agent","index":40,"text":"我们这边那个车贷的话，","beginTime":64313,"endTime":66039,"channelId":0},{"speakerRole":"agent","index":41,"text":"它是需要全换质量呢才能结清的。","beginTime":66039,"endTime":68455,"channelId":0},{"speakerRole":"agent","index":42,"text":"所以当时我问你的一个尾款还剩多少的话，","beginTime":68455,"endTime":71561,"channelId":0},{"speakerRole":"agent","index":43,"text":"就是因为我们这边给到您的一个预审额度的话，","beginTime":71561,"endTime":75012,"channelId":0},{"speakerRole":"agent","index":44,"text":"是二十万。","beginTime":75012,"endTime":75702,"channelId":0},{"speakerRole":"agent","index":45,"text":"如果您的尾款先的不多的话，","beginTime":75702,"endTime":77773,"channelId":0},{"speakerRole":"agent","index":46,"text":"您可以考虑先提前结清，","beginTime":77773,"endTime":79499,"channelId":0},{"speakerRole":"agent","index":47,"text":"提前清结清之后再在我们这边来办理哦。","beginTime":79499,"endTime":83112,"channelId":0},{"speakerRole":"agent","index":48,"text":"那现在意思就是申请不下来，","beginTime":83112,"endTime":85181,"channelId":0},{"speakerRole":"agent","index":49,"text":"对吧？","beginTime":85181,"endTime":85526,"channelId":0},{"speakerRole":"agent","index":50,"text":"对，","beginTime":85526,"endTime":85698,"channelId":0},{"speakerRole":"agent","index":51,"text":"是啊，","beginTime":85698,"endTime":86043,"channelId":0},{"speakerRole":"agent","index":52,"text":"如果说你的那个尾款，","beginTime":86043,"endTime":87595,"channelId":0},{"speakerRole":"agent","index":53,"text":"比如说可能就只剩两三万块钱了，","beginTime":87595,"endTime":90009,"channelId":0},{"speakerRole":"agent","index":54,"text":"或者是四五万块钱，","beginTime":90009,"endTime":91389,"channelId":0},{"speakerRole":"agent","index":55,"text":"你可以考虑提前结清。","beginTime":91389,"endTime":92941,"channelId":0},{"speakerRole":"agent","index":56,"text":"因为我们给到您的预售额度是二十万。","beginTime":92941,"endTime":95700,"channelId":0},{"speakerRole":"agent","index":57,"text":"嗯嗯，","beginTime":96080,"endTime":96489,"channelId":0},{"speakerRole":"agent","index":58,"text":"那行吧，","beginTime":96489,"endTime":97102,"channelId":0},{"speakerRole":"agent","index":59,"text":"弄不下来就算了。","beginTime":97102,"endTime":98534,"channelId":0},{"speakerRole":"agent","index":60,"text":"嗯，","beginTime":98534,"endTime":98739,"channelId":0},{"speakerRole":"agent","index":61,"text":"哎，","beginTime":98739,"endTime":98944,"channelId":0},{"speakerRole":"agent","index":62,"text":"好的好的，","beginTime":98944,"endTime":99762,"channelId":0},{"speakerRole":"agent","index":63,"text":"那我就不打扰您了。","beginTime":99762,"endTime":101398,"channelId":0},{"speakerRole":"agent","index":64,"text":"哎，","beginTime":101398,"endTime":101603,"channelId":0},{"speakerRole":"agent","index":65,"text":"好，","beginTime":101603,"endTime":101808,"channelId":0},{"speakerRole":"agent","index":66,"text":"拜拜。","beginTime":101808,"endTime":102217,"channelId":0},{"speakerRole":"agent","index":67,"text":"嗯，","beginTime":102217,"endTime":102421,"channelId":0},{"speakerRole":"agent","index":68,"text":"嗯，","beginTime":102421,"endTime":102626,"channelId":0},{"speakerRole":"agent","index":69,"text":"没事，","beginTime":102626,"endTime":103035,"channelId":0},{"speakerRole":"agent","index":70,"text":"好。","beginTime":103035,"endTime":103240,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:45','2026-05-22 00:23:48','2026-05-22 00:23:42','2026-05-22 00:23:48','system','system','BATCH-20260522-207060',NULL);
