(205625,'rec_4209ca0b6e0e47aea873eaff','ext_9999c1cb40b24ea0bc1be7ad23dd3950','4058f6fb-b0ea-40c1-9834-9b95ce039701.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/af2a14054f1c4f57a68b548c9ed13d29.mp3',2,114,'mp3',114912,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":840,"endTime":1260,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好啊，","beginTime":1260,"endTime":4480,"channelId":0},{"speakerRole":"agent","index":2,"text":"七二五的王先生啊，","beginTime":5600,"endTime":7500,"channelId":0},{"speakerRole":"agent","index":3,"text":"哎怎么了？","beginTime":8060,"endTime":9360,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎，","beginTime":10160,"endTime":10311,"channelId":0},{"speakerRole":"agent","index":5,"text":"王先生您好，","beginTime":10311,"endTime":11070,"channelId":0},{"speakerRole":"agent","index":6,"text":"我这边是支付宝天请车贷的回访部门来给您做个回访。","beginTime":11070,"endTime":14560,"channelId":0},{"speakerRole":"agent","index":7,"text":"嗯，","beginTime":15320,"endTime":15805,"channelId":0},{"speakerRole":"agent","index":8,"text":"您点多。","beginTime":15805,"endTime":17260,"channelId":0},{"speakerRole":"agent","index":9,"text":"嗯，","beginTime":17500,"endTime":17667,"channelId":0},{"speakerRole":"agent","index":10,"text":"对，","beginTime":17667,"endTime":17835,"channelId":0},{"speakerRole":"agent","index":11,"text":"您这边在五月十三日的时候，","beginTime":17835,"endTime":19845,"channelId":0},{"speakerRole":"agent","index":12,"text":"在我们支付宝之前是在跟进有个车贷产品嘛，","beginTime":19845,"endTime":23029,"channelId":0},{"speakerRole":"agent","index":13,"text":"看您是一直没有结婚使用的。","beginTime":23029,"endTime":25040,"channelId":0},{"speakerRole":"agent","index":14,"text":"您这边主要是因为什么原因呢？","beginTime":25360,"endTime":27334,"channelId":0},{"speakerRole":"agent","index":15,"text":"是觉得额度利息不合适，","beginTime":27334,"endTime":28853,"channelId":0},{"speakerRole":"agent","index":16,"text":"还是说有其他的原因，","beginTime":28853,"endTime":30220,"channelId":0},{"speakerRole":"agent","index":17,"text":"利息不合适啊，","beginTime":30960,"endTime":32054,"channelId":0},{"speakerRole":"agent","index":18,"text":"你这个利息太高了呀。","beginTime":32054,"endTime":33695,"channelId":0},{"speakerRole":"agent","index":19,"text":"现在呃，","beginTime":33695,"endTime":35121,"channelId":0},{"speakerRole":"agent","index":20,"text":"我这边看到您这边是呃，","beginTime":35121,"endTime":36937,"channelId":0},{"speakerRole":"agent","index":21,"text":"终审没有进行的，","beginTime":36937,"endTime":38208,"channelId":0},{"speakerRole":"agent","index":22,"text":"然后呢，","beginTime":38208,"endTime":38753,"channelId":0},{"speakerRole":"agent","index":23,"text":"现在给出的一个利息，","beginTime":38753,"endTime":40387,"channelId":0},{"speakerRole":"agent","index":24,"text":"只是一个模板利息。","beginTime":40387,"endTime":41840,"channelId":0},{"speakerRole":"agent","index":25,"text":"您后续的话呢，","beginTime":42180,"endTime":43087,"channelId":0},{"speakerRole":"agent","index":26,"text":"如果有需要的话，","beginTime":43087,"endTime":44145,"channelId":0},{"speakerRole":"agent","index":27,"text":"可以我我现在带领您去做一下终审，","beginTime":44145,"endTime":46413,"channelId":0},{"speakerRole":"agent","index":28,"text":"做一下终审。","beginTime":46413,"endTime":47169,"channelId":0},{"speakerRole":"agent","index":29,"text":"您到时候看一下额度利息咋满意不满意，","beginTime":47169,"endTime":49739,"channelId":0},{"speakerRole":"agent","index":30,"text":"咱们就不用嘛，","beginTime":49739,"endTime":50646,"channelId":0},{"speakerRole":"agent","index":31,"text":"到时候直接取消就可以了。","beginTime":50646,"endTime":52309,"channelId":0},{"speakerRole":"agent","index":32,"text":"满意的话，","beginTime":52309,"endTime":52914,"channelId":0},{"speakerRole":"agent","index":33,"text":"我们到时候再考虑怎么使用嘛，","beginTime":52914,"endTime":54880,"channelId":0},{"speakerRole":"agent","index":34,"text":"到时候再说吧哈现在不贴合，","beginTime":55840,"endTime":58920,"channelId":0},{"speakerRole":"agent","index":35,"text":"现在不缺钱了是吗？","beginTime":60000,"endTime":61460,"channelId":0},{"speakerRole":"agent","index":36,"text":"嗯嗯，","beginTime":61700,"endTime":63030,"channelId":0},{"speakerRole":"agent","index":37,"text":"好的，","beginTime":63030,"endTime":63372,"channelId":0},{"speakerRole":"agent","index":38,"text":"那您这笔时间的话，","beginTime":63372,"endTime":64740,"channelId":0},{"speakerRole":"agent","index":39,"text":"我这边就是给您冻结作为备用金，","beginTime":64740,"endTime":67133,"channelId":0},{"speakerRole":"agent","index":40,"text":"这样可以把它呃保持十五天左右。","beginTime":67133,"endTime":69526,"channelId":0},{"speakerRole":"agent","index":41,"text":"您这边的话，","beginTime":69526,"endTime":70381,"channelId":0},{"speakerRole":"agent","index":42,"text":"如果有需要的话，","beginTime":70381,"endTime":71577,"channelId":0},{"speakerRole":"agent","index":43,"text":"到时候再跟我们取得联系。","beginTime":71577,"endTime":73458,"channelId":0},{"speakerRole":"agent","index":44,"text":"好吧。","beginTime":73458,"endTime":73800,"channelId":0},{"speakerRole":"agent","index":45,"text":"好的好的，","beginTime":74300,"endTime":75320,"channelId":0},{"speakerRole":"agent","index":46,"text":"嗯，","beginTime":75560,"endTime":75723,"channelId":0},{"speakerRole":"agent","index":47,"text":"好的，","beginTime":75723,"endTime":76051,"channelId":0},{"speakerRole":"agent","index":48,"text":"那您这边手机号可以添加上您的微信吗？","beginTime":76051,"endTime":78837,"channelId":0},{"speakerRole":"agent","index":49,"text":"我这边用我们系统添加一下您的微信，","beginTime":78837,"endTime":81458,"channelId":0},{"speakerRole":"agent","index":50,"text":"后续如果有需要的话，","beginTime":81458,"endTime":82933,"channelId":0},{"speakerRole":"agent","index":51,"text":"也可以直接随时随时联系我。","beginTime":82933,"endTime":84900,"channelId":0},{"speakerRole":"agent","index":52,"text":"好的好的，","beginTime":85720,"endTime":87000,"channelId":0},{"speakerRole":"agent","index":53,"text":"可以。","beginTime":87000,"endTime":87640,"channelId":0},{"speakerRole":"agent","index":54,"text":"嗯，","beginTime":87880,"endTime":88040,"channelId":0},{"speakerRole":"agent","index":55,"text":"好的，","beginTime":88040,"endTime":88362,"channelId":0},{"speakerRole":"agent","index":56,"text":"您这边看一下您微信聊天页面会有一个服务通知，","beginTime":88362,"endTime":91740,"channelId":0},{"speakerRole":"agent","index":57,"text":"里面会有一个企业微信邀请人是呃小米小店的王清华。","beginTime":91980,"endTime":96460,"channelId":0},{"speakerRole":"agent","index":58,"text":"嗯，","beginTime":97480,"endTime":97940,"channelId":0},{"speakerRole":"agent","index":59,"text":"看贷款。","beginTime":97940,"endTime":99535,"channelId":0},{"speakerRole":"agent","index":60,"text":"好的，","beginTime":99535,"endTime":100230,"channelId":0},{"speakerRole":"agent","index":61,"text":"那我给我。","beginTime":100230,"endTime":101620,"channelId":0},{"speakerRole":"agent","index":62,"text":"对啊，","beginTime":102100,"endTime":102515,"channelId":0},{"speakerRole":"agent","index":63,"text":"有了有了。","beginTime":102515,"endTime":103345,"channelId":0},{"speakerRole":"agent","index":64,"text":"嗯，","beginTime":103345,"endTime":103553,"channelId":0},{"speakerRole":"agent","index":65,"text":"好好，","beginTime":103553,"endTime":103968,"channelId":0},{"speakerRole":"agent","index":66,"text":"嗯，","beginTime":103968,"endTime":104176,"channelId":0},{"speakerRole":"agent","index":67,"text":"您这边通过一下，","beginTime":104176,"endTime":105630,"channelId":0},{"speakerRole":"agent","index":68,"text":"然后那后续有问题的话，","beginTime":105630,"endTime":107706,"channelId":0},{"speakerRole":"agent","index":69,"text":"随时可以联系我。","beginTime":107706,"endTime":109160,"channelId":0},{"speakerRole":"agent","index":70,"text":"好的好的，","beginTime":109580,"endTime":110460,"channelId":0},{"speakerRole":"agent","index":71,"text":"嗯，","beginTime":110460,"endTime":110680,"channelId":0},{"speakerRole":"agent","index":72,"text":"好，","beginTime":110680,"endTime":110900,"channelId":0},{"speakerRole":"agent","index":73,"text":"再见啊。","beginTime":110900,"endTime":111560,"channelId":0},{"speakerRole":"agent","index":74,"text":"嗯好的，","beginTime":111800,"endTime":112304,"channelId":0},{"speakerRole":"agent","index":75,"text":"那我这边就不打扰您了，","beginTime":112304,"endTime":113984,"channelId":0},{"speakerRole":"agent","index":76,"text":"再见。","beginTime":113984,"endTime":114320,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:48','2026-05-22 00:23:50','2026-05-22 00:23:44','2026-05-22 00:23:50','system','system','BATCH-20260522-207060',NULL),
(205626,'rec_b5c2146b31e34b5ca7d7a4e1','ext_2315d87565f54bf187b682490c584adb','51978a86-294a-40ab-b46a-1f01c43c6d14.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/0741c9c2c2c34fd5b8ca8aac3c94f0e2.mp3',2,187,'mp3',187848,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎，","beginTime":1540,"endTime":1826,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":1826,"endTime":2400,"channelId":0},{"speakerRole":"agent","index":2,"text":"杨先生你好。","beginTime":2400,"endTime":4600,"channelId":0},{"speakerRole":"agent","index":3,"text":"哎，","beginTime":5100,"endTime":5284,"channelId":0},{"speakerRole":"agent","index":4,"text":"你看一下，","beginTime":5284,"endTime":6020,"channelId":0},{"speakerRole":"agent","index":5,"text":"我这边是路口菱汽车的服务，","beginTime":6020,"endTime":8228,"channelId":0},{"speakerRole":"agent","index":6,"text":"很多人就是你刚刚不是在支付宝申请了一笔新的车贷码，","beginTime":8228,"endTime":12644,"channelId":0},{"speakerRole":"agent","index":7,"text":"有印象吗？","beginTime":12644,"endTime":13380,"channelId":0},{"speakerRole":"agent","index":8,"text":"啊，","beginTime":13800,"endTime":14008,"channelId":0},{"speakerRole":"agent","index":9,"text":"对哎，","beginTime":14008,"endTime":14426,"channelId":0},{"speakerRole":"agent","index":10,"text":"对，","beginTime":14426,"endTime":14635,"channelId":0},{"speakerRole":"agent","index":11,"text":"就是现在的话预审已经通过了，","beginTime":14635,"endTime":17351,"channelId":0},{"speakerRole":"agent","index":12,"text":"后期天放款的部分，","beginTime":17351,"endTime":19022,"channelId":0},{"speakerRole":"agent","index":13,"text":"因为我这边协助您办理。","beginTime":19022,"endTime":21111,"channelId":0},{"speakerRole":"agent","index":14,"text":"呃，","beginTime":21111,"endTime":21320,"channelId":0},{"speakerRole":"agent","index":15,"text":"您这辆陕汽三三g八三，","beginTime":21320,"endTime":23408,"channelId":0},{"speakerRole":"agent","index":16,"text":"这辆车是你本人名下的全部客车吗？","beginTime":23408,"endTime":26542,"channelId":0},{"speakerRole":"agent","index":17,"text":"先生，","beginTime":26542,"endTime":26960,"channelId":0},{"speakerRole":"agent","index":18,"text":"对的是的哦，","beginTime":27640,"endTime":29429,"channelId":0},{"speakerRole":"agent","index":19,"text":"行，","beginTime":29429,"endTime":29618,"channelId":0},{"speakerRole":"agent","index":20,"text":"那它是符合办理条件证的呃，","beginTime":29618,"endTime":31892,"channelId":0},{"speakerRole":"agent","index":21,"text":"现在的话需要在支付宝这边完善一下，","beginTime":31892,"endTime":34923,"channelId":0},{"speakerRole":"agent","index":22,"text":"真的要提交上来审核。","beginTime":34923,"endTime":36628,"channelId":0},{"speakerRole":"agent","index":23,"text":"审核通过的话，","beginTime":36628,"endTime":37765,"channelId":0},{"speakerRole":"agent","index":24,"text":"这边就可以让我们给您安排放款了。","beginTime":37765,"endTime":40606,"channelId":0},{"speakerRole":"agent","index":25,"text":"您现在这边知道他在身边吗？","beginTime":40606,"endTime":42880,"channelId":0},{"speakerRole":"agent","index":26,"text":"资料有什么大本啊，","beginTime":44520,"endTime":46419,"channelId":0},{"speakerRole":"agent","index":27,"text":"哎对，","beginTime":46419,"endTime":46893,"channelId":0},{"speakerRole":"agent","index":28,"text":"大本的照片和行驶证本的照片啊。","beginTime":46893,"endTime":51480,"channelId":0},{"speakerRole":"agent","index":29,"text":"有。","beginTime":51480,"endTime":52080,"channelId":0},{"speakerRole":"agent","index":30,"text":"嗯，","beginTime":52320,"endTime":52514,"channelId":0},{"speakerRole":"agent","index":31,"text":"行，","beginTime":52514,"endTime":52708,"channelId":0},{"speakerRole":"agent","index":32,"text":"那我这边加您个微信，","beginTime":52708,"endTime":54456,"channelId":0},{"speakerRole":"agent","index":33,"text":"我协助您办理一下啊。","beginTime":54456,"endTime":56203,"channelId":0},{"speakerRole":"agent","index":34,"text":"不是没电啊啊，","beginTime":56203,"endTime":57369,"channelId":0},{"speakerRole":"agent","index":35,"text":"等一下，","beginTime":57369,"endTime":57951,"channelId":0},{"speakerRole":"agent","index":36,"text":"等电，","beginTime":57951,"endTime":58340,"channelId":0},{"speakerRole":"agent","index":37,"text":"这是一律加上来呃，","beginTime":59360,"endTime":61928,"channelId":0},{"speakerRole":"agent","index":38,"text":"利率这些您进这个支付宝支付网上这样的时候，","beginTime":61928,"endTime":65688,"channelId":0},{"speakerRole":"agent","index":39,"text":"可以看到每月的一个还款计划表，","beginTime":65688,"endTime":68320,"channelId":0},{"speakerRole":"agent","index":40,"text":"这是初始的一个显示的额度利率。","beginTime":68320,"endTime":70952,"channelId":0},{"speakerRole":"agent","index":41,"text":"这些最终的话您提交的资料，","beginTime":70952,"endTime":73208,"channelId":0},{"speakerRole":"agent","index":42,"text":"然后审核老师这边会根据您提交的资料，","beginTime":73208,"endTime":76404,"channelId":0},{"speakerRole":"agent","index":43,"text":"以及您的一个个人征信这边来判定的。","beginTime":76404,"endTime":79412,"channelId":0},{"speakerRole":"agent","index":44,"text":"如果您的征信好一点的话，","beginTime":79412,"endTime":81480,"channelId":0},{"speakerRole":"agent","index":45,"text":"它的利率这边会给你降。","beginTime":81480,"endTime":83360,"channelId":0},{"speakerRole":"agent","index":46,"text":"嗯，","beginTime":86320,"endTime":86580,"channelId":0},{"speakerRole":"agent","index":47,"text":"那你们最高的那个是吧，","beginTime":86580,"endTime":89180,"channelId":0},{"speakerRole":"agent","index":48,"text":"最高的就是二十三点九四了。","beginTime":90540,"endTime":95240,"channelId":0},{"speakerRole":"agent","index":49,"text":"那你就没有百分之二十四了吧，","beginTime":97360,"endTime":99780,"channelId":0},{"speakerRole":"agent","index":50,"text":"嗯差不多吧，","beginTime":100560,"endTime":101885,"channelId":0},{"speakerRole":"agent","index":51,"text":"但是还没有达到嗯车子贷行业的话，","beginTime":101885,"endTime":105229,"channelId":0},{"speakerRole":"agent","index":52,"text":"我们这边给的利息都是比较低的。","beginTime":105229,"endTime":107415,"channelId":0},{"speakerRole":"agent","index":53,"text":"你可以到时候对比一下嘛，","beginTime":107415,"endTime":109133,"channelId":0},{"speakerRole":"agent","index":54,"text":"因为他这个也不会长长时间下款。","beginTime":109133,"endTime":111319,"channelId":0},{"speakerRole":"agent","index":55,"text":"你这边申请通过了之后，","beginTime":111319,"endTime":112881,"channelId":0},{"speakerRole":"agent","index":56,"text":"呃，","beginTime":112881,"endTime":113037,"channelId":0},{"speakerRole":"agent","index":57,"text":"如果觉得合适的话，","beginTime":113037,"endTime":114286,"channelId":0},{"speakerRole":"agent","index":58,"text":"让我们这边给你下货。","beginTime":114286,"endTime":115692,"channelId":0},{"speakerRole":"agent","index":59,"text":"如果你觉得不合适的话，","beginTime":115692,"endTime":117253,"channelId":0},{"speakerRole":"agent","index":60,"text":"不使用它，","beginTime":117253,"endTime":117878,"channelId":0},{"speakerRole":"agent","index":61,"text":"这边是没有任何影响的。","beginTime":117878,"endTime":119440,"channelId":0},{"speakerRole":"agent","index":62,"text":"他可以自由还吗？","beginTime":120020,"endTime":121340,"channelId":0},{"speakerRole":"agent","index":63,"text":"自由环就是说然后比如说我先急用，","beginTime":122020,"endTime":126334,"channelId":0},{"speakerRole":"agent","index":64,"text":"然后我我嗯然后八零，","beginTime":126334,"endTime":128129,"channelId":0},{"speakerRole":"agent","index":65,"text":"然后可能因为一个月用两个月，","beginTime":128129,"endTime":130723,"channelId":0},{"speakerRole":"agent","index":66,"text":"然后就比较好用了吧。","beginTime":130723,"endTime":132519,"channelId":0},{"speakerRole":"agent","index":67,"text":"哦可以，","beginTime":132519,"endTime":133117,"channelId":0},{"speakerRole":"agent","index":68,"text":"我们这边下款了之后是一次性下款。","beginTime":133117,"endTime":136110,"channelId":0},{"speakerRole":"agent","index":69,"text":"您用两个月、三个月或者半年，","beginTime":136110,"endTime":138504,"channelId":0},{"speakerRole":"agent","index":70,"text":"这个是可以结清的。","beginTime":138504,"endTime":140101,"channelId":0},{"speakerRole":"agent","index":71,"text":"但是您这个如果一年内结清，","beginTime":140101,"endTime":142495,"channelId":0},{"speakerRole":"agent","index":72,"text":"它是有剩余本金百分之四的违约金。","beginTime":142495,"endTime":145488,"channelId":0},{"speakerRole":"agent","index":73,"text":"一年后结清的话，","beginTime":145488,"endTime":146884,"channelId":0},{"speakerRole":"agent","index":74,"text":"它是没有任何违约金的。","beginTime":146884,"endTime":148880,"channelId":0},{"speakerRole":"agent","index":75,"text":"嗯，","beginTime":151380,"endTime":151693,"channelId":0},{"speakerRole":"agent","index":76,"text":"叫什么那个重庆小米消金，","beginTime":151693,"endTime":154722,"channelId":0},{"speakerRole":"agent","index":77,"text":"哎，","beginTime":154722,"endTime":154906,"channelId":0},{"speakerRole":"agent","index":78,"text":"对，","beginTime":154906,"endTime":155090,"channelId":0},{"speakerRole":"agent","index":79,"text":"我这边叫小米消金澄华，","beginTime":155090,"endTime":156928,"channelId":0},{"speakerRole":"agent","index":80,"text":"我刚刚已经添加您了，","beginTime":156928,"endTime":158582,"channelId":0},{"speakerRole":"agent","index":81,"text":"我看到您这边也通过了。","beginTime":158582,"endTime":160420,"channelId":0},{"speakerRole":"agent","index":82,"text":"嗯，","beginTime":161740,"endTime":161951,"channelId":0},{"speakerRole":"agent","index":83,"text":"我把那个大本的拍照模板发给您一下，","beginTime":161951,"endTime":165340,"channelId":0},{"speakerRole":"agent","index":84,"text":"您这边嗯照着那样拍。","beginTime":165340,"endTime":167246,"channelId":0},{"speakerRole":"agent","index":85,"text":"因为大本的话要那样拍才能上传上去。","beginTime":167246,"endTime":170635,"channelId":0},{"speakerRole":"agent","index":86,"text":"然后你那个呃行驶证也在身边吗？","beginTime":170635,"endTime":173600,"channelId":0},{"speakerRole":"agent","index":87,"text":"这边有个照片哦，","beginTime":174420,"endTime":175621,"channelId":0},{"speakerRole":"agent","index":88,"text":"哦，","beginTime":175621,"endTime":175793,"channelId":0},{"speakerRole":"agent","index":89,"text":"可以可以，","beginTime":175793,"endTime":176480,"channelId":0},{"speakerRole":"agent","index":90,"text":"那您上传进去了。","beginTime":176480,"endTime":177681,"channelId":0},{"speakerRole":"agent","index":91,"text":"如果您这边有什么问题，","beginTime":177681,"endTime":179398,"channelId":0},{"speakerRole":"agent","index":92,"text":"直接问我这边啊。","beginTime":179398,"endTime":180600,"channelId":0},{"speakerRole":"agent","index":93,"text":"嗯，","beginTime":181340,"endTime":181910,"channelId":0},{"speakerRole":"agent","index":94,"text":"好好的好的，","beginTime":181910,"endTime":183476,"channelId":0},{"speakerRole":"agent","index":95,"text":"那我就先挂了。","beginTime":183476,"endTime":184612,"channelId":0},{"speakerRole":"agent","index":96,"text":"杨先生，","beginTime":184612,"endTime":185180,"channelId":0},{"speakerRole":"agent","index":97,"text":"嗯嗯，","beginTime":185600,"endTime":186346,"channelId":0},{"speakerRole":"agent","index":98,"text":"好好，","beginTime":186346,"endTime":187093,"channelId":0},{"speakerRole":"agent","index":99,"text":"再见。","beginTime":187093,"endTime":187840,"channelId":0}]}',80,NULL,NULL,0,0,2,'2026-05-22 00:23:48','2026-05-22 00:23:52','2026-05-22 00:23:45','2026-05-22 00:23:52','system','system','BATCH-20260522-207060',NULL),
(205627,'rec_c69de08511814c60a50efb07','ext_31308457bcd64c00a9a00dc3c0a9dd01','681831ae-a0a9-4bd8-baac-a8925eda4b2b.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/d9b3c23641c34205aeb2c6d77fae60e9.mp3',2,195,'mp3',195768,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":1840,"endTime":2044,"channelId":0},{"speakerRole":"agent","index":1,"text":"哎你好，","beginTime":2044,"endTime":2656,"channelId":0},{"speakerRole":"agent","index":2,"text":"哎，","beginTime":2656,"endTime":2860,"channelId":0},{"speakerRole":"agent","index":3,"text":"是手机尾号二四五幺的郑先生，","beginTime":2860,"endTime":5512,"channelId":0},{"speakerRole":"agent","index":4,"text":"对吧？","beginTime":5512,"endTime":5920,"channelId":0},{"speakerRole":"agent","index":5,"text":"对啊，","beginTime":6300,"endTime":7040,"channelId":0},{"speakerRole":"agent","index":6,"text":"你好，","beginTime":7300,"endTime":7620,"channelId":0},{"speakerRole":"agent","index":7,"text":"邓先生，","beginTime":7620,"endTime":8100,"channelId":0},{"speakerRole":"agent","index":8,"text":"我是支付宝金选车贷客服经理。","beginTime":8100,"endTime":10180,"channelId":0},{"speakerRole":"agent","index":9,"text":"就刚才收到您在支付宝平台上提交的车贷业务申请，","beginTime":10180,"endTime":13700,"channelId":0},{"speakerRole":"agent","index":10,"text":"这边协助是可以办理的。","beginTime":13700,"endTime":15300,"channelId":0},{"speakerRole":"agent","index":11,"text":"给您确定一下车辆信息啊，","beginTime":15560,"endTime":17391,"channelId":0},{"speakerRole":"agent","index":12,"text":"您这辆车牌号e s尾号e m六，","beginTime":17391,"endTime":19555,"channelId":0},{"speakerRole":"agent","index":13,"text":"这辆车子是感觉本身对象了吗？","beginTime":19555,"endTime":21720,"channelId":0},{"speakerRole":"agent","index":14,"text":"对，","beginTime":22040,"endTime":22740,"channelId":0},{"speakerRole":"agent","index":15,"text":"目前车子是全款还是四s店状态，","beginTime":23100,"endTime":25460,"channelId":0},{"speakerRole":"agent","index":16,"text":"按揭还完哦，","beginTime":27000,"endTime":28828,"channelId":0},{"speakerRole":"agent","index":17,"text":"按揭已经还完了是吧？","beginTime":28828,"endTime":30701,"channelId":0},{"speakerRole":"agent","index":18,"text":"哎，","beginTime":30701,"endTime":30910,"channelId":0},{"speakerRole":"agent","index":19,"text":"好的，","beginTime":30910,"endTime":31326,"channelId":0},{"speakerRole":"agent","index":20,"text":"那是符合办理条件的。","beginTime":31326,"endTime":33200,"channelId":0},{"speakerRole":"agent","index":21,"text":"呃，","beginTime":33440,"endTime":33588,"channelId":0},{"speakerRole":"agent","index":22,"text":"然后我看一下平均预审批的额度是六万八千五，","beginTime":33588,"endTime":36558,"channelId":0},{"speakerRole":"agent","index":23,"text":"你具体需要用到多少资金啊？","beginTime":36558,"endTime":38340,"channelId":0},{"speakerRole":"agent","index":24,"text":"嗯，","beginTime":43120,"endTime":43960,"channelId":0},{"speakerRole":"agent","index":25,"text":"什么三万是吧，","beginTime":44640,"endTime":46060,"channelId":0},{"speakerRole":"agent","index":26,"text":"嗯，","beginTime":46360,"endTime":47160,"channelId":0},{"speakerRole":"agent","index":27,"text":"哦那可以的。","beginTime":47600,"endTime":48548,"channelId":0},{"speakerRole":"agent","index":28,"text":"然后您现在那个行驶证和绿本的照片，","beginTime":48548,"endTime":51583,"channelId":0},{"speakerRole":"agent","index":29,"text":"手机里面有没有成长的？","beginTime":51583,"endTime":53480,"channelId":0},{"speakerRole":"agent","index":30,"text":"ok有手机里面有吗？","beginTime":55060,"endTime":58320,"channelId":0},{"speakerRole":"agent","index":31,"text":"没有没有的。","beginTime":58760,"endTime":59746,"channelId":0},{"speakerRole":"agent","index":32,"text":"那你原件的日本的原件，","beginTime":59746,"endTime":61720,"channelId":0},{"speakerRole":"agent","index":33,"text":"您现在是在哪里啊？","beginTime":61720,"endTime":63300,"channelId":0},{"speakerRole":"agent","index":34,"text":"明天在家里，","beginTime":63820,"endTime":65160,"channelId":0},{"speakerRole":"agent","index":35,"text":"在家里吗？","beginTime":65640,"endTime":66840,"channelId":0},{"speakerRole":"agent","index":36,"text":"嗯，","beginTime":68120,"endTime":68383,"channelId":0},{"speakerRole":"agent","index":37,"text":"具体你现在远不远啊，","beginTime":68383,"endTime":70753,"channelId":0},{"speakerRole":"agent","index":38,"text":"家里对呃，","beginTime":70753,"endTime":73548,"channelId":0},{"speakerRole":"agent","index":39,"text":"是在老家还是在您现在住地方用了，","beginTime":73548,"endTime":77300,"channelId":0},{"speakerRole":"agent","index":40,"text":"对吧？","beginTime":77300,"endTime":77860,"channelId":0},{"speakerRole":"agent","index":41,"text":"明天吧，","beginTime":78100,"endTime":79100,"channelId":0},{"speakerRole":"agent","index":42,"text":"在您住的地方呢，","beginTime":79340,"endTime":80646,"channelId":0},{"speakerRole":"agent","index":43,"text":"是吧？","beginTime":80646,"endTime":81020,"channelId":0},{"speakerRole":"agent","index":44,"text":"嗯嗯，","beginTime":81360,"endTime":82248,"channelId":0},{"speakerRole":"agent","index":45,"text":"那我先那资金是要什么时候用的，","beginTime":82248,"endTime":85600,"channelId":0},{"speakerRole":"agent","index":46,"text":"这笔钱是要什么时候用到呢？","beginTime":85600,"endTime":87260,"channelId":0},{"speakerRole":"agent","index":47,"text":"没有啊，","beginTime":87860,"endTime":88433,"channelId":0},{"speakerRole":"agent","index":48,"text":"我只筛选什么时候都可以，","beginTime":88433,"endTime":90534,"channelId":0},{"speakerRole":"agent","index":49,"text":"我只是看一下。","beginTime":90534,"endTime":91680,"channelId":0},{"speakerRole":"agent","index":50,"text":"对，","beginTime":92440,"endTime":92640,"channelId":0},{"speakerRole":"agent","index":51,"text":"您现在正忙，","beginTime":92640,"endTime":93640,"channelId":0},{"speakerRole":"agent","index":52,"text":"我等一下看一下。","beginTime":93640,"endTime":95040,"channelId":0},{"speakerRole":"agent","index":53,"text":"呃，","beginTime":95280,"endTime":95454,"channelId":0},{"speakerRole":"agent","index":54,"text":"我知道您现在的话就是说额度的话，","beginTime":95454,"endTime":98064,"channelId":0},{"speakerRole":"agent","index":55,"text":"现在只是过了个预审，","beginTime":98064,"endTime":99630,"channelId":0},{"speakerRole":"agent","index":56,"text":"您终审还没有通过。","beginTime":99630,"endTime":101022,"channelId":0},{"speakerRole":"agent","index":57,"text":"你要提交终审，","beginTime":101022,"endTime":102066,"channelId":0},{"speakerRole":"agent","index":58,"text":"这个额度给您批下来，","beginTime":102066,"endTime":103632,"channelId":0},{"speakerRole":"agent","index":59,"text":"批下来，","beginTime":103632,"endTime":104154,"channelId":0},{"speakerRole":"agent","index":60,"text":"你再考虑越不对。","beginTime":104154,"endTime":105372,"channelId":0},{"speakerRole":"agent","index":61,"text":"好吧。","beginTime":105372,"endTime":105720,"channelId":0},{"speakerRole":"agent","index":62,"text":"对，","beginTime":107040,"endTime":107276,"channelId":0},{"speakerRole":"agent","index":63,"text":"先这样吧。","beginTime":107276,"endTime":108220,"channelId":0},{"speakerRole":"agent","index":64,"text":"对对对，","beginTime":108520,"endTime":108990,"channelId":0},{"speakerRole":"agent","index":65,"text":"我先添加一下，","beginTime":108990,"endTime":109932,"channelId":0},{"speakerRole":"agent","index":66,"text":"因为这后期放款的话，","beginTime":109932,"endTime":111344,"channelId":0},{"speakerRole":"agent","index":67,"text":"都是我这边协助您操作的，","beginTime":111344,"endTime":113070,"channelId":0},{"speakerRole":"agent","index":68,"text":"都我这边给您办理好吧。","beginTime":113070,"endTime":114640,"channelId":0},{"speakerRole":"agent","index":69,"text":"嗯，","beginTime":114880,"endTime":115084,"channelId":0},{"speakerRole":"agent","index":70,"text":"你看一下微信上现在有没有收到这利息，","beginTime":115084,"endTime":118552,"channelId":0},{"speakerRole":"agent","index":71,"text":"利息是怎么样的啊，","beginTime":118552,"endTime":121380,"channelId":0},{"speakerRole":"agent","index":72,"text":"利息是怎么样的嗯，","beginTime":121820,"endTime":123441,"channelId":0},{"speakerRole":"agent","index":73,"text":"利息的话是我们有个期间六厘到一分一次。","beginTime":123441,"endTime":127091,"channelId":0},{"speakerRole":"agent","index":74,"text":"然后您具体要您提交完资料，","beginTime":127091,"endTime":129524,"channelId":0},{"speakerRole":"agent","index":75,"text":"这边审计结果为准呢，","beginTime":129524,"endTime":131349,"channelId":0},{"speakerRole":"agent","index":76,"text":"就相当于您的就是有贷一万块钱，","beginTime":131349,"endTime":134301,"channelId":0},{"speakerRole":"agent","index":77,"text":"咱们贷一万块钱哈，","beginTime":134301,"endTime":135823,"channelId":0},{"speakerRole":"agent","index":78,"text":"一个月利息在六十到一百一十四这个之间。","beginTime":135823,"endTime":139246,"channelId":0},{"speakerRole":"agent","index":79,"text":"然后让您提交完资料审批结果为准，","beginTime":139246,"endTime":142099,"channelId":0},{"speakerRole":"agent","index":80,"text":"好吧。","beginTime":142099,"endTime":142480,"channelId":0},{"speakerRole":"agent","index":81,"text":"啊，","beginTime":143280,"endTime":143448,"channelId":0},{"speakerRole":"agent","index":82,"text":"对，","beginTime":143448,"endTime":143616,"channelId":0},{"speakerRole":"agent","index":83,"text":"然后您看微信，","beginTime":143616,"endTime":144624,"channelId":0},{"speakerRole":"agent","index":84,"text":"看看有没有收到服务通知，","beginTime":144624,"endTime":146472,"channelId":0},{"speakerRole":"agent","index":85,"text":"一个黄色喇叭有没有看到。","beginTime":146472,"endTime":148320,"channelId":0},{"speakerRole":"agent","index":86,"text":"我说姐姐微信添加你了，","beginTime":149040,"endTime":150920,"channelId":0},{"speakerRole":"agent","index":87,"text":"嗯，","beginTime":151480,"endTime":151655,"channelId":0},{"speakerRole":"agent","index":88,"text":"然后你点进去查看，","beginTime":151655,"endTime":153060,"channelId":0},{"speakerRole":"agent","index":89,"text":"识别我的企业微信号二维码，","beginTime":153060,"endTime":155166,"channelId":0},{"speakerRole":"agent","index":90,"text":"添加到通讯录。","beginTime":155166,"endTime":156220,"channelId":0},{"speakerRole":"agent","index":91,"text":"添加过来了吗？","beginTime":166640,"endTime":167860,"channelId":0},{"speakerRole":"agent","index":92,"text":"后面。","beginTime":169260,"endTime":170240,"channelId":0},{"speakerRole":"agent","index":93,"text":"还没有啊嗯啊有的。","beginTime":173820,"endTime":176249,"channelId":0},{"speakerRole":"agent","index":94,"text":"然后您今天晚上您回去的话，","beginTime":176249,"endTime":178796,"channelId":0},{"speakerRole":"agent","index":95,"text":"把那个日本的照片，","beginTime":178796,"endTime":180494,"channelId":0},{"speakerRole":"agent","index":96,"text":"还有新生照片，","beginTime":180494,"endTime":181767,"channelId":0},{"speakerRole":"agent","index":97,"text":"先拍照。","beginTime":181767,"endTime":182404,"channelId":0},{"speakerRole":"agent","index":98,"text":"呃，","beginTime":182404,"endTime":182616,"channelId":0},{"speakerRole":"agent","index":99,"text":"传我卖手机。","beginTime":182616,"endTime":183678,"channelId":0},{"speakerRole":"agent","index":100,"text":"然后您有空的话，","beginTime":183678,"endTime":185163,"channelId":0},{"speakerRole":"agent","index":101,"text":"您联系我，","beginTime":185163,"endTime":186012,"channelId":0},{"speakerRole":"agent","index":102,"text":"我这边协助给您操作就好了。","beginTime":186012,"endTime":188560,"channelId":0},{"speakerRole":"agent","index":103,"text":"嗯，","beginTime":189120,"endTime":189373,"channelId":0},{"speakerRole":"agent","index":104,"text":"行，","beginTime":189373,"endTime":189627,"channelId":0},{"speakerRole":"agent","index":105,"text":"可以。","beginTime":189627,"endTime":190135,"channelId":0},{"speakerRole":"agent","index":106,"text":"好的。","beginTime":190135,"endTime":190643,"channelId":0},{"speakerRole":"agent","index":107,"text":"嗯，","beginTime":190643,"endTime":190896,"channelId":0},{"speakerRole":"agent","index":108,"text":"那先这样啊。","beginTime":190896,"endTime":192166,"channelId":0},{"speakerRole":"agent","index":109,"text":"嗯，","beginTime":192166,"endTime":192420,"channelId":0},{"speakerRole":"agent","index":110,"text":"好的，","beginTime":193280,"endTime":193693,"channelId":0},{"speakerRole":"agent","index":111,"text":"那祝您生活愉快，","beginTime":193693,"endTime":195140,"channelId":0},{"speakerRole":"agent","index":112,"text":"再见啊。","beginTime":195140,"endTime":195760,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:24:13','2026-05-22 00:24:16','2026-05-22 00:24:09','2026-05-22 00:24:16','system','system','BATCH-20260522-207060',NULL),
