(205645,'rec_789c46f26fc349f4a26406e1','ext_4358bd2cfb934dfd8cb8303aeb191bf8','68e099b0-0e31-48d2-97d8-1beeea074537.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/3df8ad52ee6d43b1a3957e182259e2ac.mp3',2,62,'mp3',67464,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":740,"endTime":1166,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好喂哎您好，","beginTime":1166,"endTime":3831,"channelId":0},{"speakerRole":"agent","index":2,"text":"请问您是手机尾号九七四一的郭先生是吗？","beginTime":3831,"endTime":7140,"channelId":0},{"speakerRole":"agent","index":3,"text":"对，","beginTime":7380,"endTime":8100,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎，","beginTime":8500,"endTime":8648,"channelId":0},{"speakerRole":"agent","index":5,"text":"郭先生您好，","beginTime":8648,"endTime":9388,"channelId":0},{"speakerRole":"agent","index":6,"text":"我这边是支付宝精选车贷的回访部门，","beginTime":9388,"endTime":11756,"channelId":0},{"speakerRole":"agent","index":7,"text":"来给您做个回访啊。","beginTime":11756,"endTime":12940,"channelId":0},{"speakerRole":"agent","index":8,"text":"呃您在我们支付宝十月十四日的时候申请有一个车贷产品，","beginTime":13360,"endTime":17237,"channelId":0},{"speakerRole":"agent","index":9,"text":"看您自己是没有激活使用的。","beginTime":17237,"endTime":19098,"channelId":0},{"speakerRole":"agent","index":10,"text":"您这边主要因为什么原因呢？","beginTime":19098,"endTime":20960,"channelId":0},{"speakerRole":"agent","index":11,"text":"嗯，","beginTime":21720,"endTime":22700,"channelId":0},{"speakerRole":"agent","index":12,"text":"那个这个不用了，","beginTime":23700,"endTime":26220,"channelId":0},{"speakerRole":"agent","index":13,"text":"再见。","beginTime":26220,"endTime":26940,"channelId":0},{"speakerRole":"agent","index":14,"text":"呃，","beginTime":28340,"endTime":28615,"channelId":0},{"speakerRole":"agent","index":15,"text":"现现在怎么了呀？","beginTime":28615,"endTime":30540,"channelId":0},{"speakerRole":"agent","index":16,"text":"这个现在没有，","beginTime":31620,"endTime":34340,"channelId":0},{"speakerRole":"agent","index":17,"text":"我说现在没借款的那个呃，","beginTime":35160,"endTime":38960,"channelId":0},{"speakerRole":"agent","index":18,"text":"需要哪些啊，","beginTime":39780,"endTime":40634,"channelId":0},{"speakerRole":"agent","index":19,"text":"也就是资金方面问题已经解决了，","beginTime":40634,"endTime":43028,"channelId":0},{"speakerRole":"agent","index":20,"text":"已经没有借款的需要了，","beginTime":43028,"endTime":44738,"channelId":0},{"speakerRole":"agent","index":21,"text":"是吧？","beginTime":44738,"endTime":45080,"channelId":0},{"speakerRole":"agent","index":22,"text":"嗯，","beginTime":46780,"endTime":47072,"channelId":0},{"speakerRole":"agent","index":23,"text":"好的，","beginTime":47072,"endTime":47656,"channelId":0},{"speakerRole":"agent","index":24,"text":"了解。","beginTime":47656,"endTime":48240,"channelId":0},{"speakerRole":"agent","index":25,"text":"呃，","beginTime":48480,"endTime":48634,"channelId":0},{"speakerRole":"agent","index":26,"text":"那您这边的话，","beginTime":48634,"endTime":49563,"channelId":0},{"speakerRole":"agent","index":27,"text":"这笔资金我这边给您扣钱，","beginTime":49563,"endTime":51267,"channelId":0},{"speakerRole":"agent","index":28,"text":"做个备用金，","beginTime":51267,"endTime":52041,"channelId":0},{"speakerRole":"agent","index":29,"text":"你们可以保证他的啊两个月的时间。","beginTime":52041,"endTime":54776,"channelId":0},{"speakerRole":"agent","index":30,"text":"您这边操作，","beginTime":54776,"endTime":55673,"channelId":0},{"speakerRole":"agent","index":31,"text":"如果有需要的话，","beginTime":55673,"endTime":56929,"channelId":0},{"speakerRole":"agent","index":32,"text":"可以看我们支付宝现在后台给他操作啊，","beginTime":56929,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":33,"text":"这边会有灯吗？","beginTime":60460,"endTime":62060,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:43','2026-05-22 00:23:45','2026-05-22 00:23:39','2026-05-22 00:23:45','system','system','BATCH-20260522-207060',NULL),
(205646,'rec_7b554fe694fa4aff85f010ff','ext_343c05fdcfeb4518be993b49f7c2a789','0126c093-0d74-40b8-b851-cc0d8356ce49.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/c23e48f9ceac4c90bf6f2522f85bbd48.mp3',2,72,'mp3',72648,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"哎，","beginTime":600,"endTime":794,"channelId":0},{"speakerRole":"agent","index":1,"text":"你好，","beginTime":794,"endTime":1183,"channelId":0},{"speakerRole":"agent","index":2,"text":"喂，","beginTime":1183,"endTime":1377,"channelId":0},{"speakerRole":"agent","index":3,"text":"哪里？","beginTime":1377,"endTime":1766,"channelId":0},{"speakerRole":"agent","index":4,"text":"哎，","beginTime":1766,"endTime":1960,"channelId":0},{"speakerRole":"agent","index":5,"text":"是聂先生，","beginTime":1960,"endTime":2737,"channelId":0},{"speakerRole":"agent","index":6,"text":"对吧？","beginTime":2737,"endTime":3126,"channelId":0},{"speakerRole":"agent","index":7,"text":"呃，","beginTime":3126,"endTime":3320,"channelId":0},{"speakerRole":"agent","index":8,"text":"这边是那个支付宝的，","beginTime":3320,"endTime":5069,"channelId":0},{"speakerRole":"agent","index":9,"text":"是支付宝新线车站的。","beginTime":5069,"endTime":6818,"channelId":0},{"speakerRole":"agent","index":10,"text":"您上个月底在我们这边不是提交了一个车申请吗？","beginTime":6818,"endTime":10900,"channelId":0},{"speakerRole":"agent","index":11,"text":"不用不用不用，","beginTime":11220,"endTime":12173,"channelId":0},{"speakerRole":"agent","index":12,"text":"嗯，","beginTime":12173,"endTime":12331,"channelId":0},{"speakerRole":"agent","index":13,"text":"啊你这个是资金周转了吗？","beginTime":12331,"endTime":14079,"channelId":0},{"speakerRole":"agent","index":14,"text":"还是什么情况？","beginTime":14079,"endTime":15032,"channelId":0},{"speakerRole":"agent","index":15,"text":"因为你这个订单哈一直在我们这个系统里面，","beginTime":15032,"endTime":18050,"channelId":0},{"speakerRole":"agent","index":16,"text":"所以会回报，","beginTime":18050,"endTime":18844,"channelId":0},{"speakerRole":"agent","index":17,"text":"你，","beginTime":18844,"endTime":19003,"channelId":0},{"speakerRole":"agent","index":18,"text":"知道吧？","beginTime":19003,"endTime":19480,"channelId":0},{"speakerRole":"agent","index":19,"text":"那怎么弄？","beginTime":19880,"endTime":21320,"channelId":0},{"speakerRole":"agent","index":20,"text":"对，","beginTime":21320,"endTime":21680,"channelId":0},{"speakerRole":"agent","index":21,"text":"呃，","beginTime":21920,"endTime":22058,"channelId":0},{"speakerRole":"agent","index":22,"text":"就是你这个三万六千七百角度暂时不用了吧吧。","beginTime":22058,"endTime":24820,"channelId":0},{"speakerRole":"agent","index":23,"text":"对呀，","beginTime":25120,"endTime":25555,"channelId":0},{"speakerRole":"agent","index":24,"text":"哦，","beginTime":25555,"endTime":25772,"channelId":0},{"speakerRole":"agent","index":25,"text":"您您这个车牌是闽d九四九r d嘛，","beginTime":25772,"endTime":29035,"channelId":0},{"speakerRole":"agent","index":26,"text":"他这个车是按揭的还是交换的啊，","beginTime":29035,"endTime":32080,"channelId":0},{"speakerRole":"agent","index":27,"text":"啊，","beginTime":33040,"endTime":33232,"channelId":0},{"speakerRole":"agent","index":28,"text":"都都已经更新了是吧？","beginTime":33232,"endTime":34964,"channelId":0},{"speakerRole":"agent","index":29,"text":"对，","beginTime":34964,"endTime":35156,"channelId":0},{"speakerRole":"agent","index":30,"text":"行，","beginTime":35156,"endTime":35349,"channelId":0},{"speakerRole":"agent","index":31,"text":"那条件是否合办理条件，","beginTime":35349,"endTime":37273,"channelId":0},{"speakerRole":"agent","index":32,"text":"然后你这个是我看您当时不是呃，","beginTime":37273,"endTime":39967,"channelId":0},{"speakerRole":"agent","index":33,"text":"四月二十七号十点二十分随便填的，","beginTime":39967,"endTime":42853,"channelId":0},{"speakerRole":"agent","index":34,"text":"随便填哦，","beginTime":42853,"endTime":43623,"channelId":0},{"speakerRole":"agent","index":35,"text":"随便填的就这样。","beginTime":43623,"endTime":44970,"channelId":0},{"speakerRole":"agent","index":36,"text":"你你方便加个微信啊，","beginTime":44970,"endTime":46702,"channelId":0},{"speakerRole":"agent","index":37,"text":"加个微信，","beginTime":46702,"endTime":47472,"channelId":0},{"speakerRole":"agent","index":38,"text":"然后这边您备注一下面。","beginTime":47472,"endTime":49396,"channelId":0},{"speakerRole":"agent","index":39,"text":"如果因为你这个还是有一定要求的，","beginTime":49396,"endTime":52282,"channelId":0},{"speakerRole":"agent","index":40,"text":"假如说面有需要的话，","beginTime":52282,"endTime":54014,"channelId":0},{"speakerRole":"agent","index":41,"text":"就是微信联系不不乱，","beginTime":54014,"endTime":55746,"channelId":0},{"speakerRole":"agent","index":42,"text":"谁改掉的，","beginTime":55746,"endTime":56516,"channelId":0},{"speakerRole":"agent","index":43,"text":"人家人家车都被变成你们的了。","beginTime":56516,"endTime":59017,"channelId":0},{"speakerRole":"agent","index":44,"text":"变速箱车子我不押车啊，","beginTime":59017,"endTime":60920,"channelId":0},{"speakerRole":"agent","index":45,"text":"一百五不要这样，","beginTime":61160,"endTime":63580,"channelId":0},{"speakerRole":"agent","index":46,"text":"你这个那个什么利息高的，","beginTime":63820,"endTime":66574,"channelId":0},{"speakerRole":"agent","index":47,"text":"厦门，","beginTime":66574,"endTime":67074,"channelId":0},{"speakerRole":"agent","index":48,"text":"那车都变成你们了，","beginTime":67074,"endTime":69077,"channelId":0},{"speakerRole":"agent","index":49,"text":"就这样了，","beginTime":69077,"endTime":70079,"channelId":0},{"speakerRole":"agent","index":50,"text":"拜拜。","beginTime":70079,"endTime":70580,"channelId":0},{"speakerRole":"agent","index":51,"text":"好好好，","beginTime":70820,"endTime":71600,"channelId":0},{"speakerRole":"agent","index":52,"text":"行嗯，","beginTime":71600,"endTime":72120,"channelId":0},{"speakerRole":"agent","index":53,"text":"嗯嗯。","beginTime":72120,"endTime":72640,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:43','2026-05-22 00:23:46','2026-05-22 00:23:40','2026-05-22 00:23:46','system','system','BATCH-20260522-207060',NULL),
(205647,'rec_d34627e5bd8640ec987d8123','ext_6aa9cd524e664c828fb9940c6998d5ac','0616a07b-f137-4373-aa57-61798ee5bada.mp3',2023391656704524699,8,2057739101828657154,2,5,'/data/upload/records/2023391656704524699/20260522/5eddb5b3402048f682dbe170d285ab60.mp3',2,172,'mp3',174600,'{"channels":2,"sentences":[{"speakerRole":"agent","index":0,"text":"喂，","beginTime":1140,"endTime":2120,"channelId":0},{"speakerRole":"agent","index":1,"text":"是曹先生吗？","beginTime":3300,"endTime":4720,"channelId":0},{"speakerRole":"agent","index":2,"text":"怎么嗯你五月十四号不是在支付宝提交了一笔汽车贷款吗？","beginTime":5040,"endTime":10464,"channelId":0},{"speakerRole":"agent","index":3,"text":"这笔资金今天需要给你办理放款吗？","beginTime":10464,"endTime":13180,"channelId":0},{"speakerRole":"agent","index":4,"text":"嗯，","beginTime":13520,"endTime":13873,"channelId":0},{"speakerRole":"agent","index":5,"text":"不用嗯，","beginTime":13873,"endTime":15047,"channelId":0},{"speakerRole":"agent","index":6,"text":"你最近解决了吗？","beginTime":15047,"endTime":16640,"channelId":0},{"speakerRole":"agent","index":7,"text":"嗯，","beginTime":17060,"endTime":17840,"channelId":0},{"speakerRole":"agent","index":8,"text":"那这个资金我们后期也不需要了吗？","beginTime":19360,"endTime":21850,"channelId":0},{"speakerRole":"agent","index":9,"text":"还是怎样的？","beginTime":21850,"endTime":22680,"channelId":0},{"speakerRole":"agent","index":10,"text":"我想问一下那个利息是什么情况嗯，","beginTime":23060,"endTime":26628,"channelId":0},{"speakerRole":"agent","index":11,"text":"利息的话，","beginTime":26628,"endTime":27382,"channelId":0},{"speakerRole":"agent","index":12,"text":"我这边的备注也给你说了，","beginTime":27382,"endTime":29454,"channelId":0},{"speakerRole":"agent","index":13,"text":"你审核通过了过后，","beginTime":29454,"endTime":30962,"channelId":0},{"speakerRole":"agent","index":14,"text":"我们这边可以给您申请降息的嘛。","beginTime":30962,"endTime":33600,"channelId":0},{"speakerRole":"agent","index":15,"text":"你你们不审核通过也不可以不可以看吗？","beginTime":36620,"endTime":40340,"channelId":0},{"speakerRole":"agent","index":16,"text":"嗯，","beginTime":40760,"endTime":40962,"channelId":0},{"speakerRole":"agent","index":17,"text":"是这样的，","beginTime":40962,"endTime":41771,"channelId":0},{"speakerRole":"agent","index":18,"text":"曹先生，","beginTime":41771,"endTime":42378,"channelId":0},{"speakerRole":"agent","index":19,"text":"我给你解释一下啊，","beginTime":42378,"endTime":43997,"channelId":0},{"speakerRole":"agent","index":20,"text":"因为我们这个利息券的话，","beginTime":43997,"endTime":46222,"channelId":0},{"speakerRole":"agent","index":21,"text":"他不是说每个客户都可以用的，","beginTime":46222,"endTime":48852,"channelId":0},{"speakerRole":"agent","index":22,"text":"他是每天他们不是说无限的，","beginTime":48852,"endTime":51280,"channelId":0},{"speakerRole":"agent","index":23,"text":"它是有限量的，","beginTime":51280,"endTime":52494,"channelId":0},{"speakerRole":"agent","index":24,"text":"知道吧？","beginTime":52494,"endTime":53101,"channelId":0},{"speakerRole":"agent","index":25,"text":"每天只有几张，","beginTime":53101,"endTime":54315,"channelId":0},{"speakerRole":"agent","index":26,"text":"所以说要肯定要审核通过了，","beginTime":54315,"endTime":56742,"channelId":0},{"speakerRole":"agent","index":27,"text":"然后确定你这个能通过，","beginTime":56742,"endTime":58766,"channelId":0},{"speakerRole":"agent","index":28,"text":"然后我们这边确定要要我们才能给你申请这个东西。","beginTime":58766,"endTime":62673,"channelId":0},{"speakerRole":"agent","index":29,"text":"你说你资料都没提交，","beginTime":62673,"endTime":64177,"channelId":0},{"speakerRole":"agent","index":30,"text":"我们这边也不能确定，","beginTime":64177,"endTime":65681,"channelId":0},{"speakerRole":"agent","index":31,"text":"也不能保证百分之百保证说哎，","beginTime":65681,"endTime":67854,"channelId":0},{"speakerRole":"agent","index":32,"text":"你这个病肯定是能通过的，","beginTime":67854,"endTime":69692,"channelId":0},{"speakerRole":"agent","index":33,"text":"对不对？","beginTime":69692,"endTime":70193,"channelId":0},{"speakerRole":"agent","index":34,"text":"没有一家机构贷款贷款公司，","beginTime":70193,"endTime":72198,"channelId":0},{"speakerRole":"agent","index":35,"text":"或者是说金融机构，","beginTime":72198,"endTime":73535,"channelId":0},{"speakerRole":"agent","index":36,"text":"或者是银行没有就是说你没有提交资料之前，","beginTime":73535,"endTime":76710,"channelId":0},{"speakerRole":"agent","index":37,"text":"没有审核之前不可能做保保证的。","beginTime":76710,"endTime":79050,"channelId":0},{"speakerRole":"agent","index":38,"text":"所以说这个降息算的话，","beginTime":79050,"endTime":80721,"channelId":0},{"speakerRole":"agent","index":39,"text":"我们可能显示也不会用的。","beginTime":80721,"endTime":82559,"channelId":0},{"speakerRole":"agent","index":40,"text":"你要提交了资料过后，","beginTime":82559,"endTime":84063,"channelId":0},{"speakerRole":"agent","index":41,"text":"审核通过了，","beginTime":84063,"endTime":84899,"channelId":0},{"speakerRole":"agent","index":42,"text":"那确定是能通过。","beginTime":84899,"endTime":86068,"channelId":0},{"speakerRole":"agent","index":43,"text":"然后你也确定你需要这笔资金，","beginTime":86068,"endTime":88241,"channelId":0},{"speakerRole":"agent","index":44,"text":"我们才能去申请降息的。","beginTime":88241,"endTime":89912,"channelId":0},{"speakerRole":"agent","index":45,"text":"因为的话这个余额有限嘛，","beginTime":89912,"endTime":91750,"channelId":0},{"speakerRole":"agent","index":46,"text":"对不对？","beginTime":91750,"endTime":92251,"channelId":0},{"speakerRole":"agent","index":47,"text":"那我给你用了过后，","beginTime":92251,"endTime":93588,"channelId":0},{"speakerRole":"agent","index":48,"text":"那你说你不要了，","beginTime":93588,"endTime":94758,"channelId":0},{"speakerRole":"agent","index":49,"text":"那这个名额又浪费了。","beginTime":94758,"endTime":96262,"channelId":0},{"speakerRole":"agent","index":50,"text":"那客户有有客户需要的，","beginTime":96262,"endTime":97933,"channelId":0},{"speakerRole":"agent","index":51,"text":"他是不是有用不上呢？","beginTime":97933,"endTime":99437,"channelId":0},{"speakerRole":"agent","index":52,"text":"对不对？","beginTime":99437,"endTime":99938,"channelId":0},{"speakerRole":"agent","index":53,"text":"曹先生，","beginTime":99938,"endTime":100440,"channelId":0},{"speakerRole":"agent","index":54,"text":"那我想知道你这个假期能假期多少呢？","beginTime":100680,"endTime":103300,"channelId":0},{"speakerRole":"agent","index":55,"text":"我这边的话，","beginTime":103560,"endTime":104480,"channelId":0},{"speakerRole":"agent","index":56,"text":"我们教训是两到四个点，","beginTime":104480,"endTime":106321,"channelId":0},{"speakerRole":"agent","index":57,"text":"我这边就直接给您申请这四个点审核通过了。","beginTime":106321,"endTime":109819,"channelId":0},{"speakerRole":"agent","index":58,"text":"你确定要要到底这个点的话，","beginTime":109819,"endTime":116020,"channelId":0},{"speakerRole":"agent","index":59,"text":"大嗯，","beginTime":116900,"endTime":118612,"channelId":0},{"speakerRole":"agent","index":60,"text":"那我到时先到时候再再说吧。","beginTime":118612,"endTime":121880,"channelId":0},{"speakerRole":"agent","index":61,"text":"你这边大概什么时候需要吗？","beginTime":122520,"endTime":124437,"channelId":0},{"speakerRole":"agent","index":62,"text":"因为这个降息券的话，","beginTime":124437,"endTime":125876,"channelId":0},{"speakerRole":"agent","index":63,"text":"他不是说呃一直在发放的，","beginTime":125876,"endTime":127634,"channelId":0},{"speakerRole":"agent","index":64,"text":"它是有可能是说公司今天出这个政策有降息券，","beginTime":127634,"endTime":130830,"channelId":0},{"speakerRole":"agent","index":65,"text":"对不对？","beginTime":130830,"endTime":131310,"channelId":0},{"speakerRole":"agent","index":66,"text":"有可能用了一个星期，","beginTime":131310,"endTime":132748,"channelId":0},{"speakerRole":"agent","index":67,"text":"然后申请交期的客户都很多，","beginTime":132748,"endTime":134666,"channelId":0},{"speakerRole":"agent","index":68,"text":"用劵了也很多。","beginTime":134666,"endTime":135625,"channelId":0},{"speakerRole":"agent","index":69,"text":"那用完了，","beginTime":135625,"endTime":136264,"channelId":0},{"speakerRole":"agent","index":70,"text":"那可能一个星期过后，","beginTime":136264,"endTime":137703,"channelId":0},{"speakerRole":"agent","index":71,"text":"他就没有交息券了，","beginTime":137703,"endTime":138981,"channelId":0},{"speakerRole":"agent","index":72,"text":"是这样的，","beginTime":138981,"endTime":139621,"channelId":0},{"speakerRole":"agent","index":73,"text":"那么是真，","beginTime":139621,"endTime":140260,"channelId":0},{"speakerRole":"agent","index":74,"text":"那么那个时候再让我继续等着。","beginTime":140260,"endTime":143000,"channelId":0},{"speakerRole":"agent","index":75,"text":"嗯，","beginTime":143400,"endTime":143593,"channelId":0},{"speakerRole":"agent","index":76,"text":"那你这笔资金大概什么时候需要嘛，","beginTime":143593,"endTime":146500,"channelId":0},{"speakerRole":"agent","index":77,"text":"我还不确定还不确定是就是说有这边就是说有这方面的，","beginTime":146820,"endTime":151870,"channelId":0},{"speakerRole":"agent","index":78,"text":"就是资金需求，","beginTime":151870,"endTime":153133,"channelId":0},{"speakerRole":"agent","index":79,"text":"但是还不确定到底什么时候用是吧？","beginTime":153133,"endTime":156289,"channelId":0},{"speakerRole":"agent","index":80,"text":"对哦，","beginTime":156289,"endTime":156933,"channelId":0},{"speakerRole":"agent","index":81,"text":"就是说你是在等一笔回款吗，","beginTime":156933,"endTime":159253,"channelId":0},{"speakerRole":"agent","index":82,"text":"还是怎样的，","beginTime":159253,"endTime":160220,"channelId":0},{"speakerRole":"agent","index":83,"text":"差不多吧。","beginTime":160760,"endTime":161441,"channelId":0},{"speakerRole":"agent","index":84,"text":"哦，","beginTime":161441,"endTime":161612,"channelId":0},{"speakerRole":"agent","index":85,"text":"再等一笔回款是吧？","beginTime":161612,"endTime":162975,"channelId":0},{"speakerRole":"agent","index":86,"text":"那好的好的，","beginTime":162975,"endTime":163827,"channelId":0},{"speakerRole":"agent","index":87,"text":"反正好像我刚刚看了一下，","beginTime":163827,"endTime":165702,"channelId":0},{"speakerRole":"agent","index":88,"text":"我加了你微信了，","beginTime":165702,"endTime":166895,"channelId":0},{"speakerRole":"agent","index":89,"text":"到时候微信上联系好吧好吧。","beginTime":166895,"endTime":169290,"channelId":0},{"speakerRole":"agent","index":90,"text":"嗯，","beginTime":169290,"endTime":169515,"channelId":0},{"speakerRole":"agent","index":91,"text":"好的好的，","beginTime":169515,"endTime":170415,"channelId":0},{"speakerRole":"agent","index":92,"text":"那不打扰了啊，","beginTime":170415,"endTime":171765,"channelId":0},{"speakerRole":"agent","index":93,"text":"嗯再见。","beginTime":171765,"endTime":172440,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:23:45','2026-05-22 00:23:49','2026-05-22 00:23:41','2026-05-22 00:23:49','system','system','BATCH-20260522-207060',NULL),
