me":57502,"channelId":0},{"speakerRole":"agent","index":37,"text":"好吧，","beginTime":57502,"endTime":57811,"channelId":0},{"speakerRole":"agent","index":38,"text":"对，","beginTime":57811,"endTime":57966,"channelId":0},{"speakerRole":"agent","index":39,"text":"备注一下，","beginTime":57966,"endTime":58586,"channelId":0},{"speakerRole":"agent","index":40,"text":"不好打了，","beginTime":58586,"endTime":59205,"channelId":0},{"speakerRole":"agent","index":41,"text":"你备注一下。","beginTime":59205,"endTime":59980,"channelId":0},{"speakerRole":"agent","index":42,"text":"嗯，","beginTime":60000,"endTime":60187,"channelId":0},{"speakerRole":"agent","index":43,"text":"好嘞好嘞，","beginTime":60187,"endTime":60937,"channelId":0},{"speakerRole":"agent","index":44,"text":"嗯那您那个嗯嗯，","beginTime":60937,"endTime":62250,"channelId":0},{"speakerRole":"agent","index":45,"text":"行行行好嘞好嘞，","beginTime":62250,"endTime":63562,"channelId":0},{"speakerRole":"agent","index":46,"text":"好，","beginTime":63562,"endTime":63750,"channelId":0},{"speakerRole":"agent","index":47,"text":"再见啊嗯。","beginTime":63750,"endTime":64500,"channelId":0}]}',100,NULL,NULL,0,0,3,'2026-05-22 00:24:18','2026-05-22 00:24:21','2026-05-22 00:24:13','2026-05-22 00:24:21','system','system','BATCH-20260522-207060',NULL),
